SELECT @bk_author,@bk_cat,'آیفون ۱۱ در سرما و با شارژ زیر ۳۰ درصد خاموش می‌شود','خاموشی ناگهانی آیفون در هوای سرد یا زیر ۳۰٪ شارژ تقریباً همیشه نشانهٔ فرسودگی باتری است، نه مشکل نرم‌افزاری.','وقتی باتری لیتیومی فرسوده می‌شود، مقاومت داخلی‌اش بالا می‌رود و در لحظه‌های مصرف زیاد یا سرما ولتاژش افت می‌کند؛ آیفون هم برای محافظت از خودش خاموش می‌شود. با بررسی سلامت باتری می‌توانید این موضوع را قطعی کنید.','آیفون ۱۱','آیفون','11','','خاموشی ناگهانی','easy','[{"title": "بررسی سلامت باتری", "body": "به تنظیمات › باتری › سلامت باتری و شارژ بروید. اگر ظرفیت زیر ۸۰٪ است یا پیام «سرویس باتری» می‌بینید، باتری باید تعویض شود."}, {"title": "تست با شارژر دیگری", "body": "قبل از تعویض، چند روز با کابل و شارژر سالم و اورجینال استفاده کنید تا مطمئن شوید مشکل از باتری است نه از شارژ نشدن کامل."}, {"title": "تعویض باتری با قطعه باکیفیت", "body": "باتری را فقط با نمونهٔ اورجینال یا گرید A با ضمانت تعویض کنید. قبل از جداسازی فلکس، شارژ گوشی را زیر ۲۵٪ ببرید تا در صورت شوک باتری، خطر کمتر شود."}, {"title": "کالیبره کردن باتری نو", "body": "بعد از تعویض، یک‌بار گوشی را از ۱۰۰٪ تا خاموشی کامل مصرف و بدون وقفه تا ۱۰۰٪ شارژ کنید تا درصد باتری دقیق شود."}]','پیچ‌گوشتی Pentalobe 0.8، پیچ‌گوشتی فیلیپس ۰۰۰، پیک پلاستیکی، ساکشن بازکنندهٔ صفحه','["/uploads/tips/mobile/open-iphone-repair.jpg", "/uploads/tips/gen/disconnect-battery-flex.jpg"]','','[]','free',0,'public','published','آیفون,باتری,خاموشی,سرما',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-10 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۱۱ در سرما و با شارژ زیر ۳۰ درصد خاموش می‌شود');

