SELECT @bk_author,@bk_cat,'درصد باتری آیفون ۱۲ یک‌دفعه از ۴۰ به ۱۵ می‌پرد','پرش ناگهانی درصد باتری یعنی متر حجمی باتری خراب شده یا باتری غیراصل نصب شده است.','آیفون درصد باتری را از روی منحنی یادگرفتهٔ مصرف محاسبه می‌کند. اگر باتری فرسوده باشد یا نمونهٔ تقلبی بدون قفل سلامت نصب شده باشد، عدد واقعی با نمایش اختلاف زیادی می‌دهد و درصد می‌پرد.','آیفون ۱۲','آیفون','12','','پرش درصد باتری','easy','[{"title": "بررسی پیام قطعهٔ ناشناس", "body": "در تنظیمات › باتری › سلامت باتری اگر پیام «قطعهٔ مهم ناشناس» یا «نمی‌توان تأیید کرد» می‌بینید، باتری غیراصل است و باید با نمونهٔ دارای قفل سلامت تعویض شود."}, {"title": "کالیبراسیون کامل", "body": "یک‌بار چرخهٔ کامل شارژ تا ۱۰۰٪ و مصرف تا خاموشی انجام دهید؛ اگر پرش ادامه داشت مشکل سخت‌افزاری است."}, {"title": "تعویض باتری با تراشهٔ اصلی", "body": "بهترین راه انتقال قفل سلامت از باتری قدیمی به جدید با جوشکاری تراشهٔ BMS است که فقط مراکز مجهز انجام می‌دهند."}, {"title": "بررسی رطوبت و خوردگی", "body": "اگر گوشی سابقهٔ آب‌خوردگی دارد، ترمینال باتری روی برد را با الکل ایزوپروپیل ۹۹٪ تمیز کنید؛ خوردگی هم همین علامت را می‌دهد."}]','الکل ایزوپروپیل ۹۹٪، برس ضداستاتیک، پیچ‌گوشتی ست کامل آیفون','["/uploads/tips/gen/swollen-battery.jpg", "/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','free',0,'public','published','آیفون,باتری,درصد',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-10 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'درصد باتری آیفون ۱۲ یک‌دفعه از ۴۰ به ۱۵ می‌پرد');

