SELECT @bk_author,@bk_cat,'آیفون ۱۳ هنگام شارژ و بازی بیش از حد داغ می‌شود','داغی ملایم هنگام شارژ طبیعی است، اما داغی شدید همراه با کندی یعنی باتری، شارژر یا پس‌زمینهٔ نرم‌افزاری مشکل دارد.','حرارت زیاد هم باتری را فرسوده می‌کند هم پردازنده را کم‌سرعت (Throttle) می‌کند. باید عامل گرما را دقیق پیدا کرد: شارژر تقلبی، قاب ضخیم، شارژ همزمان با بازی یا فرایند پنهان گوشی.','آیفون ۱۳','آیفون','13','','داغ شدن','medium','[{"title": "بخش تحلیل باتری را چک کنید", "body": "در تنظیمات › باتری ببینید کدام اپ بیشترین مصرف پس‌زمینه را دارد؛ اپ‌های مخرب یا قدیمی عامل رایج گرمای مزمن هستند."}, {"title": "شارژر را عوض کنید", "body": "با شارژر اورجینال یا دارای گواهی USB-PD تست کنید. شارژر تقلبی ولتاژ ناپایدار می‌دهد و هم باتری داغ می‌کند هم مدار شارژ."}, {"title": "بدون قاب و بدون استفاده شارژ کنید", "body": "قاب ضخیم حرارت را حبس می‌کند؛ هنگام شارژ سریع گوشی را بازی ندهید و قاب را بردارید."}, {"title": "به‌روزرسانی و ریست تنظیمات", "body": "اگر داغی بعد از یک آپدیت شروع شد، تنظیمات › عمومی › انتقال یا ریست آیفون › ریست تنظیمات را انجام دهید. اگر ادامه داشت، باتری و خمیر حرارتی صفحهٔ منطقی بررسی شود."}]','شارژر USB-PD اورجینال، نرم‌افزار مانیتور دما','["/uploads/tips/gen/charger-and-cable.jpg", "/uploads/tips/mobile/open-iphone-repair.jpg"]','https://www.aparat.com/v/gbpzjc7','[]','free',0,'public','published','آیفون,داغی,باتری,شارژ',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-10 19:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۱۳ هنگام شارژ و بازی بیش از حد داغ می‌شود');

INSERT INTO tips (author_id,category_id,title,short_description,description,device_name,brand,model,board_number,fault_type,difficulty,solution_json,tools,images_json,video_url,attachments_json,access_type,price,visibility,status,tags,version,versions_json,featured,views,likes_count,purchases_count,rating_sum,rating_count,duplicate_of,rejection_reason,source_url,source_name,published_at)
SELECT @bk_author,@bk_cat,'بیرون زدن صفحهٔ آیفون X از بدنه — باتری متورم را فوری تعویض کنید','اگر صفحه یا شیشهٔ پشت گوشی بالا آمد، باتری متورم شده؛ ادامهٔ استفاده خطر نشت و آتش‌سوزی دارد.','تورم باتری لیتیومی یعنی گاز داخل کیسهٔ باتری تولید شده. با فشار دادن یا سوراخ کردن، باتری می‌تواند شعله‌ور شود. کار باید با احتیاط کامل و ابزار مناسب انجام شود.','آیفون ایکس','آیفون','X','','باتری متورم','hard','[{"title": "شارژ را قطع و گوشی را خاموش کنید", "body": "دیگر شارژ نکنید. اگر گوشی روشن است آن را خاموش و از قاب خارج کنید؛ گوشی را فشار ندهید و روی آن وزن نگذارید."}, {"title": "خارج کردن باتری با چسب‌کش", "body": "در آیفون X باتری با نوارهای چسب کشی (Pull Tabs) نگه داشته شده؛ با کشیدن آرام و موازی سطح، نوارها را بیرون بیاورید. اگر نوار پاره شد، چند قطره الکل ایزوپروپیل زیر باتری بریزید و با کارت پلاستیکی آرام جدا کنید."}, {"title": "هرگز با فلز زیر باتری نروید", "body": "فشار یا سوراخ شدن کیسهٔ باتری باعث اشتعال می‌شود. باتری متورم را در ظرف فلزی یا شنی نگه دارید و طبق مقررات دفع کنید."}, {"title": "نصب باتری اصل و تست نهایی", "body": "باتری نو را با نوار چسب نو نصب کنید و بعد از بستن، سلامت باتری و شارژدهی را تست کنید. آب‌بندی با واشر جدید انجام شود."}]','الکل ایزوپروپیل، کارت پلاستیکی، پنس پلاستیکی، ظرف فلزی برای باتری خراب','["/uploads/tips/gen/swollen-battery.jpg", "/uploads/tips/gen/disconnect-battery-flex.jpg"]','','[]','like',0,'public','published','آیفون,باتری متورم,تورم,خطر',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-10 20:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بیرون زدن صفحهٔ آیفون X از بدنه — باتری متورم را فوری تعویض کنید');

