SELECT @bk_author,@bk_cat,'آیفون ۷ با شارژ زیر ۲۰ درصد خاموش می‌شود — علامت کلاسیک باتری مرده','این رفتار در آیفون ۷ و ۷ پلاس فوق‌العاده شایع است و با تعویض باتری کاملاً برطرف می‌شود.','آیفون ۷ چند سال از بازار آمده و باتری‌هایش به پایان عمر رسیده‌اند. افت ولتاژ زیر فشار باعث خاموشی در دماهای پایین یا مصرف‌های لحظه‌ای می‌شود.','آیفون ۷','آیفون','7','','خاموش شدن زیر ۲۰ درصد','easy','[{"title": "تأیید فرسودگی", "body": "سلامت باتری زیر ۸۰٪ یعنی وقت تعویض است. اگر بالای ۸۰٪ ولی مشکل هست، باتری ممکن است تقلبی یا تعویض‌شده با نمونهٔ بی‌کیفیت باشد."}, {"title": "بستن اپ‌های پرمصرف", "body": "تا زمان تعویض، مصرف لحظه‌ای را با بستن اپ‌های پس‌زمینه و کاهش روشنایی کم کنید تا خاموشی دیرتر رخ دهد."}, {"title": "تعویض باتری با رعایت نکات آیفون ۷", "body": "در آیفون ۷ پشت صفحه‌نمایش باید برداشته شود و واشر ضدآب حول صفحه است؛ هنگام باز کردن از پیک پلاستیکی استفاده کنید تا کابل نمایشگر آسیب نبیند."}, {"title": "تست نهایی", "body": "بعد از تعویض گوشی را یک روز کامل استفاده کنید؛ خاموشی زیر ۲۰٪ نباید تکرار شود."}]','ست پیچ‌گوشتی آیفون، ساکشن، پیک','["/uploads/tips/mobile/open-iphone-repair.jpg"]','https://www.aparat.com/v/fj7v2','[]','free',0,'public','published','آیفون ۷,باتری,خاموشی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-11 00:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۷ با شارژ زیر ۲۰ درصد خاموش می‌شود — علامت کلاسیک باتری مرده');

