SELECT @bk_author,@bk_cat,'آیفون ۶S هنگام باز کردن دوربین ریست می‌شود (شوک باتری)','ریستارت لحظهٔ باز شدن دوربین نشانهٔ افت ناگهانی ولتاژ باتری است؛ تعویض باتری مشکل را حل می‌کند.','دوربین یکی از پرمصرف‌ترین ماژول‌هاست و لحظهٔ فعال شدن جریان زیادی می‌کشد. باتری فرسوده این جریان را تأمین نمی‌کند و برد برای محافظت ریست می‌کند.','آیفون ۶اس','آیفون','6S','','ریستارت خودکار','medium','[{"title": "تست تشخیصی ساده", "body": "دوربین را در حالت شارژ کامل باز کنید؛ اگر ریست نشد ولی با شارژ متوسط شد، باتری مقصر است."}, {"title": "تعویض باتری", "body": "باتری اورجینال یا گرید A با کیفیت نصب کنید. قبل از نصب ترمینال باتری روی برد را بازرسی کنید که خوردگی یا قطرهٔ لحیم نداشته باشد."}, {"title": "اگر با باتری نو حل نشد", "body": "سوییچ دیسکریت روی برد یا خط رمزگذاری شارژ را بررسی کنید؛ در آیفون‌های قدیمی خوردگی دور ترمینال رایج است."}]','ست باز کردن آیفون، پنس، الکل ایزوپروپیل','["/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','free',0,'public','published','آیفون,ریستارت,دوربین,باتری',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-11 04:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۶S هنگام باز کردن دوربین ریست می‌شود (شوک باتری)');

