SELECT @bk_author,@bk_cat,'آیفون SE دیر شارژ می‌شود — از کجا شروع کنیم؟','شارژ کند معمولاً ترکیب کابل/شارژر غیراصل، پورت کثیف یا خاموش بودن شارژ سریع است.','آیفون SE با شارژر ۱۸ وات به بالا در حدود ۹۰ دقیقه پر می‌شود. اگر زمان شارژ خیلی بیشتر است، ساده‌ترین علت‌ها را اول بررسی کنید.','آیفون SE ۲۰۲۰','آیفون','SE','','شارژ آهسته','easy','[{"title": "پورت لایتنینگ را تمیز کنید", "body": "با خلال چوبی یا برس نرم آرام پرز و گردوغبار داخل پورت را بیرون بیاورید. فلز با جسم نوک‌تیز وارد نکنید."}, {"title": "کابل و شارژر را تست کنید", "body": "با کابل و آداپتور سالم دیگر تست کنید؛ سیم‌های شکستهٔ داخلی کابل بدون آنکه بیرون معلوم باشد جریان را کم می‌کنند."}, {"title": "شارژ سریع را تأیید کنید", "body": "شارژ سریع آیفون فقط با شارژر USB-PD و کابل USB-C به لایتنینگ فعال می‌شود؛ شارژر ۵ وات قدیمی طبیعتاً کند است."}, {"title": "بررسی نرم‌افزاری", "body": "اگر همه‌چیز سالم بود، ریست تنظیمات را انجام دهید؛ گاهی خطای نرم‌افزاری مدیریت شارژ باعث محدود شدن جریان می‌شود."}]','','["/uploads/tips/gen/wet-usb-port.jpg", "/uploads/tips/gen/charger-and-cable.jpg"]','','[]','free',0,'public','published','آیفون,شارژ کند,پورت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-11 07:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون SE دیر شارژ می‌شود — از کجا شروع کنیم؟');

