SELECT @bk_author,@bk_cat,'بعد از آپدیت iOS مصرف باتری آیفون ۱۴ بالا رفته است','چند روز بعد از آپدیت مصرف بالا طبیعی است؛ اگر ادامه یافت، اپ پرمصرف پس‌زمینه را پیدا و محدود کنید.','بعد از نصب iOS جدید، سیستم چند روز در پس‌زمینه ایندکس می‌سازد و اپ‌ها خود را بهینه می‌کنند؛ این دوره مصرف بالایی دارد. مشکل مزمن معمولاً از تنظیمات یا باتری فرسوده است.','آیفون ۱۴','آیفون','14','','مصرف باتری بالا','easy','[{"title": "۴۸ ساعت صبر کنید", "body": "این رفتار موقتی است؛ در این مدت گوشی را شبانه شارژ کامل کنید."}, {"title": "تحلیل مصرف", "body": "در تنظیمات › باتری، مصرف اپ‌ها را در ۲۴ ساعت ببینید؛ اپ مشکوک را پس‌زمینه‌اش را خاموش کنید."}, {"title": "خدمات موقعیت‌محور را محدود کنید", "body": "Location روی «هنگام استفاده» تنظیم شود و Background App Refresh را برای اپ‌های غیرضروری ببندید."}, {"title": "ریست تنظیمات به‌عنوان راه آخر", "body": "اگر مصرف بالا ماند، ریست تنظیمات بدون پاک کردن داده‌ها مشکل را حل می‌کند. اگر باز هم حل نشد سلامت باتری را ببینید."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','like',0,'public','published','آیفون,مصرف باتری,آپدیت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-11 10:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بعد از آپدیت iOS مصرف باتری آیفون ۱۴ بالا رفته است');

