SELECT @bk_author,@bk_cat,'تعویض نمایشگر شکستهٔ آیفون ۱۲ به روش اصولی','برای تعویض پنل آیفون ۱۲ باید از پایین گرم و باز شود و بعد از تعویض، قفل قطعات با تراشه اصلی منتقل شود.','نمایشگر آیفون ۱۲ با چسب و پیچ به بدنه وصل است و کابل‌هایش از پایین برداشته می‌شوند. مهم‌ترین نکتهٔ حرفه‌ای‌ها، انتقال تراشهٔ کوچک روی پنل قدیمی به پنل جدید است تا پیام قطعهٔ ناشناس نیاید و True Tone حفظ شود.','آیفون ۱۲','آیفون','12','','شکستن نمایشگر','hard','[{"title": "خاموش کردن و باز کردن پیچ‌های پایین", "body": "دو پیچ Pentalobe کنار پورت شارژ را باز کنید و با حرارت ملایم و ساکشن، نمایشگر را آرام بالا بکشید."}, {"title": "جداسازی باتری اول", "body": "اول فلکس باتری را جدا کنید؛ بعد فلکس‌های نمایشگر و Face ID. ترتیب مهم است تا اتصال کوتاه پیش نیاید."}, {"title": "انتقال سنسور و براکت", "body": "بلندگو، میکروفون و سنسور محیطی از پنل قدیمی به جدید منتقل شوند و روی پنل جدید، تراشهٔ نمایشگر قدیمی جوش داده شود (برای حفظ True Tone و رفع پیام قطعهٔ ناشناس)."}, {"title": "بستن و تست", "body": "قبل از بستن کامل، گوشی را روشن و تاچ، رنگ، True Tone و روشنایی خودکار را تست کنید؛ بعد واشر آب‌بندی نو بگذارید."}]','هیتر یا سشوار صنعتی، ساکشن، ست پیچ‌گوشتی، واشر آب‌بندی نو','["/uploads/tips/gen/cracked-display.jpg", "/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','paid',65000,'public','published','آیفون,نمایشگر,تعویض صفحه',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-11 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض نمایشگر شکستهٔ آیفون ۱۲ به روش اصولی');

