SELECT @bk_author,@bk_cat,'تاچ خودبه‌خودی (Ghost Touch) آیفون ۱۱ بعد از تعویض غیراصل نمایشگر','اگر بعد از تعویض صفحه، لمس‌های خیالی دارید، به احتمال زیاد پنل بی‌کیفیت یا سیم‌کشی نادرست عامل است.','پنل‌های ارزان برای آیفون ۱۱ درجهٔ لمس پایینی دارند و با گرمای شارژ یا تابش آفتاب تاچ ناپایدار می‌شود. گاهی هم چسب زیر پنل روی مسیر سنسور اثر گذاشته است.','آیفون ۱۱','آیفون','11','','گوست تاچ','hard','[{"title": "تست با پنل اورجینال", "body": "سریع‌ترین راه تشخیص، نصب پنل سالم اورجینال یا گرید اصلی است؛ اگر تاچ خیالی رفت، پنل قبلی مشکل داشته."}, {"title": "بررسی کانکتورها", "body": "کانکتورهای نمایشگر و Touch IC را دوباره جا بزنید؛ پین کج یا چربی روی سوکت تاچ ناپایدار می‌دهد."}, {"title": "بررسی صفحهٔ خمیده", "body": "اگر بدنه گوشی خم شده باشد، پنل زیر فشار تاچ خیالی می‌دهد؛ با خط‌کش صافی قاب را چک کنید."}, {"title": "رفع خمیدگی و تعویض پنل", "body": "بدنه خمیده در دستگاه سیم‌بول (Straightener) صاف و پنل باکیفیت نصب شود."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','آیفون,گوست تاچ,نمایشگر',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-11 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تاچ خودبه‌خودی (Ghost Touch) آیفون ۱۱ بعد از تعویض غیراصل نمایشگر');

