SELECT @bk_author,@bk_cat,'خطوط رنگی روی صفحهٔ آیفون ۸ بعد از ضربه','خطوط عمودی یا لکه بعد از ضربه معمولاً یعنی پنل آسیب دیده؛ گاهی هم فقط کانکتور جا کامل نیفتاده.','ضربه می‌تواند IC نمایشگر یا کابل‌ها را آسیب بزند. اول ارزان‌ترین علت (کانکتور) را بررسی کنید، بعد سراغ تعویض پنل بروید.','آیفون ۸','آیفون','8','','خطوط صفحه','medium','[{"title": "ریست اجباری", "body": "دکمهٔ خاموش + کم کردن صدا را ۱۰ ثانیه نگه دارید؛ اگر خطوط بعد ریست رفت، مشکل نرم‌افزاری یا موقت بوده."}, {"title": "باز کردن و جازدن کانکتورها", "body": "گوشی را باز و کانکتور نمایشگر را با فشار متعادل جا بزنید؛ گاهی خطوط با این کار رفع می‌شود."}, {"title": "تعویض نمایشگر", "body": "اگر خطوط ماند، پنل آسیب دیده و باید تعویض شود؛ پنل با تراشهٔ اصلی بگیرید تا پیام قطعهٔ ناشناس نیاید."}, {"title": "اگر با پنل سالم خطوط ماند", "body": "مشکل از برد یا IC نمایشگر است که تعمیر تخصصی برد لازم دارد."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','آیفون,خطوط صفحه,ضربه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-11 17:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'خطوط رنگی روی صفحهٔ آیفون ۸ بعد از ضربه');

