SELECT @bk_author,@bk_cat,'ناحیه‌ای از صفحهٔ آیفون ۱۳ پرو به لمس جواب نمی‌دهد','ناحیهٔ مردهٔ لمس می‌تواند از پنل، محافظ صفحه یا حتی قاب ضخیم باشد؛ مرحله‌به‌مرحله عیب‌یابی کنید.','سنسور لمس در تمام پنل یکپارچه است؛ ناحیهٔ مشخصی که جواب نمی‌دهد یعنی آسیب موضعی سنسور یا مشکل جسمی روی آن ناحیه.','آیفون ۱۳ پرو','آیفون','13 Pro','','لمس ناقص','medium','[{"title": "محافظ صفحه را بردارید", "body": "محافظ بی‌کیفیت یا حباب‌دار، الکترودها را اغتشاش می‌دهد؛ بدون محافظ تست کنید."}, {"title": "تست نقشهٔ لمس", "body": "در حالت تعمیرکاری (یا اپ تست لمس) ناحیه‌های مرده را مشخص کنید؛ یک‌نقطهٔ ثابت یعنی آسیب سنسور."}, {"title": "جازدن کانکتور نمایشگر", "body": "باز کنید و فلکس لمس را دوباره جا بزنید؛ اکسیدیشن سوکت همین علامت را می‌دهد."}, {"title": "تعویض پنل", "body": "اگر مشکل ماند، سنسور نمایشگر معیوب است و تعویض پنل لازم است؛ برای آیفون ۱۳ پرو پنل ۱۲۰ هرتز اورجینال بگیرید."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','like',0,'public','published','آیفون,لمس,نمایشگر',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-11 20:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ناحیه‌ای از صفحهٔ آیفون ۱۳ پرو به لمس جواب نمی‌دهد');

