SELECT @bk_author,@bk_cat,'آیفون X صفحه مشکی دارد ولی گوشی روشن است (صدای اعلان می‌آید)','صفحهٔ مشکی با کارکرد صدا در آیفون X معمولاً از پارگی فلکس نمایشگر یا آسیب OLED است.','در آیفون X فلکس‌های نمایشگر حساس‌اند؛ ضربه یا خمیدگی بدنه پارگی مسیر فلکس را ایجاد می‌کند که تصویر را کامل قطع می‌کند ولی صدا و لمس گاهی کار می‌کند.','آیفون ایکس','آیفون','X','','صفحه سیاه','hard','[{"title": "تست کارکرد با صدا", "body": "یک پیام صوتی بفرستید؛ اگر صدای اعلان می‌آید یعنی گوشی روشن است و مشکل فقط نمایشگر است."}, {"title": "باز کردن و بازرسی فلکس", "body": "فلکس نمایشگر را از نظر پارگی یا خط سفید شکستگی بررسی کنید؛ ناحیهٔ خمشدگی معمولاً کنار بدنه است."}, {"title": "تعویض پنل OLED", "body": "پنل سالم اورجینال نصب کنید؛ برای حفظ True Tone تراشهٔ اصلی منتقل شود."}, {"title": "بررسی نهایی بدنه", "body": "اگر بدنه خم است، صاف‌کاری و تست مجدد انجام شود تا پنل جدید هم آسیب نبیند."}]','','["/uploads/tips/gen/cracked-display.jpg", "/uploads/tips/mobile/phone-circuit-repair.jpg"]','','[]','free',0,'public','published','آیفون X,صفحه مشکی,OLED',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-11 23:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون X صفحه مشکی دارد ولی گوشی روشن است (صدای اعلان می‌آید)');

