SELECT @bk_author,@bk_cat,'آیفون ۷ صفحهٔ سفید (White Screen) هنگام روشن شدن','صفحهٔ سفید یا خطوط سفید می‌تواند از پنل، کانکتور یا در موارد نادر برد باشد؛ به ترتیب تست کنید.','اول نرم‌افزار را رد کنید (ریست اجباری)، بعد سخت‌افزار ساده (کانکتور)، آخر پنل و برد. این ترتیب هزینهٔ تعمیر را کم می‌کند.','آیفون ۷','آیفون','7','','صفحه سفید','medium','[{"title": "ریست اجباری", "body": "خاموش + کم‌کردن صدا را تا لوگوی اپل نگه دارید."}, {"title": "کانکتور نمایشگر", "body": "باز کنید و کانکتورها را با تمیزکاری الکل، جا بزنید."}, {"title": "تعویض پنل", "body": "پنل سالم بگذارید؛ اگر سفیدی رفت، پنل قبلی خراب بوده."}, {"title": "تعمیر برد", "body": "اگر با پنل سالم مشکل ماند، مسیر سیگنال نمایشگر روی برد بررسی شود (تخصصی)."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','آیفون,صفحه سفید',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-12 05:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۷ صفحهٔ سفید (White Screen) هنگام روشن شدن');

