SELECT @bk_author,@bk_cat,'آیفون ۱۳ شارژ نمی‌شود — عیب‌یابی کامل از ارزان به گران','۹۰٪ موارد شارژ نشدن از پورت کثیف، کابل خراب یا شارژر بی‌کیفیت است؛ برد آخرین گزینه است.','قبل از هر هزینه‌ای این ترتیب را اجرا کنید: پورت › کابل/شارژر › نرم‌افزار › سخت‌افزار. با این روش بدون هزینه اکثر موارد حل می‌شود.','آیفون ۱۳','آیفون','13','','شارژ نمی‌شود','medium','[{"title": "تمیزکاری پورت لایتنینگ", "body": "با نور قوی داخل پورت را ببینید؛ پرز لباس با خلال یا برس نرم بیرون بیاورید. پرز فشرده رایج‌ترین علت است."}, {"title": "تست با ست شارژ دیگر", "body": "کابل و شارژر اورجینال دیگر (ترجیحاً USB-PD) تست کنید؛ کابل‌های بی‌کیفیت بعد مدتی از کار می‌افتند."}, {"title": "ریست تنظیمات و آپدیت iOS", "body": "اگر آیفون پیام «لوازم جانبی تأیید نمی‌شود» می‌دهد، آپدیت iOS و ریست تنظیمات را انجام دهید."}, {"title": "بازکردن و بررسی مدار شارژ", "body": "اگر همه سالم بود، فلکس پورت لایتنینگ ارزان است و تعویضش ساده است؛ بعد از آن اگر باز شارژ نشد، IC شارژ (Tristar/Hydra) روی برد باید تعمیر شود."}]','خلال، برس نرم، الکل ایزوپروپیل، مولتی‌متر','["/uploads/tips/gen/wet-usb-port.jpg"]','','[]','free',0,'public','published','آیفون,شارژ,پورت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-12 13:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۱۳ شارژ نمی‌شود — عیب‌یابی کامل از ارزان به گران');

