SELECT @bk_author,@bk_cat,'پیام «رطوبت در کانکتور شناسایی شد» در آیفون — چه کنیم؟','آیفون برای محافظت شارژ را قطع می‌کند؛ صبوری و خشک کردن صحیح، بهتر از هر ترفند خانگی است.','سنسور رطوبت پورت لایتنینگ با تماس آب فعال می‌شود و شارژ قطع می‌شود تا خوردگی پیش نیاید. سشوار داغ یا فشار هوا پرهیز کنید چون رطوبت را عمیق‌تر می‌برد.','آیفون ۱۲','آیفون','12','','پیام رطوبت','easy','[{"title": "شارژر را جدا و پورت را با آب نچکان پارچه خشک کنید", "body": "گوشی را با پورت رو به پایین بگیرید و آرام تکان دهید تا قطره‌ها بیفتند."}, {"title": "در هوای آزاد یا جلوی فن بگذارید", "body": "چند ساعت در محیط خشک یا جلوی هوای خنک فن. برنج هم کار می‌کند ولی کند است و خرده‌برنج می‌تواند داخل پورت برود."}, {"title": "صبر کنید", "body": "حداقل ۳۰ دقیقه تا چند ساعت؛ پیام تا خشک شدن کامل تکرار می‌شود."}, {"title": "اگر پیام ماند", "body": "سنسور یا پورت ممکن است خورده باشد؛ فلکس پورت تعویض شود (هزینهٔ کم). اگر گوشی داخل آب افتاده بود، حتماً باز و خشک‌کاری حرفه‌ای شود."}]','','["/uploads/tips/gen/wet-usb-port.jpg", "/uploads/tips/gen/phone-in-rice.jpg"]','','[]','paid',55000,'public','published','آیفون,رطوبت,پورت',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-12 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'پیام «رطوبت در کانکتور شناسایی شد» در آیفون — چه کنیم؟');

