SELECT @bk_author,@bk_cat,'آیفون ۱۱ فقط با زاویهٔ خاصی از کابل شارژ می‌شود','این یعنی کانکتور پورت شل شده یا لحیم پایه‌هایش ترک خورده؛ تعویض فلکس پورت ساده و ارزان است.','با تکان خوردن مکرر کابل، پایه‌های لحیم فلکس پورت شکستگی خستگی (Fatigue) پیدا می‌کنند. در آیفون ۱۱ فلکس پورت با چند پیچ قابل تعویض است.','آیفون ۱۱','آیفون','11','','شارژ با زاویه','medium','[{"title": "تأیید عیب از روی کابل", "body": "با کابل سالم دیگر هم تست کنید تا مطمئن شوید مشکل از گوشی است نه کابل."}, {"title": "تعویض فلکس پورت لایتنینگ", "body": "پیچ‌های پایین را باز، نمایشگر را بالا، باتری را جدا و فلکس پورت را تعویض کنید. قطعه ارزان و در بازار موجود است."}, {"title": "تمیزکاری سوکت", "body": "قبل از بستن، سوکت‌ها را با الکل تمیز کنید و فلکس نو را محکم جا بزنید."}, {"title": "تست نهایی", "body": "شارژ سیمی، انتقال داده و میکروفون پایین گوشی (روی همان فلکس است) را تست کنید."}]','','["/uploads/tips/gen/wet-usb-port.jpg", "/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','آیفون,پورت شارژ,فلکس',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-12 19:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۱۱ فقط با زاویهٔ خاصی از کابل شارژ می‌شود');

