SELECT @bk_author,@bk_cat,'شارژ بی‌سیم MagSafe در آیفون ۱۴ پرو کار نمی‌کند','قاب ضخیم، فلز یا آهنربای اضافه و گرمای زیاد سه عامل اصلی کار نکردن شارژ بی‌سیم هستند.','شارژ بی‌سیم حساس به فاصله و حرارت است؛ آیفون اگر داغ شود توان را کم می‌کند یا قطع می‌کند. قبل از تعمیر، محیط را بهینه کنید.','آیفون ۱۴ پرو','آیفون','14 Pro','','شارژ بی‌سیم','medium','[{"title": "قاب را بردارید", "body": "قاب‌های ضخیم، فلزی یا آهنربادار روی کویل اثر می‌گذارند؛ بدون قاب تست کنید."}, {"title": "با شارژر MagSafe اصل تست کنید", "body": "شارژرهای بی‌کیفیت توان پایدار ندارند؛ با شارژر ۲۰ وات + کابل اصل MagSafe یا Qi2 تست کنید."}, {"title": "دمای گوشی را کنترل کنید", "body": "در حالت داغ، شارژ بی‌سیم متوقف می‌شود؛ گوشی را خنک کنید و دوباره تست کنید."}, {"title": "بازرسی کویل", "body": "اگر باز هم کار نکرد، اتصال کویل شارژ بی‌سیم روی برد بررسی شود (تخصصی)."}]','','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','like',0,'public','published','آیفون,شارژ بی‌سیم,MagSafe',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-12 22:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'شارژ بی‌سیم MagSafe در آیفون ۱۴ پرو کار نمی‌کند');

