SELECT @bk_author,@bk_cat,'پورت Type-C آیفون ۱۵ شل شده و کابل می‌افتد','پورت Type-C با هزاران بار وصل/جدا استهلاک می‌یابد؛ تعویض فلکس پورت راه‌حل قطعی است.','خم شدن پین‌ها یا گشاد شدن فنر مرکزی Type-C باعث اتصال ناپایدار می‌شود. در آیفون ۱۵ پورت روی فلکس مستقل است و تعویضش آسان است.','آیفون ۱۵','آیفون','15','','پورت Type-C شل','medium','[{"title": "تأیید مشکل با چند کابل", "body": "با چند کابل مختلف تست کنید؛ اگر همه شل‌اند، پورت گوشی مشکل دارد."}, {"title": "تعویض فلکس پورت", "body": "باتری را جدا، فلکس پورت را باز و با نمونهٔ اورجینال تعویض کنید."}, {"title": "تست انتقال داده", "body": "آیفون ۱۵ فقط با پورت سالم داده USB 2 انتقال می‌دهد؛ بعد از تعویض، انتقال فایل را هم تست کنید."}, {"title": "نکتهٔ نگهداری", "body": "کابل را همیشه مستقیم بکشید نه با زاویه؛ عمر پورت چند برابر می‌شود."}]','','["/uploads/tips/gen/wet-usb-port.jpg"]','','[]','free',0,'public','published','آیفون ۱۵,Type-C,پورت',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-13 01:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'پورت Type-C آیفون ۱۵ شل شده و کابل می‌افتد');

