SELECT @bk_author,@bk_cat,'لرزش و صدای تق‌تق دوربین آیفون ۱۳ پرو (مشکل OIS)','لرزش مداوم ماژول دوربین معمولاً از آسیب مکانیکی رینگ OIS است؛ گاهی با آپدیت و ریست رفع می‌شود.','سیستم لرزشگیر اپتیکال با آهنربا و فنر کار می‌کند؛ ضربه یا آب‌خوردگی چرخهٔ لرزش را به هم می‌ریزد. گاهی هم نرم‌افزار با ریست اجباری تنظیم می‌شود.','آیفون ۱۳ پرو','آیفون','13 Pro','','لرزش دوربین','hard','[{"title": "ریست اجباری و آپدیت iOS", "body": "دکمهٔ کم‌کردن صدا + روشن را نگه دارید؛ بعد iOS را آپدیت کنید. چند مورد با همین کار حل شده است."}, {"title": "تست در حالت Safe", "body": "اپ دوربین و اپ ثالث دوربین را جدا تست کنید؛ اگر فقط یک اپ مشکل دارد نرم‌افزاری است."}, {"title": "باز کردن و بررسی ماژول", "body": "اگر مشکل ماند، دوربین باز شود؛ تراشهٔ ریز روی ماژول و مسیر فلکس بررسی و ماژول نو نصب شود."}, {"title": "نکتهٔ اپل", "body": "در برخی آیفون ۱۳ پرو اپل این مشکل را با تعویض رایگان پذیرفته بود؛ اگر گارانتی/خدمات اپل در دسترس است اول آن را امتحان کنید."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg", "/uploads/tips/mobile/phone-circuit-repair.jpg"]','','[]','free',0,'public','published','آیفون,دوربین,لرزش,OIS',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-13 02:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'لرزش و صدای تق‌تق دوربین آیفون ۱۳ پرو (مشکل OIS)');

