SELECT @bk_author,@bk_cat,'ترک خوردن شیشهٔ لنز دوربین آیفون ۱۱ — تعویض شیشه یا ماژول؟','اگر عکس‌ها سالم‌اند فقط شیشهٔ بیرونی ترک دارد، تعویض شیشه با لیزر ارزان‌تر است؛ اگر تصویر تار شد، ماژول تعویض می‌شود.','شیشهٔ لنز با چسب مخصوص روی ماژول چسبیده است. جدا کردن بدون لیزر ریسک شکستن ماژول دارد؛ مراکز مجهز با لیزر و قالب انجام می‌دهند.','آیفون ۱۱','آیفون','11','','ترک لنز دوربین','medium','[{"title": "بررسی کیفیت عکس", "body": "اگر تاری، لکه یا نویز نیست، فقط شیشه ترک خورده و تعویض شیشه کافی است."}, {"title": "تعویض شیشه با لیزر", "body": "با دستگاه لیزر دور چسب بریده و شیشه جدا می‌شود؛ شیشهٔ نو با چسب UV نصب می‌شود."}, {"title": "تعویض ماژول در صورت آسیب", "body": "اگر عکس تار است یا گرد و خاک داخل لنز رفته، ماژول دوربین تعویض شود؛ ماژول آیفون ۱۱ در بازار موجود است."}, {"title": "آب‌بندی مجدد", "body": "بعد از هر تعمیر دوربین، واشر آب‌بندی نو گذاشته شود."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','free',0,'public','published','آیفون,دوربین,ترک لنز',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-13 05:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ترک خوردن شیشهٔ لنز دوربین آیفون ۱۱ — تعویض شیشه یا ماژول؟');

