SELECT @bk_author,@bk_cat,'دوربین آیفون ۱۲ تار عکس می‌گیرد — قبل از تعمیر این‌ها را تست کنید','تاری دوربین اغلب از چربی، خراش شیشه یا فوکوس قفل‌شده است؛ تعمیرگاه آخرین مرحله است.','ساده‌ترین علت‌ها را حذف کنید: اثر انگشت روی لنز، محافظ صفحهٔ دوربین، اپ ضبط ثالث و تنظیمات فرمت عکس.','آیفون ۱۲','آیفون','12','','دوربین تار','easy','[{"title": "تمیز کردن لنز", "body": "با پارچهٔ میکروفایبر تمیز کنید؛ چربی انگشت رایج‌ترین علت تاری است."}, {"title": "ریست دوربین", "body": "اپ دوربین را از بین اپ‌های باز ببندید و دوباره باز کنید؛ ریست اجباری هم بزنید."}, {"title": "تست فوکوس", "body": "روی موضوع نزدیک و دور را با ضربه فوکوس کنید؛ اگر فوکوسگیر کار نمی‌کند، ماژول مشکل دارد."}, {"title": "تعویض ماژول", "body": "اگر همه سالم بود و تاری ماند، ماژول دوربین تعویض شود."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','like',0,'public','published','آیفون,دوربین تار',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-13 10:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'دوربین آیفون ۱۲ تار عکس می‌گیرد — قبل از تعمیر این‌ها را تست کنید');

