SELECT @bk_author,@bk_cat,'فلش دوربین آیفون ۸ کار نمی‌کند','فلش و چراغق (Torch) روی همان مدار هستند؛ اگر هر دو کار نمی‌کنند معمولاً فلکس یا ماژول فلش معیوب است.','اول مطمئن شوید حالت کم‌مصرف یا دمای بالای گوشی فلش را قفل نکرده است؛ سپس سراغ سخت‌افزار بروید.','آیفون ۸','آیفون','8','','فلش دوربین','medium','[{"title": "بررسی دما و حالت کم‌مصرف", "body": "آیفون داغ فلش را غیرفعال می‌کند؛ گوشی را خنک کنید و حالت کم‌مصرف را خاموش کنید."}, {"title": "تست با چراغق", "body": "کنترل مرکز › چراغق را بزنید؛ روشن نشدن آن هم مشکل مدار فلش را تأیید می‌کند."}, {"title": "بازکردن و بررسی فلکس فلش", "body": "فلکس فلش (روی درب پشت) بازرسی و تعویض شود."}, {"title": "تعویض ماژول فلش", "body": "اگر فلکس سالم بود، ماژول LED تعویض شود؛ در صورت ادامه، مسیر برد تخصصی بررسی می‌شود."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','free',0,'public','published','آیفون,فلش,چراغق',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-13 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'فلش دوربین آیفون ۸ کار نمی‌کند');

