SELECT @bk_author,@bk_cat,'دوربین جلوی آیفون ۱۴ بعد از ضربه کار نمی‌کند','دوربین جلو (FaceTime) پشت نمایشگر است؛ تعویض آن همراه با باز کردن صفحه انجام می‌شود.','فلکس دوربین جلو با سنسور Face ID هم‌زمان در یک ماژول است؛ در تعویض باید مراقب بود ماژول سنسور جابجا نشود چون کالیبراسیون Face ID کارخانه‌ای است.','آیفون ۱۴','آیفون','14','','دوربین جلو','medium','[{"title": "تفکیک مشکل نرم‌افزار", "body": "اپ دوربین را ببندید، ریست اجباری بزنید و آپدیت iOS را انجام دهید."}, {"title": "باز کردن نمایشگر", "body": "نمایشگر از پایین باز شود تا دسترسی به ماژول دوربین جلو باز شود."}, {"title": "تعویض ماژول دوربین جلو", "body": "ماژول نو نصب شود؛ فلکس‌ها را با برچسب از پیش جدا نکنید (Face ID کنارش است)."}, {"title": "تست و بستن", "body": "دوربین جلو، حالت شبانه و سلفی تست و گوشی با واشر نو بسته شود."}]','','["/uploads/tips/gen/cracked-display.jpg", "/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','free',0,'public','published','آیفون,دوربین جلو',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-13 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'دوربین جلوی آیفون ۱۴ بعد از ضربه کار نمی‌کند');

