SELECT @bk_author,@bk_cat,'آیفون ۱۲ هر چند دقیقه خودش ریستارت می‌شود','ریستارت تکراری یا از حلقهٔ نرم‌افزاری است یا از اتصال سخت‌افزاری مثل فلکس باتری؛ به ترتیب عیب‌یابی کنید.','گزارش کرش‌ها در تنظیمات › حریم خصوصی › تحلیل، عامل را نشان می‌دهد. اگر پانیک کرنل باشد مشکل سخت‌افزاری است.','آیفون ۱۲','آیفون','12','','ریستارت مکرر','medium','[{"title": "خواندن گزارش کرش", "body": "تحلیل و بهبودها › دادهٔ تحلیل؛ اگر Crash در Kernel/Panic باشد سخت‌افزاری است، اگر در یک اپ باشد نرم‌افزاری."}, {"title": "ریست اجباری و آپدیت", "body": "ریست اجباری بزنید و iOS را به آخرین نسخه آپدیت کنید."}, {"title": "بازرسی فلکس باتری و برد", "body": "باز کنید و فلکس باتری و پیچ‌های زمین را بررسی کنید؛ پیچ گم‌شده یا فلکس شل رایج است."}, {"title": "تعویض باتری به‌عنوان تست", "body": "باتری سالم بگذارید؛ اگر ریستارت ماند، تعمیر برد تخصصی لازم است."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg", "/uploads/tips/mobile/board-macro-afem.jpg"]','','[]','like',0,'public','published','آیفون,ریستارت,کرش',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-13 20:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۱۲ هر چند دقیقه خودش ریستارت می‌شود');

