SELECT @bk_author,@bk_cat,'رمز آیفون ۱۱ را فراموش کرده‌ام — راه رسمی بازیابی بدون آسیب به اپل‌آیدی','با Recovery یا Find My می‌توان گوشی را پاک و از بکاپ بازیابی کرد؛ اپل‌آیدی و قفل فعال‌سازی جدا از رمز صفحه هستند.','رمز صفحه فقط با پاک کردن گوشی رفع می‌شود؛ این قانون امنیتی اپل است. مهم این است که اپل‌آیدی خود را داشته باشید تا قفل فعال‌سازی (Activation Lock) فعال نماند.','آیفون ۱۱','آیفون','11','','فراموشی رمز','medium','[{"title": "حالت Recovery", "body": "گوشی را به کامپیوتر وصل، افزایش صدا/کاهش صدا/دکمهٔ جانبی را تا حالت Recovery نگه دارید."}, {"title": "پاک‌سازی با Finder/iTunes", "body": "در پنجرهٔ باز شده «بازگردانی» را بزنید؛ iOS دانلود و نصب می‌شود و همه‌چیز پاک می‌شود."}, {"title": "ورود اپل‌آیدی پس از نصب", "body": "بعد از نصب، با اپل‌آیدی خود وارد شوید تا قفل فعال‌سازی برداشته شود؛ سپس از بکاپ iCloud یا کامپیوتر بازیابی کنید."}, {"title": "اگر اپل‌آیدی را هم نمی‌دانید", "body": "از iforgot.apple.com بازیابی حساب را انجام دهید. هرگز از ابزارهای بایپس غیررسمی استفاده نکنید؛ هم ناپایدار است هم خلاف قوانین."}]','کابل، کامپیوتر','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','آیفون,رمز فراموشی,recovery',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-13 23:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'رمز آیفون ۱۱ را فراموش کرده‌ام — راه رسمی بازیابی بدون آسیب به اپل‌آیدی');

