SELECT @bk_author,@bk_cat,'Face ID آیفون ۱۲ پرو بعد از ضربه کار نمی‌کند','ماژول Face ID کالیبراسیون کارخانه‌ای دارد و با تعویض آزاد درست نمی‌شود؛ اول تنظیمات را رد کنید.','Face ID روی جفت‌شدگی تراشه با برد متکی است؛ اگر ماژول آسیب دیده باشد فقط اپل یا دستگاه‌های خاص می‌توانند جفت کنند. پس قبل از نتیجه‌گیری بی‌خودی تعویض نکنید.','آیفون ۱۲ پرو','آیفون','12 Pro','','Face ID','hard','[{"title": "تنظیمات Face ID را بازنشانی کنید", "body": "تنظیمات › Face ID و رمز › بازنشانی Face ID و دوباره ثبت چهره با نور مناسب."}, {"title": "بررسی ماژول سنسور", "body": "اگر گوشی ضربه خورده و نمایشگر هم تعویض شده، ممکن است فلکس سنسور جا کامل نیفتاده باشد؛ بازرسی کنید."}, {"title": "تست پس از تعویض صفحه", "body": "اگر بعد از تعویض نمایشگر غیراصل Face ID از کار افتاد، پنل باید با سنسور هم‌خوان باشد؛ پنل اورجینال تست شود."}, {"title": "در صورت آسیب ماژول", "body": "ماژول TrueDepth تعویض تخصصی با دستگاه جفت‌سازی لازم دارد؛ در ایران برخی مراکز مجهز این کار را انجام می‌دهند."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','آیفون,Face ID',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-14 02:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'Face ID آیفون ۱۲ پرو بعد از ضربه کار نمی‌کند');

