SELECT @bk_author,@bk_cat,'آیفون «در دسترس نیست، X دقیقه دیگر امتحان کنید» — علت و راه حل','این حالت به‌خاطر تلاش‌های ناموفق رمز است؛ صبر یا بازگردانی با کامپیوتر دو راه اصلی است.','iOS برای امنیت بعد از چند رمز اشتباه، فاصلهٔ زمانی می‌گذارد؛ اگر کسی رمز را چند بار اشتباه زده، این پیام طبیعی است. اگر خودتان رمز را می‌دانید فقط صبر کنید و درست وارد کنید.','آیفون ۱۳','آیفون','13','','قفل تلاش ناموفق','easy','[{"title": "صبر و ورود صحیح", "body": "زمان اعلام‌شده را بگذارید بگذرد و رمز درست را وارد کنید؛ هر اشتباه، زمان بعدی را طولانی‌تر می‌کند."}, {"title": "اگر رمز را نمی‌دانید", "body": "با Recovery Mode گوشی را پاک کنید (بخش رمز فراموشی) و از بکاپ بازیابی کنید."}, {"title": "پیشگیری", "body": "Touch ID/Face ID را فعال و رمز قوی ولی به‌یادماندنی انتخاب کنید تا به این وضعیت نیفتید."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','آیفون,قفل رمز,امنیت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-14 06:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون «در دسترس نیست، X دقیقه دیگر امتحان کنید» — علت و راه حل');

