SELECT @bk_author,@bk_cat,'آیفون ۱۳ آب خورده — کارهای اولیه و مراحل تعمیر حرفه‌ای','بعد از آب‌خوردگی هرگز شارژ نکنید؛ خاموش کنید، خشک کنید و سریع به تعمیرکار حرفه‌ای برسانید.','آیفون در برابر پاشش مقاوم است ولی غوطه‌وری خطرناک است. خوردگی مدارها با تأخیر پیش می‌آید، پس تعمیر زودهنگام دستگاه را نجات می‌دهد.','آیفون ۱۳','آیفون','13','','آب‌خوردگی','hard','[{"title": "خاموش و خشک", "body": "خاموش کنید، قاب را بردارید، با پارچه خشک کنید و ۲۴ ساعت در محیط خشک بگذارید. سشوار داغ و شارژر ممنوع."}, {"title": "تخلیهٔ کامل", "body": "به تعمیرکار ببرید: باز شدن، جدا کردن باتری، شست‌وشوی برد با اولتراسونیک الکل و خشک‌کاری."}, {"title": "بازرسی خوردگی", "body": "لحیم‌ها و سوکت‌ها زیر میکروسکوپ بررسی و در صورت خوردگی، بازلحیم و تمیزکاری انجام می‌شود."}, {"title": "تست مرحله‌ای", "body": "بعد از خشک‌کاری، باتری سالم نصب و همهٔ ماژول‌ها تست می‌شود؛ اکسیدیشن گاهی با تأخیر چند هفته‌ای برمی‌گردد، پس تست کشیده ضروری است."}]','','["/uploads/tips/gen/phone-in-rice.jpg", "/uploads/tips/gen/wet-usb-port.jpg"]','','[]','like',0,'public','published','آیفون,آب‌خوردگی,خوردگی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-14 10:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۱۳ آب خورده — کارهای اولیه و مراحل تعمیر حرفه‌ای');

