SELECT @bk_author,@bk_cat,'آیفون ۶اس دکمهٔ وای‌فای خاکستری شده — مشکل کلاسیک مدار وای‌فای','روشن نشدن وای‌فای و دکمهٔ خاکستری در آیفون ۶اس معمولاً از آسیب IC وای‌فای یا خوردگی است.','این مشکل در آیفون‌های قدیمی شایع است؛ اغلب بعد از آب‌خوردگی یا ضربه ظاهر می‌شود. تعمیر آن سطح برد است ولی نتیجهٔ دائمی می‌دهد.','آیفون ۶اس','آیفون','6S','','وای‌فای خاکستری','hard','[{"title": "تست نرم‌افزاری اول", "body": "ریست Network Settings را انجام دهید؛ در موارد نادر با این کار وای‌فای برمی‌گردد."}, {"title": "DFU و نصب iOS", "body": "نصب کامل با DFU هم بخش نرم‌افزاری را رد می‌کند."}, {"title": "تعمیر برد وای‌فای", "body": "باز کردن، شست‌وشوی برد و در صورت نیاز تعویض ماژول وای‌فای با دستگاه جوش. این کار تخصصی است."}, {"title": "نکتهٔ اقتصادی", "body": "اگر هزینهٔ تعمیر برد بالا شد، برای گوشی قدیمی شاید ارتقا منطقی‌تر باشد؛ با تعمیرکار مشورت کنید."}]','','["/uploads/tips/mobile/phone-circuit-repair.jpg", "/uploads/tips/mobile/board-under-microscope.jpg"]','','[]','free',0,'public','published','آیفون,وای‌فای,برد',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-14 12:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۶اس دکمهٔ وای‌فای خاکستری شده — مشکل کلاسیک مدار وای‌فای');

