SELECT @bk_author,@bk_cat,'ویبرهٔ آیفون ۱۲ کار نمی‌کند یا صدای تق‌تق عجیب می‌دهد','ماژول Taptic آیفون هم ویبره می‌دهد هم لمس‌های ضربه‌ای؛ خرابی‌اش با تعویض ماژول حل می‌شود.','اول مطمئن شوید ویبره از تنظیمات خاموش نیست؛ ماژول Taptic با چند پیچ قابل تعویض است ولی بین باتری و بدنه است و باز شدن کامل لازم دارد.','آیفون ۱۲','آیفون','12','','ویبره','medium','[{"title": "تنظیمات ویبره", "body": "تنظیمات › صدا و لمس › بازخورد لمسی و ویبره در حالت بی‌صدا را چک کنید."}, {"title": "تست با بازی‌ها و زنگ", "body": "در تنظیمات › صدا › زنگ تماس، صدای زنگ را با انگشت حرکت دهید تا ویبره تست شود."}, {"title": "تعویض ماژول Taptic", "body": "باتری را جدا، ماژول را تعویض کنید؛ ماژول در بازار فراوان است."}, {"title": "اگر ماژول سالم بود", "body": "مسیر برد یا کانکتور Taptic بررسی شود (تخصصی)."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','آیفون,ویبره,Taptic',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-14 14:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ویبرهٔ آیفون ۱۲ کار نمی‌کند یا صدای تق‌تق عجیب می‌دهد');

