SELECT @bk_author,@bk_cat,'بیماری حلقهٔ آیفون ۷ — گریهٔ بلندگو در تماس و خاکستری شدن دکمهٔ ضبط','اگر دکمهٔ ضبط صدا خاکستری است و در تماس صدای بلندگو نمی‌آید، Audio IC آیفون ۷ شما دچار بیماری حلقه شده.','در آیفون ۷ مدار Audio IC به‌خاطر استرس مکانیکی ترک برمی‌دارد و علائمش گریزپاست: گاهی بلندگو، اسپیکرفون و ضبط صدا کار می‌کند و گاهی نه. تعمیر قطعی آن جوش مجدد IC روی برد است.','آیفون ۷','آیفون','7','','بیماری حلقه (Audio IC)','hard','[{"title": "تست تشخیصی", "body": "دکمهٔ ضبط صدا در اپ یادداشت را ببینید؛ خاکستری شدن + ناکار بودن اسپیکرفون، بیماری حلقه را تأیید می‌کند."}, {"title": "تعمیر موقت با فشار", "body": "برخی با فشار روی نقطهٔ مشخص پشت گوشی موقتاً مشکل را می‌بندند؛ این راه‌حل پایدار نیست."}, {"title": "Reball و جوش مجدد IC", "body": "Audio IC (U3101) برداشته، پایه‌هایش تمیز و دوباره با دستگاه جوش نصب می‌شود؛ تعمیرگاه مجهز لازم دارد."}, {"title": "پیشگیری", "body": "اگر گوشی شما این مشکل را شروع کرده، از قاب سفت استفاده کنید و گوشی را فشار ندهید؛ ضربه مشکل را سریع‌تر می‌کند."}]','','["/uploads/tips/mobile/phone-circuit-repair.jpg", "/uploads/tips/mobile/board-under-microscope.jpg"]','','[]','free',0,'public','published','آیفون ۷,Audio IC,بلندگو',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-14 18:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بیماری حلقهٔ آیفون ۷ — گریهٔ بلندگو در تماس و خاکستری شدن دکمهٔ ضبط');

