SELECT @bk_author,@bk_cat,'طرف مقابل صدای آیفون ۱۳ را خوب نمی‌شنود (میکروفون تماس)','آیفون چند میکروفون دارد؛ خاموشی میکروفون پایین معمولاً از گرفتگی یا خرابی فلکس پایین است.','iOS در تماس معمولاً میکروفون پایین را می‌گیرد. اگر تار یا بی‌صدا شنیده می‌شوید، ابتدا گرفتگی را رفع کنید و بعد تست سخت‌افزاری بگیرید.','آیفون ۱۳','آیفون','13','','میکروفون تماس','medium','[{"title": "تست میکروفون‌ها", "body": "در ضبط صدا، اسپیکرفون و ویدیو هر میکروفون را جداگانه تست کنید تا مشخص شود کدام معیوب است."}, {"title": "تمیزکاری شبکهٔ میکروفون", "body": "سوراخ میکروفون پایین را با برس نرم و مکش ملایم تمیز کنید؛ گرد و غبار رایج‌ترین علت است."}, {"title": "بررسی تنظیمات نویز", "body": "تنظیمات › دسترس‌پذیری › صدا › تشخیص صدای محیط را خاموش/روشن کنید و تست بگیرید."}, {"title": "تعویض فلکس پایین", "body": "اگر فقط یک میکروفون بی‌صدا است، فلکس پایین (که میکروفون و پورت را دارد) تعویض شود."}]','','["/uploads/tips/gen/speaker-mesh-macro.jpg"]','','[]','like',0,'public','published','آیفون,میکروفون',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-14 22:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'طرف مقابل صدای آیفون ۱۳ را خوب نمی‌شنود (میکروفون تماس)');

