SELECT @bk_author,@bk_cat,'صدای خش‌دار از اسپیکر آیفون ۱۲ — از تمیزکاری تا تعویض','خش‌دار بودن صدا معمولاً از گردوغبار شبکهٔ اسپیکر یا خرابی پارچهٔ ضدآب اسپیکر است.','اسپیکر آیفون با شبکهٔ ریز پوشانده شده؛ ذرات و رطوبت صدا را خراب می‌کنند. راه‌حل‌ها از تمیزکاری تا تعویض ماژول پیش می‌روند.','آیفون ۱۲','آیفون','12','','اسپیکر خش‌دار','easy','[{"title": "تمیزکاری با برس نرم", "body": "اسپیکر را با برس نرم و مکش ملایم تمیز کنید؛ از مایعات داخل سوراخ‌ها پرهیز کنید."}, {"title": "تخلیهٔ آب", "body": "اپ‌های Sound/سونیک (مثل Sonic) صدای فرکانس بالا می‌دهند که قطره‌ها را از اسپیکر می‌پرانند؛ بعد از شستن گوشی عالی است."}, {"title": "تست با موسیقی فرکانس‌های مختلف", "body": "اگر فقط در صدای بم خش دارید، اسپیکر آسیب دیده؛ تعویض ماژول لازم است."}, {"title": "تعویض ماژول اسپیکر", "body": "ماژول اسپیکر پایین ارزان و قابل تعویض است؛ در آیفون ۱۲ روی همان فلکس پورت هم میکروفون هست، مراقب کانکتورها باشید."}]','','["/uploads/tips/gen/speaker-mesh-macro.jpg"]','','[]','free',0,'public','published','آیفون,اسپیکر,صدا',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-15 01:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'صدای خش‌دار از اسپیکر آیفون ۱۲ — از تمیزکاری تا تعویض');

