SELECT @bk_author,@bk_cat,'بلندگوی بالای آیفون ۱۳ (Receiver) صدای کم می‌دهد','بلندگوی تماس پشت نمایشگر است و خرابی‌اش با تعویض ماژول جدا از نمایشگر حل می‌شود.','در آیفون‌های نو بلندگوی تماس یک ماژول جدا پشت نمایشگر است؛ گرفتگی شبکه یا خرابی ماژول صدا را کم می‌کند.','آیفون ۱۳','آیفون','13','','بلندگو تماس','medium','[{"title": "افزایش صدا و تست", "body": "دکمهٔ صدا را در حین تماس بالا ببرید؛ بررسی کنید حالت بلندگو در تنظیمات صدا فعال باشد."}, {"title": "تمیزکاری شبکهٔ بالای صفحه", "body": "شبکهٔ بلندگو زیر نوار بالا نمایشگر است؛ با برس نرم تمیز کنید."}, {"title": "باز کردن نمایشگر و تعویض ماژول", "body": "نمایشگر باز و ماژول Receiver تعویض شود؛ پیچ‌های نمایشگر را طبق ترتیب درآورید تا بدنه ترک نخورد."}, {"title": "اگر بعد تعویض صفحه مشکل شروع شد", "body": "در تعویض نمایشگر، ماژول بلندگو را از پنل قدیمی به جدید منتقل کنید."}]','','["/uploads/tips/gen/speaker-mesh-macro.jpg", "/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','آیفون,بلندگو تماس',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-15 02:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بلندگوی بالای آیفون ۱۳ (Receiver) صدای کم می‌دهد');

