SELECT @bk_author,@bk_cat,'صدای ویدیوی آیفون SE نویز و خش دارد (میکروفون ضبط)','آیفون در ضبط ویدیو از چند میکروفون هم‌زمان استفاده می‌کند؛ خرابی یکی، نویز و خش می‌دهد.','میکروفون بالای گوشی (پشت بلندگو) در ضبط ویدیو نقش حذف نویز دارد؛ خرابی‌اش نویز ضبط را بالا می‌برد.','آیفون SE ۲۰۲۰','آیفون','SE','','نویز ضبط ویدیو','medium','[{"title": "تست سه‌گانهٔ میکروفون", "body": "ضبط ویدیو، ضبط صدا و تماس اسپیکرفون را تست کنید تا میکروفون معیوب مشخص شود."}, {"title": "تمیزکاری", "body": "سوراخ میکروفون بالای گوشی را تمیز کنید؛ جلد یا چسب ممکن است مسیر صدا را بسته باشد."}, {"title": "تعویض فلکس مرتبط", "body": "میکروفون معیوب روی فلکس مربوطه (بالا یا پایین) تعویض شود."}, {"title": "نکتهٔ ضبط", "body": "اگر فقط نزدیک موتور یا منبع نویز نویز دارید، طبیعی است؛ جهت‌گیری میکروفون را عوض کنید."}]','','["/uploads/tips/gen/speaker-mesh-macro.jpg"]','','[]','free',0,'public','published','آیفون,نویز,میکروفون,ویدیو',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-15 06:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'صدای ویدیوی آیفون SE نویز و خش دارد (میکروفون ضبط)');

