SELECT @bk_author,@bk_cat,'تعویض شیشهٔ پشت آیفون ۱۱ — روش لیزر یا سیم برش','شیشهٔ پشت آیفون با چسب سخت چسبیده؛ تعویض درست آن با لیزر یا برش سیمی انجام می‌شود.','ضربه به پشت گوشی شیشه را خرد می‌کند. برداشتن آن با چکش یا انبردست (روش‌های خانگی) دوربین و Wi-Fi را می‌شکند؛ مراکز مجهز ابزار مناسب دارند.','آیفون ۱۱','آیفون','11','','شکستن شیشهٔ پشت','hard','[{"title": "حفاظت داخلی", "body": "نمایشگر و قطعات داخل با تراشهٔ شیشه آسیب می‌بینند؛ اول شیشه‌های شل خارج شود و گوشی بسته بماند تا لیزر/برش."}, {"title": "برش با لیزر", "body": "دستگاه لیزر مسیر چسب دور شیشه را می‌بُرد تا شیشه بدون فشار جدا شود."}, {"title": "روش سیم برش", "body": "با سیم فولادی و حرارت، چسب زیر شیشه بریده می‌شود؛ حرفه‌ای و کم‌ریسک."}, {"title": "نصب شیشهٔ نو", "body": "شیشهٔ نو با چسب مخصوص و واشر آب‌بندی نصب و تست نهایی می‌شود."}]','دستگاه لیزر، سیم برش، حرارت، چسب UV','["/uploads/tips/gen/heat-gun-backcover.jpg"]','','[]','free',0,'public','published','آیفون,شیشه پشت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-15 19:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض شیشهٔ پشت آیفون ۱۱ — روش لیزر یا سیم برش');

