SELECT @bk_author,@bk_cat,'شیشهٔ پشت آیفون ۱۲ مینی ترک خورده — هزینه و روش تعمیر','برای مینی، چون بدنه کوچک است برش سیمی گزینهٔ مطمئن‌تری از لیزر است.','شیشهٔ پشت با کویل شارژ بی‌سیم یکپارچه است؛ در تعویض باید مراقب بود کویل و مسیر آنتن سالم بماند.','آیفون ۱۲ مینی','آیفون','12 mini','','ترک شیشه پشت','medium','[{"title": "تشخیص سطح آسیب", "body": "اگر فقط شیشه ترک است و کویل/دوربین سالم، تعویض شیشه کافی است."}, {"title": "باز کردن با برش سیمی", "body": "شیشه با حرارت و سیم برش جدا شود؛ کویل شارژ بی‌سیم که روی شیشه است حفظ شود."}, {"title": "نصب شیشه و کویل", "body": "شیشهٔ نو و کویل با چسب درست نصب شود؛ تست شارژ بی‌سیم بعد از مونتاژ."}, {"title": "تست آنتن‌ها", "body": "Wi-Fi و بلوتوث بعد از بستن تست شوند؛ مسیر آنتن‌ها در پشت گوشی است."}]','','["/uploads/tips/gen/heat-gun-backcover.jpg"]','','[]','like',0,'public','published','آیفون,شیشه پشت,مینی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-15 21:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'شیشهٔ پشت آیفون ۱۲ مینی ترک خورده — هزینه و روش تعمیر');

