SELECT @bk_author,@bk_cat,'چرا آیفون ۱۳ من شب کامل شارژ نمی‌شود؟','شارژ آهسته می‌تواند از پورت کثیف، شارژر ضعیف یا گرمای زیاد باشد؛ هر سه را رد کنید.','شارژر ۲۰ وات آیفون ۱۳ را در حدود ۱.۵ ساعت پر می‌کند. اگر خیلی بیشتر طول می‌کشد، عیب‌یابی مرحله‌ای لازم است.','آیفون ۱۳','آیفون','13','','شارژ آهسته','easy','[{"title": "اندازه‌گیری زمان شارژ", "body": "از ۲۰ تا ۱۰۰٪ زمان بگیرید؛ بیش از ۳ ساعت یعنی مشکل واقعی است."}, {"title": "تمیزکاری پورت و تست کابل/شارژر", "body": "پورت را تمیز و با ست شارژر USB-PD سالم تست کنید."}, {"title": "دما را کنترل کنید", "body": "اگر گوشی حین شارژ داغ است، سیستم شارژ را کند می‌کند؛ قاب را بردارید و در محیط خنک شارژ کنید."}, {"title": "نکتهٔ نرم‌افزار", "body": "شارژ بهینهٔ iOS شب‌ها شارژ را عمداً کند نگه می‌دارد تا سحرگاه کامل شود؛ این رفتار طبیعی است و خطا نیست."}]','','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','paid',25000,'public','published','آیفون,شارژ آهسته',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-16 01:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'چرا آیفون ۱۳ من شب کامل شارژ نمی‌شود؟');

