SELECT @bk_author,@bk_cat,'وای‌فای آیفون ۱۴ قطع و وصل می‌شود — راه‌حل‌های مؤثر','قبل از نگرانی سخت‌افزاری، ریست شبکه، فراموشی مودم و آپدیت iOS اکثر موارد را حل می‌کند.','قطع و وصلی وای‌فای بیشتر نرم‌افزاری یا مربوط به مودم است. با این ترتیب تست کنید تا مقصر پیدا شود.','آیفون ۱۴','آیفون','14','','قطع شدن مکرر وای‌فای','easy','[{"title": "فراموشی شبکه و وصل مجدد", "body": "تنظیمات › وای‌فای › شبکهٔ مورد نظر › فراموش کردن، بعد وصل مجدد."}, {"title": "ریست تنظیمات شبکه", "body": "تنظیمات › عمومی › انتقال/ریست › ریست تنظیمات شبکه."}, {"title": "آپدیت iOS و مودم", "body": "آیفون و فریمور مودم را آپدیت کنید؛ ناسازگاری فریمور رایج است."}, {"title": "تست در شبکه‌های دیگر", "body": "اگر فقط در خانه مشکل دارید مودم مقصر است؛ اگر همه‌جا مشکل است و با ریست حل نشد، آنتن وای‌فای بررسی سخت‌افزاری شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','آیفون,وای‌فای',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-16 04:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'وای‌فای آیفون ۱۴ قطع و وصل می‌شود — راه‌حل‌های مؤثر');

