SELECT @bk_author,@bk_cat,'بلوتوث آیفون ۱۲ به ایرپاد و خودرو وصل نمی‌شود','با پاک کردن جفت‌سازی‌های قدیمی و ریست شبکه، ۹۰٪ مشکلات بلوتوث حل می‌شود.','بلوتوث iOS حافظهٔ جفت‌سازی محدودی دارد؛ اتصال‌های قدیمی خراب می‌شوند و اتصال جدید را مختل می‌کنند.','آیفون ۱۲','آیفون','12','','بلوتوث','easy','[{"title": "فراموشی همهٔ دستگاه‌ها", "body": "تنظیمات › بلوتوث، هر دستگاه موجود را فراموش کنید."}, {"title": "ریست تنظیمات شبکه", "body": "این ریست هم بلوتوث هم وای‌فای را بازنشانی می‌کند."}, {"title": "ریست دستگاه مقصد", "body": "ایرپاد یا سیستم خودرو را هم ریست کنید؛ گاهی مقصد مشکل دارد."}, {"title": "تست با دستگاه دیگر", "body": "اگر آیفون با هیچ دستگاهی جفت نمی‌شود و ریست‌ها بی‌اثر بود، ماژول بلوتوث بررسی سخت‌افزاری شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','آیفون,بلوتوث',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-16 06:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بلوتوث آیفون ۱۲ به ایرپاد و خودرو وصل نمی‌شود');

