SELECT @bk_author,@bk_cat,'آیفون ۱۳ هنگام بازی سنگین داغ و کند می‌شود','کند شدن هنگام داغی کاملاً عمدی است (محافظت پردازنده)؛ با مدیریت گرما سرعت را حفظ کنید.','iOS برای محافظت از باتری و برد، با گرما سرعت را کم می‌کند. راه‌حل مدیریت گرماست نه غیرفعال کردن محافظت.','آیفون ۱۳','آیفون','13','','گرمای بازی','easy','[{"title": "قاب و محیط", "body": "قاب ضخیم را بردارید و در محیط خنک بازی کنید."}, {"title": "مصرف پس‌زمینه", "body": "اپ‌های پس‌زمینه را ببندید و روشنایی را روی خودکار بگذارید."}, {"title": "شارژ نکردن حین بازی", "body": "شارژ سریع همزمان با بازی گرما را دوچندان می‌کند؛ ترجیحاً بازی را جدا از شارژ انجام دهید."}, {"title": "بررسی باتری", "body": "اگر باتری فرسوده است، خودش گرما تولید می‌کند؛ سلامت باتری را چک کنید."}]','','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','like',0,'public','published','آیفون,داغی,بازی',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-16 10:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۱۳ هنگام بازی سنگین داغ و کند می‌شود');

