SELECT @bk_author,@bk_cat,'آیفون ۱۱ کند شده و هنگ می‌کند — پاک‌سازی اصولی بدون از دست رفتن داده','کندی معمولاً از حافظهٔ پر، اپ‌های سنگین و کش است؛ ریست کارخانه آخرین گزینه است.','قبل از ریست کارخانه، این پاک‌سازی‌ها را انجام دهید؛ در اکثر موارد سرعت گوشی به‌طور محسوس بهتر می‌شود.','آیفون ۱۱','آیفون','11','','گیر کردن و کندی','easy','[{"title": "حذف اپ‌های بدون استفاده", "body": "تنظیمات › عمومی › فضای ذخیره‌سازی؛ اپ‌های سنگین و بلااستفاده را حذف کنید."}, {"title": "پاک کردن کش سافاری و اپ‌ها", "body": "تنظیمات سافاری › پاک کردن تاریخچه و داده‌ها؛ برخی اپ‌ها هم گزینهٔ پاک‌کردن کش دارند."}, {"title": "راه‌اندازی مجدد هفتگی", "body": "گوشی را هفته‌ای یک‌بار کامل خاموش/روشن کنید."}, {"title": "ریست تنظیمات یا نصب پاک", "body": "اگر ادامه داشت، ریست تنظیمات و در نهایت نصب پاک با بکاپ انجام شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','آیفون,کندی,پاک‌سازی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-16 12:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۱۱ کند شده و هنگ می‌کند — پاک‌سازی اصولی بدون از دست رفتن داده');

