SELECT @bk_author,@bk_cat,'فضای آیفون ۱۳ پر شده — آزادسازی امن حافظه','عکس‌ها، پیام‌های ضمیمه‌دار و کش اپ‌ها بزرگ‌ترین مصرف‌کنندگان حافظه هستند.','با ابزار خود iOS می‌توانید بدون ریسک فضا آزاد کنید؛ حذف دستی فایل‌های ناآشنا توصیه نمی‌شود.','آیفون ۱۳','آیفون','13','','حافظه پر','easy','[{"title": "تحلیل فضا", "body": "تنظیمات › عمومی › فضای ذخیره‌سازی؛ بزرگ‌ترین‌ها را ببینید."}, {"title": "بهینه‌سازی عکس‌ها", "body": "گزینهٔ «بهینه‌سازی فضای عکس‌ها» را فعال و بکاپ iCloud را چک کنید."}, {"title": "پاک کردن پیام‌های قدیمی", "body": "تنظیم پیام‌ها روی نگه‌داری ۳۰ روز یا ۱ سال، گیز gigabyteها فضا آزاد می‌کند."}, {"title": "بازبینی اپ‌ها", "body": "اپ‌هایی که دانلود آفلاین سنگین دارند (پادکست، نقشه، ویدیو) را مرور و پاک‌سازی کنید."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','آیفون,حافظه,فضا',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-16 15:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'فضای آیفون ۱۳ پر شده — آزادسازی امن حافظه');

