SELECT @bk_author,@bk_cat,'آیفون ۱۲ سیم‌کارت را شناسایی نمی‌کند','از سیم‌کارت و سینی شروع کنید؛ سپس نرم‌افزار و در آخر مدار سیم‌کارت روی برد.','خطای No SIM یا سیم‌کارت شناسایی نمی‌شود، ترتیب عیب‌یابی مشخصی دارد که اکثر موارد را بدون هزینه حل می‌کند.','آیفون ۱۲','آیفون','12','','گیر سیم‌کارت','medium','[{"title": "سیم‌کارت و سینی", "body": "سیم‌کارت را در گوشی دیگر تست کنید؛ سینی را کامل فرو ببرید و مطمئن شوید کج نیست."}, {"title": "ریست شبکه و آپدیت", "body": "ریست تنظیمات شبکه + آپدیت iOS انجام دهید."}, {"title": "تنظیم اپراتور", "body": "تنظیمات › عمومی › درباره؛ اگر پیام آپدیت اپراتور آمد، آن را بپذیرید."}, {"title": "بررسی سوکت سیم‌کارت", "body": "اگر همه سالم بود، سوکت SIM و پین‌هایش زیر میکروسکوپ بررسی و در صورت نیاز تعمیر برد انجام شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','آیفون,سیم‌کارت',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-16 17:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیفون ۱۲ سیم‌کارت را شناسایی نمی‌کند');

