SELECT @bk_author,@bk_cat,'گلکسی A12 خودبه‌خود خاموش می‌شود — از باتری شروع کنید','خاموشی ناگهانی در A12 اغلب از باتری فرسوده، اتصال شل باتری یا اپ‌های مشکل‌دار است.','A12 یکی از پرفروش‌ترین گوشی‌های ایران است و با چند سال کارکرد، باتری‌هایش فرسوده می‌شوند. خاموشی‌های تکرارشونده معمولاً با تعویض باتری حل می‌شود.','گلکسی A12','سامسونگ','گلکسی A12','','خاموشی ناگهانی','easy','[{"title": "بررسی الگوی خاموشی", "body": "اگر خاموشی هنگام بازی یا شارژ کم است، باتری محتمل‌تر است؛ اگر تصادفی است، نرم‌افزار هم بررسی شود."}, {"title": "تعویض باتری", "body": "باتری نو با کیفیت نصب کنید. پشت A12 پلاستیکی است و با پیک و حرارت ملایم باز می‌شود؛ فلکس باتری را اول جدا کنید."}, {"title": "ریست نرم‌افزاری", "body": "اگر با باتری سالم ادامه داشت، ریست کارخانه بعد از بکاپ انجام شود."}, {"title": "بررسی اتصال باتری", "body": "گاهی فقط سوکت باتری بعد از ضربه شل شده؛ جازدن آن مشکل را حل می‌کند."}]','','["/uploads/tips/gen/swollen-battery.jpg", "/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','like',0,'public','published','سامسونگ,A12,خاموشی,باتری',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-16 21:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'گلکسی A12 خودبه‌خود خاموش می‌شود — از باتری شروع کنید');

