SELECT @bk_author,@bk_cat,'تعویض باتری گلکسی A50 به‌صورت اصولی (ویدیوی گام‌به‌گام)','باتری A50 با چسب قوی نگه داشته شده؛ با حرارت، نوار کشی و الکل بدون خم‌کردن باتری خارج می‌شود.','باتری گلکسی A50 در ویدئوهای آموزشی متعددی (مثل آموزش مجتمع پل در آپارات) قدم‌به‌قدم نشان داده شده است. نکتهٔ اصلی، صبوری در جدا کردن چسب است تا باتری خم نشود.','گلکسی A50','سامسونگ','متفرقه','','باتری ضعیف','medium','[{"title": "خاموش کردن و باز کردن پشت", "body": "با هیتر ۷۰-۸۰ درجه پشت را گرم و با ساکشن و پیک باز کنید؛ پشت A50 شیشه‌ای است و با تندی می‌شکند."}, {"title": "جداسازی فلکس باتری", "body": "اول فلکس باتری از برد جدا شود تا اتصال کوتاه پیش نیاید."}, {"title": "خارج کردن باتری با چسب کشی", "body": "نوارهای چسب را آرام و موازی سطح بکشید؛ اگر پاره شد، قطره الکل زیر باتری و برداشتن با کارت پلاستیکی."}, {"title": "نصب باتری نو و تست", "body": "باتری نو با چسب نو، فلکس جا زده و تست شارژدهی انجام شود؛ پشت گوشی با چسب آب‌بندی نو بسته شود."}]','هیتر، ساکشن، پیک، نوار چسب کشی، الکل ایزوپروپیل','["/uploads/tips/mobile/open-iphone-repair.jpg", "/uploads/tips/gen/disconnect-battery-flex.jpg"]','https://www.aparat.com/v/cyj89q2','[]','free',0,'public','published','سامسونگ,A50,باتری',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-17 01:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض باتری گلکسی A50 به‌صورت اصولی (ویدیوی گام‌به‌گام)');

