SELECT @bk_author,@bk_cat,'تعویض تاچ و ال‌سی‌دی گلکسی A12 (کامل با ویدیو)','در A12 تاچ و LCD یکپارچه‌اند؛ تعویضش با باز کردن پشت و پیچ‌های قاب میانی انجام می‌شود.','آموزش ویدیویی تعویض تاچ/ال‌سی‌دی A12 در آپارات موجود است. مسیر باز شدن از پشت است و نمایشگر با پیچ و چسب روی قاب میانی نصب است.','گلکسی A12','سامسونگ','گلکسی A12','','شکستن نمایشگر','hard','[{"title": "باز کردن پشت شیشه‌ای", "body": "با حرارت و ساکشن پشت را باز کنید و باتری را جدا کنید."}, {"title": "باز کردن قاب میانی", "body": "همهٔ پیچ‌های قاب میانی باز و قاب با پیک جدا شود؛ فلکس‌های کناری را یادداشت کنید."}, {"title": "جداسازی نمایشگر", "body": "فلکس نمایشگر از برد جدا و پنل از قاب بیرون بیاید؛ گرما برای چسب لازم است."}, {"title": "نصب پنل نو", "body": "نمایشگر نو (تاچ+LCD یکپارچه) با چسب نو نصب، تست تاچ و تصویر، و مونتاژ نهایی انجام شود."}]','هیتر، ساکشن، ست پیچ‌گوشتی، چسب دوطرفهٔ نو','["/uploads/tips/gen/cracked-display.jpg", "/uploads/tips/gen/screws-organization-mat.jpg"]','https://www.aparat.com/v/kmp5aju','[]','paid',65000,'public','published','سامسونگ,A12,نمایشگر,تاچ',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-17 02:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض تاچ و ال‌سی‌دی گلکسی A12 (کامل با ویدیو)');

