SELECT @bk_author,@bk_cat,'گلکسی S21 روشن است ولی صفحه سیاه است (پنل AMOLED)','سیاهی کامل صفحه با کارکرد صدا و ویبره، معمولاً پنل یا مسیر نمایشگر است؛ اول تست اجباری را انجام دهید.','پنل‌های AMOLED گاهی بعد از ضربه یا عیب تراشه کامل خاموش می‌شوند ولی گوشی کار می‌کند. با زنگ زدن به گوشی از خط دیگر می‌توانید روشن بودن آن را تأیید کنید.','گلکسی S21','سامسونگ','گلکسی S21','','صفحه سیاه','hard','[{"title": "ریست اجباری", "body": "Volume پایین + Power را ۲۰-۳۰ ثانیه نگه دارید؛ اگر صفحه آمد مشکل موقتی بوده."}, {"title": "تست روی حالت Safe", "body": "اگر تصویر در Safe Mode آمد، یک اپ مقصر است؛ اپ‌های اخیراً نصب‌شده را حذف کنید."}, {"title": "تست با پنل سالم", "body": "پنل دیگر نصب کنید؛ اگر تصویر آمد پنل قبلی معیوب است."}, {"title": "تعمیر برد", "body": "اگر با پنل سالم هم تصویر نبود، مسیر نمایشگر روی برد (تخصصی) بررسی شود."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','سامسونگ,S21,صفحه سیاه,AMOLED',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-17 13:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'گلکسی S21 روشن است ولی صفحه سیاه است (پنل AMOLED)');

