SELECT @bk_author,@bk_cat,'تعویض صفحهٔ ترک‌خوردهٔ نوت ۲۰ با سنسور اولتراسونیک','نوت ۲۰ پنل گران و سنسور اثر انگشت اولتراسونیک دارد؛ پنل اصل بگیرید تا اثر انگشت دقت خود را حفظ کند.','سنسور اولتراسونیک سامسونگ با پنل‌های کپی دقتش خیلی می‌افتد. برای گوشی میان‌رده قدیمی‌تر، هزینهٔ پنل اصل را با ارزش گوشی بسنجید.','گلکسی نوت ۲۰','سامسونگ','نوت ۲۰','','شکستن نمایشگر','hard','[{"title": "تأیید ترک و انتخاب قطعه", "body": "پنل Service Pack اصل برای حفظ کیفیت AMOLED و سنسور."}, {"title": "باز کردن از پشت و قطع باتری", "body": "طبق روال گوشی‌های شیشه‌ای سامسونگ."}, {"title": "انتقال قطعات پنل قدیمی", "body": "بلندگو، دوربین جلو و سنسورها از پنل قدیمی به جدید منتقل شوند."}, {"title": "تست کامل", "body": "تاچ، رنگ، اثر انگشت و Always-On تست و گوشی با واشر نو بسته شود."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','سامسونگ,نوت ۲۰,نمایشگر',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-17 15:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض صفحهٔ ترک‌خوردهٔ نوت ۲۰ با سنسور اولتراسونیک');

