SELECT @bk_author,@bk_cat,'گلکسی A10 شارژ نمی‌شود — سوکت شارژ یا نرم‌افزار؟','اول پیام «تأخیر در شارژ» و پیام‌های سامسونگ را ببینید؛ سپس پورت، کابل و در آخر فلکس پورت.','A10 و A10s سوکت شارژ پرتردد دارند. تعویض فلکس پورت در این گوشی‌ها ارزان و سریع است.','گلکسی A10','سامسونگ','متفرقه','','شارژ نمی‌شود','medium','[{"title": "تست کابل/شارژر و پورت", "body": "با ست دیگر تست کنید و پورت را تمیز کنید."}, {"title": "بررسی پیام‌های سیستم", "body": "اگر «شارژ کند» یا «رطوبت» می‌آید، پورت خیس یا کثیف است؛ خشک و تمیز کنید."}, {"title": "تعویض فلکس پورت", "body": "پشت را باز، فلکس پورت را تعویض کنید؛ میکروفون روی همان فلکس است، بعد از تعویض تست شود."}, {"title": "تست مدار شارژ", "body": "اگر با فلکس نو هم شارژ نشد، IC شارژ روی برد بررسی شود."}]','','["/uploads/tips/gen/wet-usb-port.jpg"]','','[]','free',0,'public','published','سامسونگ,A10,شارژ,سوکت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-17 19:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'گلکسی A10 شارژ نمی‌شود — سوکت شارژ یا نرم‌افزار؟');

