SELECT @bk_author,@bk_cat,'تعویض سوکت شارژ گلکسی A51 — روش درست بدون هیتر','سوکت‌های فلکس با هویه جا زده می‌شوند نه هیتر؛ آموزش تعویض سوکت در ویدیوهای آپارات کامل است.','تعمیرکاران حرفه‌ای توصیه می‌کنند سوکت فلکسی با هویهٔ ریز جا زده شود؛ هیتر چسب زیر فلکس را نرم می‌کند و سوکت جابجا می‌شود.','گلکسی A51','سامسونگ','متفرقه','','سوکت شارژ','medium','[{"title": "تأیید خرابی سوکت", "body": "با چند کابل تست کنید؛ شل بودن یا نشدن تشخیص سوکت را قطعی می‌کند."}, {"title": "باز کردن گوشی", "body": "پشت شیشه‌ای A51 با حرارت باز و باتری جدا شود."}, {"title": "تعویض فلکس پورت", "body": "فلکس قدیمی را با هویه از برد جدا و سوکت نو را جا بزنید؛ فلکس آمادهٔ نو هم جایگزین کامل است."}, {"title": "تست", "body": "شارژ سیمی، انتقال داده و میکروفون پایین تست شود."}]','هویهٔ ریز، قلع و روغن، پنس، فلکس پورت نو','["/uploads/tips/gen/wet-usb-port.jpg", "/uploads/tips/gen/screws-organization-mat.jpg"]','https://www.aparat.com/v/y68jj8p','[]','like',0,'public','published','سامسونگ,A51,سوکت شارژ',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-17 20:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض سوکت شارژ گلکسی A51 — روش درست بدون هیتر');

