SELECT @bk_author,@bk_cat,'بالا آمدن پشت گلکسی A32 — باتری متورم را جدی بگیرید','تورم باتری در A32 شایع است؛ ادامهٔ استفاده خطرناک است و تعویض فوری لازم دارد.','باتری متورم پشت گوشی را بالا می‌دهد و صفحه را تحت فشار می‌گذارد. تعویض سریع از آسیب به صفحه جلوگیری می‌کند.','گلکسی A32','سامسونگ','گلکسی A32','','باتری متورم','medium','[{"title": "توقف استفاده و شارژ", "body": "گوشی را خاموش و شارژ را قطع کنید."}, {"title": "باز کردن پشت و خروج امن باتری", "body": "با پیک و حرارت ملایم پشت را باز و باتری را با کارت پلاستیکی و الکل بیرون بیاورید؛ فشار و سوراخ کردن ممنوع."}, {"title": "بررسی صفحه و قاب", "body": "اگر صفحه از فشار باتری لکه گرفته، پنل هم باید تعویض شود."}, {"title": "نصب باتری باکیفیت", "body": "باتری گرید A با ضمانت نصب و گوشی تست شود."}]','','["/uploads/tips/gen/swollen-battery.jpg"]','','[]','paid',55000,'public','published','سامسونگ,A32,باتری متورم',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-18 05:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بالا آمدن پشت گلکسی A32 — باتری متورم را جدی بگیرید');

