SELECT @bk_author,@bk_cat,'باتری گلکسی A52 گیر کرده — جدا کردن امن بدون خم شدن','چسب باتری A52 با الکل و کشیدن نوارها آزاد می‌شود؛ خم کردن باتری خطر آتش دارد.','باتری‌های چسبیده در گوشی‌های سامسونگ با نوارهای کشی نگه داشته می‌شوند. کشیدن اشتباه (بالا به‌جای موازی) نوار را پاره می‌کند.','گلکسی A52','سامسونگ','گلکسی A52','','تعویض باتری','medium','[{"title": "کشیدن نوارها به‌صورت موازی", "body": "نوارها را آهسته و موازی سطح باتری بکشید؛ با پیچاندن نوار دور پیک، کشش کنترل‌شده انجام دهید."}, {"title": "روش الکل در پارگی", "body": "چند قطره ایزوپروپیل ۹۹٪ زیر باتری و صبر ۳۰ ثانیه؛ سپس با کارت پلاستیکی بلند کنید."}, {"title": "هرگز با فلز و فشار نقطه‌ای", "body": "باتری لیتیومی در برابر خمش و سوراخ واکنش‌های خطرناک دارد."}, {"title": "نصب و تست", "body": "باتری نو با چسب نو؛ بعد از مونتاژ چند ساعت تست شارژدهی."}]','الکل ایزوپروپیل، کارت پلاستیکی، پنس','["/uploads/tips/gen/disconnect-battery-flex.jpg", "/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','free',0,'public','published','سامسونگ,A52,باتری',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-18 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'باتری گلکسی A52 گیر کرده — جدا کردن امن بدون خم شدن');

