SELECT @bk_author,@bk_cat,'گلکسی A12 روی لوگو می‌ماند و ریستارت می‌شود','حلقهٔ لوگو یا از نرم‌افزار است یا حافظه و برد؛ اول Recovery، بعد ریست فکتوری، آخر تعمیر برد.','گوشی‌های A12 که مدت‌ها استفاده شده و حافظه‌شان شلوغ است، گاهی در بوت گیر می‌کنند. ترتیب عیب‌یابی مشخصی دارد.','گلکسی A12','سامسونگ','گلکسی A12','','حلقهٔ خاموش/روشن','medium','[{"title": "ورود به Recovery", "body": "گوشی خاموش؛ Volume بالا + Power را نگه دارید تا منوی Recovery بیاید."}, {"title": "Wipe Cache Partition", "body": "پاک کردن کش بدون حذف داده؛ اول این را امتحان کنید."}, {"title": "Factory Reset (با بکاپ)", "body": "اگر کش بی‌اثر بود، ریست فکتوری از Recovery انجام شود؛ همه‌چیز پاک می‌شود."}, {"title": "تعمیر برد / eMMC", "body": "اگر ریست هم جواب نداد، حافظهٔ eMMC یا مسیر آن بررسی شود (تخصصی)."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','سامسونگ,A12,لوگو,ریست',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-18 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'گلکسی A12 روی لوگو می‌ماند و ریستارت می‌شود');

