SELECT @bk_author,@bk_cat,'تعویض تاچ و ال‌سی‌دی گلکسی J7 Prime — آموزش کامل','J7 Prime از پشت باز می‌شود و پنل کامل (تاچ+LCD) تعویض می‌شود؛ ویدیوهای فراوان فارسی دارد.','این مدل سال‌ها در ایران فراوان بوده و قطعاتش ارزان است. تعویض پنل آن یکی از پروژه‌های تمرینی خوب تعمیرکاران تازه‌کار است.','گلکسی J7 Prime','سامسونگ','متفرقه','','تعویض تاچ','medium','[{"title": "باز کردن پشت پلاستیکی", "body": "با پیک و حرارت ملایم؛ J7 Prime پشت پلاستیکی نازکی دارد که با تندی می‌شکند."}, {"title": "باز کردن پیچ‌های قاب", "body": "همهٔ پیچ‌های فیلیپس قاب میانی باز شود."}, {"title": "جداسازی پنل", "body": "فلکس تاچ/LCD جدا و پنل با حرارت از قاب خارج شود؛ فلکس دکمهٔ خانه مراقبت می‌خواهد."}, {"title": "نصب پنل نو و تست", "body": "پنل نو جا زده، تاچ و تصویر تست و گوشی بسته شود."}]','','["/uploads/tips/gen/cracked-display.jpg", "/uploads/tips/gen/screws-organization-mat.jpg"]','https://www.aparat.com/v/xkskb1b','[]','free',0,'public','published','سامسونگ,J7 Prime,تاچ,ال‌سی‌دی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-18 17:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض تاچ و ال‌سی‌دی گلکسی J7 Prime — آموزش کامل');

