SELECT @bk_author,@bk_cat,'رمز گلکسی S21 را فراموش کرده‌ام — Find My Mobile یا Recovery','سامسونگ سرویس Find My Mobile دارد که بدون از دست دادن داده گوشی را از راه دور باز می‌کند.','اگر حساب سامسونگ روی گوشی فعال و اینترنت داشته باشد، Find My Mobile گزینهٔ Unlock را می‌دهد. بدون آن، ریست از Recovery تنها راه رسمی است.','گلکسی S21','سامسونگ','گلکسی S21','','فراموشی رمز','medium','[{"title": "Find My Mobile", "body": "از findmymobile.samsung.com وارد حساب شوید و گزینهٔ Unlock را بزنید."}, {"title": "Google Find My Device", "body": "از android.com/find هم می‌توانید گوشی را پاک کنید (داده‌ها حذف می‌شوند)."}, {"title": "Recovery Mode", "body": "گوشی خاموش؛ Volume بالا + Power؛ با Volume for Wipe data/factory reset را تأیید کنید."}, {"title": "بازیابی از بکاپ", "body": "بعد از ریست، با حساب گوگل و بکاپ Smart Switch یا گوگل، داده‌ها را برگردانید."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','like',0,'public','published','سامسونگ,S21,رمز,Find My Mobile',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-18 22:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'رمز گلکسی S21 را فراموش کرده‌ام — Find My Mobile یا Recovery');

