SELECT @bk_author,@bk_cat,'اپ دوربین گلکسی A52 خطا می‌دهد — Camera Failed','خطای Camera Failed اغلب با پاک‌کردن کش اپ دوربین و ریست Settings حل می‌شود.','قبل از نتیجه‌گیری سخت‌افزاری، این پاک‌سازی‌های نرم‌افزاری را انجام دهید؛ در اکثر موارد مشکل از سیستم است.','گلکسی A52','سامسونگ','گلکسی A52','','دوربین باز نمی‌شود','easy','[{"title": "پاک کردن کش و دادهٔ دوربین", "body": "تنظیمات › برنامه‌ها › دوربین › حافظه › پاک کردن حافظهٔ نهان و داده."}, {"title": "ریست تنظیمات برنامه", "body": "تنظیمات › برنامه‌ها › بازنشانی تنظیمات برنامه."}, {"title": "Safe Mode", "body": "گوشی را در Safe Mode روشن کنید؛ اگر دوربین کار کرد، اپ ثالثی مقصر است."}, {"title": "تست سخت‌افزاری", "body": "در حالت سرویس *#0*# (مدل‌های سازگار) تست دوربین بزنید؛ خرابی سخت‌افزاری تعویض ماژول لازم دارد."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','free',0,'public','published','سامسونگ,A52,دوربین,خطا',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-19 01:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'اپ دوربین گلکسی A52 خطا می‌دهد — Camera Failed');

