SELECT @bk_author,@bk_cat,'دوربین گلکسی A12 فوکوس نمی‌کند و عکس‌ها تار است','تاری دوربین در A12 اغلب از گردوغبار زیر شیشهٔ لنز یا لنز شل است؛ قبل از تعویض ماژول تمیزکاری کنید.','دسترسی به لنز دوربین A12 با باز کردن پشت گوشی ممکن است؛ تمیزکاری و محکم کردن ماژول اغلب مشکل را حل می‌کند.','گلکسی A12','سامسونگ','گلکسی A12','','دوربین فوکوس','easy','[{"title": "تمیز کردن بیرونی", "body": "اول شیشهٔ بیرونی با میکروفایبر تمیز شود."}, {"title": "باز کردن و بازرسی", "body": "پشت را باز کنید؛ شیشهٔ لنز از داخل تمیز و پیچ/چسب ماژول بررسی شود."}, {"title": "محکم کردن یا تعویض ماژول", "body": "اگر ماژول شل است جا بزنید؛ در صورت خرابی، ماژول نو (ارزان برای A12) نصب شود."}, {"title": "تست فوکوس", "body": "روی موضوع نزدیک/دور فوکوس دستی و اتوفوکوس تست شود."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','free',0,'public','published','سامسونگ,A12,دوربین,فوکوس',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-19 02:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'دوربین گلکسی A12 فوکوس نمی‌کند و عکس‌ها تار است');

