SELECT @bk_author,@bk_cat,'مخاطب صدای مرا در A32 خوب نمی‌شنود','گرفتگی یا خرابی میکروفون پایین رایج است؛ تمیزکاری، تست سه‌گانه و تعویض فلکس در صورت نیاز.','سامسونگ چند میکروفون دارد؛ در تماس معمولی میکروفون پایین کار می‌کند. تست جداگانه هر میکروفون، مقصر را مشخص می‌کند.','گلکسی A32','سامسونگ','گلکسی A32','','میکروفون','medium','[{"title": "تست‌های سه‌گانه", "body": "ضبط صدا (میکروفون پایین)، تماس اسپیکرفون (بالایی)، ویدیو (هر دو)."}, {"title": "تمیزکاری", "body": "سوراخ پایین کنار پورت USB را با برس نرم و مکش تمیز کنید."}, {"title": "بررسی چسب و کیسه", "body": "کیسه/قاب مسیر میکروفون را نبندد؛ بدون قاب تست کنید."}, {"title": "تعویض فلکس پایین", "body": "در صورت خرابی، فلکس پایین (پورت+میکروفون) تعویض شود."}]','','["/uploads/tips/gen/speaker-mesh-macro.jpg"]','','[]','free',0,'public','published','سامسونگ,A32,میکروفون',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-19 07:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'مخاطب صدای مرا در A32 خوب نمی‌شنود');

