SELECT @bk_author,@bk_cat,'صدای اسپیکر گلکسی A10 خش می‌دهد یا کم است','شبکهٔ اسپیکر A10 با گردوغبار می‌گیرد؛ تمیزکاری یا تعویض ماژول اسپیکر راه‌حل است.','ماژول اسپیکر A10 جداگانه و ارزان است. تست موسیقی در سطوح مختلف صدا وضعیت را مشخص می‌کند.','گلکسی A10','سامسونگ','متفرقه','','اسپیکر','easy','[{"title": "تمیزکاری شبکهٔ اسپیکر", "body": "برس نرم + مکش ملایم؛ الکل مستقیم داخل سوراخ نریزید."}, {"title": "اپ تخلیهٔ صدا", "body": "صدای سینوسی بالا (اپ‌های Speaker Cleaner) رطوبت و غبار را می‌پرانند."}, {"title": "تست با هدست", "body": "اگر با هدست صدا سالم است، مشکل فقط اسپیکر داخلی است."}, {"title": "تعویض ماژول", "body": "در صورت ادامه، ماژول اسپیکر نو نصب شود؛ پیچ و کانکتور را کامل ببندید."}]','','["/uploads/tips/gen/speaker-mesh-macro.jpg"]','','[]','like',0,'public','published','سامسونگ,A10,اسپیکر',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-19 09:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'صدای اسپیکر گلکسی A10 خش می‌دهد یا کم است');

