SELECT @bk_author,@bk_cat,'وای‌فای S22 قطع و وصل می‌شود','با فراموشی شبکه، ریست تنظیمات شبکه و آپدیت، اکثر مشکلات وای‌فای سامسونگ حل می‌شود.','اگر فقط در مودم خانه مشکل دارید، مودم مقصر است. تست در شبکه‌های مختلف مرز نرم‌افزار/سخت‌افزار را مشخص می‌کند.','گلکسی S22','سامسونگ','گلکسی S22','','وای‌فای','easy','[{"title": "فراموشی و اتصال مجدد", "body": "تنظیمات › اتصال‌ها › وای‌فای › شبکه › فراموش کردن."}, {"title": "ریست تنظیمات شبکه", "body": "تنظیمات › مدیریت کلی › ریست › ریست تنظیمات شبکه."}, {"title": "آپدیت نرم‌افزار و مودم", "body": "One UI و فریمور مودم را به‌روز کنید."}, {"title": "تست شبکه‌های مختلف", "body": "خرابی در همهٔ شبکه‌ها + بی‌اثر بودن ریست‌ها = بررسی سخت‌افزاری آنتن."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','سامسونگ,S22,وای‌فای',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-19 13:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'وای‌فای S22 قطع و وصل می‌شود');

