SELECT @bk_author,@bk_cat,'گلکسی A52 به بلوتوث ماشین وصل نمی‌شود','حافظهٔ جفت‌سازی ماشین و گوشی را پاک کنید؛ ناسازگاری پروفایل‌های قدیمی رایج‌ترین علت است.','سیستم‌های صوتی خودرو حافظهٔ اتصال محدودی دارند. پاک کردن از هر دو طرف معمولاً مشکل را حل می‌کند.','گلکسی A52','سامسونگ','گلکسی A52','','بلوتوث خودرو','easy','[{"title": "پاک کردن جفت‌سازی در گوشی", "body": "تنظیمات › اتصال‌ها › بلوتوث › چرخ‌دندهٔ دستگاه › Unpair."}, {"title": "پاک کردن در خودرو", "body": "از منوی خودرو، دستگاه‌های جفت‌شده را پاک کنید."}, {"title": "ریست تنظیمات شبکه", "body": "اگر باز هم نشد، ریست تنظیمات شبکه گوشی."}, {"title": "آپدیت سیستم خودرو", "body": "خیلی از خودروسازها آپدیت بلوتوث منتشر می‌کنند."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','سامسونگ,A52,بلوتوث,خودرو',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-19 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'گلکسی A52 به بلوتوث ماشین وصل نمی‌شود');

