SELECT @bk_author,@bk_cat,'بعد از ضربه، قسمتی از تاچ A50 کار نمی‌کند','ضربه می‌تواند فلکس تاچ را از سوکت جدا یا پنل را آسیب بزند؛ اول جازدن فلکس را امتحان کنید.','A50 پنل AMOLED با سوکت فلکس دارد؛ ضربه گاهی فقط اتصال را شل می‌کند و هزینهٔ تعمیر پایین می‌ماند.','گلکسی A50','سامسونگ','متفرقه','','تاچ ناقص','medium','[{"title": "ریست اجباری", "body": "Volume پایین + Power ۳۰ ثانیه."}, {"title": "باز کردن و جازدن فلکس", "body": "پشت باز، فلکس نمایشگر جدا/جا زده شود؛ اکسیدیشن سوکت تمیز شود."}, {"title": "تست تاچ با کد سرویس", "body": "*#0*# را در شماره‌گیر بزنید و تست Touch اجرا کنید."}, {"title": "تعویض پنل", "body": "اگر ناحیهٔ مرده باقی ماند، پنل آسیب دیده و تعویض لازم است."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','like',0,'public','published','سامسونگ,A50,تاچ,ضربه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-19 21:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بعد از ضربه، قسمتی از تاچ A50 کار نمی‌کند');

