SELECT @bk_author,@bk_cat,'ناحیهٔ پایین صفحهٔ A12 به لمس جواب نمی‌دهد','ناحیهٔ مشخص مرده یعنی آسیب موضعی پنل یا چسب/محافظ معیوب؛ مرحله‌به‌مرحله رد کنید.','پنل A12 ارزان است و تعویضش اقتصادی است؛ ولی قبل از آن محافظ و تنظیمات را رد کنید تا هزینهٔ اضافه ندهید.','گلکسی A12','سامسونگ','گلکسی A12','','ناحیهٔ مرده لمس','medium','[{"title": "بدون محافظ تست", "body": "محافظ صفحه را بردارید و دوباره تست لمس."}, {"title": "تست با کد سرویس", "body": "*#0*# › Touch تا ناحیهٔ مرده دقیق مشخص شود."}, {"title": "بازرسی اتصال", "body": "فلکس نمایشگر جازده و سوکت تمیز شود."}, {"title": "تعویض پنل یکپارچه", "body": "پنل نو (تاچ+LCD) نصب و تست کامل تاچ انجام شود."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','سامسونگ,A12,لمس,نمایشگر',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-20 00:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ناحیهٔ پایین صفحهٔ A12 به لمس جواب نمی‌دهد');

