SELECT @bk_author,@bk_cat,'S22 در سرما با شارژ زیر ۲۰٪ خاموش می‌شود','افت ولتاژ باتری در سرما رفتار طبیعی لیتیوم است ولی خاموشی زودهنگام یعنی باتری فرسوده یا نرم‌افزار بدمیزان.','پرچمدارهای نازک سامسونگ باتری کوچک‌تری دارند و فرسایششان سریع‌تر دیده می‌شود. بهینه‌سازی نرم‌افزاری + باتری سالم مشکل را می‌بندد.','گلکسی S22','سامسونگ','گلکسی S22','','خاموشی در سرما','easy','[{"title": "کالیبراسیون و آپدیت", "body": "یک چرخهٔ کامل شارژ/مصرف و آپدیت One UI."}, {"title": "بررسی مصرف پس‌زمینه", "body": "اپ‌های پر consuming را محدود کنید."}, {"title": "تعویض باتری اگر ادامه داشت", "body": "باتری اصل با ضمانت نصب شود."}, {"title": "توصیهٔ کاربری", "body": "در سرمای شدید گوشی را داخل جیب درونی نگه دارید؛ پاوربانک همراه داشته باشید."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','free',0,'public','published','سامسونگ,S22,سرما,باتری',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-20 03:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'S22 در سرما با شارژ زیر ۲۰٪ خاموش می‌شود');

