SELECT @bk_author,@bk_cat,'گلکسی M31 بعد از تخلیهٔ کامل دیگر روشن نمی‌شود','باتری‌های قدیمی با تخلیهٔ عمیق «می‌خوابند»؛ شارژ طولانی یا شارژ مستقیم باتری آن‌ها را بیدار می‌کند.','مدار حفاظت باتری وقتی ولتاژ خیلی پایین بیاید، خروجی را قطع می‌کند. شارژر معمولی گاهی نمی‌تواند آن را بیدار کند.','گلکسی M31','سامسونگ','متفرقه','','باتری خوابید','medium','[{"title": "شارژ طولانی بی‌وقفه", "body": "گوشی را ۳۰ دقیقه تا چند ساعت به شارژر اصل بزنید و دست نزنید."}, {"title": "شارژر دیگر و کابل سالم", "body": "با آداپتور قوی‌تر تست کنید."}, {"title": "شارژ مستقیم باتری (تعمیرگاه)", "body": "در تعمیرگاه با پاور ساپلای مستقیم روی ترمینال باتری ولتاژ احیا می‌شود."}, {"title": "تعویض باتری", "body": "اگر باتری دیگر احیا نشد، تعویض لازم است؛ از تخلیهٔ کامل مکرر بپرهیزید."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg", "/uploads/tips/gen/charger-and-cable.jpg"]','','[]','like',0,'public','published','سامسونگ,M31,باتری خواب',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-20 09:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'گلکسی M31 بعد از تخلیهٔ کامل دیگر روشن نمی‌شود');

