SELECT @bk_author,@bk_cat,'لکه‌های سوختگی (Burn-in) روی صفحهٔ S23','باقی‌ماندن تصویر ثابت روی AMOLED معمولاً دائمی است؛ پیشگیری و کاهش شدت، راهکارهای عملی دارند.','نوارهای ثابت (نوار وضعیت، دکمه‌ها) با زمان روی پنل حک می‌شوند. نرم‌افزارهای بازسازی پیکسل فقط موارد خفیف را کم می‌کنند.','گلکسی S23','سامسونگ','گلکسی S23','','سوختگی صفحه','hard','[{"title": "تست Burn-in", "body": "تصویر خاکستری تمام‌صفحه را نمایش دهید؛ سایه‌های ثابت را می‌بینید."}, {"title": "بازسازی پیکسل", "body": "برخی اپ‌ها/سرویس‌ها چرخهٔ بازسازی رنگ اجرا می‌کنند؛ روی موارد خفیف مؤثر است."}, {"title": "کاهش دائمی عوامل", "body": "Time-out کوتاه، تم تیره و عدم نمایش ثابت (Always-On) را کم کنید تا پیشرفت متوقف شود."}, {"title": "تعویض پنل در موارد شدید", "body": "تنها راه‌حل قطعی پنل نو است؛ هزینه را با ارزش گوشی بسنجید."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','paid',35000,'public','published','سامسونگ,S23,Burn-in,AMOLED',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-20 13:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'لکه‌های سوختگی (Burn-in) روی صفحهٔ S23');

