SELECT @bk_author,@bk_cat,'صفحهٔ A52 گاه‌گاهی چشمک و پرش رنگ می‌زند','چشمک می‌تواند از تنظیم روشنایی خودکار، فلکس شل یا شروع خرابی پنل باشد.','اول نرم‌افزار، بعد اتصال، آخر پنل. این ترتیب هزینه را کم می‌کند و در تعمیرگاه‌ها هم به همین صورت پیش می‌روند.','گلکسی A52','سامسونگ','گلکسی A52','','چشمک صفحه','medium','[{"title": "خاموش کردن روشنایی خودکار", "body": "اگر چشمک در تغییر نور بود، مشکل سنسور یا تنظیم است."}, {"title": "Safe Mode", "body": "اپ ثالث معیوب هم می‌تواند نمایشگر را به هم بریزد؛ در Safe تست کنید."}, {"title": "جازدن فلکس نمایشگر", "body": "پشت باز، سوکت تمیز و فلکس محکم جا زده شود."}, {"title": "تعویض پنل", "body": "در صورت ادامه، پنل نو نصب و تست کشیده (چند ساعت) انجام شود."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','سامسونگ,A52,چشمک,نمایشگر',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-20 15:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'صفحهٔ A52 گاه‌گاهی چشمک و پرش رنگ می‌زند');

