SELECT @bk_author,@bk_cat,'تعویض شیشهٔ پشت گلکسی A32 (پشت شیشه‌ای)','پشت شیشه‌ای با چسب قوی نصب است؛ با حرارت، ساکشن و صبر بدون شکستن دوربین جدا می‌شود.','A32 پشت شیشه‌ای دارد و دوربین‌ها روی درب پشت هستند؛ در جدا کردن باید مراقب فلکس دوربین‌ها بود.','گلکسی A32','سامسونگ','گلکسی A32','','ترک شیشه پشت','medium','[{"title": "گرام دادن کل سطح", "body": "هیتر یا سشوار صنعتی تا ~۸۰ درجه."}, {"title": "ساکشن و پیک", "body": "از گوشهٔ پایین شروع کنید؛ فلکس دوربین پشت را جدا نکنید، فقط مراقب باشید."}, {"title": "خروج درب پشت", "body": "اگر دوربین‌ها روی درب‌اند، فلکس‌هایشان جدا و درب آزاد شود."}, {"title": "نصب درب نو", "body": "چسب آب‌بندی نو و مونتاژ معکوس؛ تست دوربین و شارژ بی‌سیم (در صورت وجود)."}]','هیتر، ساکشن، پیک، چسب آب‌بندی','["/uploads/tips/gen/heat-gun-backcover.jpg"]','','[]','free',0,'public','published','سامسونگ,A32,شیشه پشت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-20 18:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض شیشهٔ پشت گلکسی A32 (پشت شیشه‌ای)');

