SELECT @bk_author,@bk_cat,'شیشهٔ پشت S21 خرد شده — تعویض اصولی با ریسک کم','شیشهٔ پشت S21 با لیزر یا برش سیمی جدا می‌شود؛ تکنیک‌های خانگی کویل شارژ و دوربین را می‌شکنند.','در گوشی‌های شیشه‌ای پرچمدار، درب پشت با چسب مقتدر چسبیده. حرفه‌ای‌ها با لیزر مسیر چسب را می‌برند تا شیشه بدون خرد شدن برداشته شود.','گلکسی S21','سامسونگ','گلکسی S21','','شکستن شیشه پشت','hard','[{"title": "ایمن‌سازی", "body": "خرده‌شیشه‌های شل را با چسب کاغذی بپوشانید تا هنگام کار نریزند."}, {"title": "برش چسب", "body": "لیزر یا برش سیمی چاش دور درب را آزاد می‌کند."}, {"title": "نصب درب نو", "body": "درب نو با واشر آب‌بندی و چسب نو نصب شود."}, {"title": "تست پس از مونتاژ", "body": "شارژ بی‌سیم، NFC، آنتن‌ها و دوربین‌ها تست شوند."}]','','["/uploads/tips/gen/heat-gun-backcover.jpg"]','','[]','like',0,'public','published','سامسونگ,S21,شیشه پشت',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-20 22:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'شیشهٔ پشت S21 خرد شده — تعویض اصولی با ریسک کم');

