SELECT @bk_author,@bk_cat,'کابل شارژ در A51 شل است و می‌افتد','استهلاک فنر Type-C رایج است؛ تعویض فلکس پورت A51 ارزان و سریع است.','قبل از تعویض، مطمئن شوید مشکل از کابل نیست؛ سپس فلکس پورت را تعویض کنید. میکروفون پایین روی همان فلکس است.','گلکسی A51','سامسونگ','متفرقه','','پورت شل','medium','[{"title": "تست با چند کابل", "body": "اگر همه شل‌اند، پورت گوشی معیوب است."}, {"title": "باز کردن گوشی", "body": "پشت شیشه‌ای با حرارت باز و باتری جدا شود."}, {"title": "تعویض فلکس پورت", "body": "فلکس نو (پورت+میکروفون+آنتن) نصب شود."}, {"title": "تست", "body": "شارژ، داده و میکروفون پایین تست و گوشی با چسب نو بسته شود."}]','','["/uploads/tips/gen/wet-usb-port.jpg"]','','[]','free',0,'public','published','سامسونگ,A51,پورت,Type-C',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-20 23:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'کابل شارژ در A51 شل است و می‌افتد');

