SELECT @bk_author,@bk_cat,'گلکسی A32 آب خورده — اقدامات فوری و تعمیر حرفه‌ای','هرگز گوشی خیس را شارژ نکنید؛ خاموش، خشک و سریع به تعمیرکار حرفه‌ای.','ویدئوهای فارسی متعددی (مثل شهر سخت‌افزار در آپارات) مراحل نجات گوشی آب‌خورده را آموزش می‌دهند. اصل طلایی: خاموشی سریع و باز شدن زودهنگام.','گلکسی A32','سامسونگ','گلکسی A32','','آب‌خوردگی','hard','[{"title": "خاموش فوری", "body": "خاموش کنید و شارژ نزنید؛ جریان روی مدار خیس، خوردگی سریع می‌سازد."}, {"title": "خشک اولیه", "body": "پارچه، تکان ملایم، هوای خنک فن. برنج فوریهٔ اطمینان نیست ولی بی‌ضرر است."}, {"title": "باز شدن کامل و شست‌وشو", "body": "باتری جدا، برد با اولتراسونیک الکل شسته، سوکت‌ها تمیز و خشک می‌شوند."}, {"title": "بازرسی و تست کشیده", "body": "خوردگی‌ها زیر میکروسکوپ بازلحیم و تست چندروزه انجام شود؛ مشکلات اکسیدیشن گاهی دیر ظاهر می‌شوند."}]','','["/uploads/tips/gen/phone-in-rice.jpg", "/uploads/tips/gen/wet-usb-port.jpg"]','https://www.aparat.com/v/n689wo4','[]','free',0,'public','published','سامسونگ,A32,آب‌خوردگی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-21 03:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'گلکسی A32 آب خورده — اقدامات فوری و تعمیر حرفه‌ای');

