SELECT @bk_author,@bk_cat,'شست‌وشوی برد A50 بعد از آب‌خوردگی با اولتراسونیک','برد گوشی آب‌خورده با الکل ایزوپروپیل و اولتراسونیک شسته می‌شود؛ آب معمولی هرگز.','الکل ایزوپروپیل ۹۹٪ آب و نمک را حل می‌کند و سریع تبخیر می‌شود. اولتراسونیک ذرات خوردگی را از زیر تراشه‌ها می‌شوید.','گلکسی A50','سامسونگ','متفرقه','','آب‌خوردگی','hard','[{"title": "تخلیهٔ کامل", "body": "باتری و همهٔ فلکس‌ها جدا شوند."}, {"title": "اولتراسونیک الکل", "body": "برد ۳ تا ۵ دقیقه در دستگاه اولتراسونیک با الکل."}, {"title": "خشک‌کاری", "body": "با هیتر ملایم یا جریان هوای خنک کامل خشک شود."}, {"title": "بازرسی و تعمیر خوردگی", "body": "سوکت‌ها و مسیرهای خورده بازلحیم و در صورت نیاز سیم‌کشی انجام شود."}]','دستگاه اولتراسونیک، الکل ایزوپروپیل ۹۹٪، هیتر، میکروسکوپ','["/uploads/tips/gen/esd-workspace.jpg", "/uploads/tips/mobile/board-under-microscope.jpg"]','','[]','free',0,'public','published','سامسونگ,A50,اولتراسونیک,برد',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-21 05:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'شست‌وشوی برد A50 بعد از آب‌خوردگی با اولتراسونیک');

