SELECT @bk_author,@bk_cat,'دوربین S21 تار عکس می‌گیرد','تاری می‌تواند از چربی لنز، خراش شیشه یا خرابی موتور فوکوس باشد؛ از ساده به سخت چک کنید.','پرچمدارهای سامسونگ سنسورهای بزرگ دارند که فوکوس نزدیک را گاهی اشتباه می‌گیرد؛ عکس ماکرو را با فاصلهٔ درست بگیرید.','گلکسی S21','سامسونگ','گلکسی S21','','دوربین تار','easy','[{"title": "تمیزکاری", "body": "میکروفایبر؛ اثر انگشت رایج‌ترین علت."}, {"title": "تست فوکوس در حالت Pro", "body": "فوکوس دستی را از نزدیک تا دور حرکت دهید؛ اگر نمودار فوکوس کار می‌کند، سنسور سالم است."}, {"title": "ریست دوربین", "body": "کش اپ دوربین پاک و ریست اجباری بزنید."}, {"title": "تعویض ماژول", "body": "اگر موتور فوکوس صدا می‌دهد یا فوکوس نمی‌گیرد، ماژول تعویض شود."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','like',0,'public','published','سامسونگ,S21,دوربین تار',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-21 08:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'دوربین S21 تار عکس می‌گیرد');

