SELECT @bk_author,@bk_cat,'فلش دوربین A52 کار نمی‌کند','فلش و چراغق روی یک مدارند؛ تست چراغق، تعویض فلکس درب پشت و ماژول LED ترتیب تعمیر است.','درب پشت A52 فلکس فلش را دارد؛ تعویضش ساده است. دمای بالای گوشی هم فلش را موقتاً قفل می‌کند.','گلکسی A52','سامسونگ','گلکسی A52','','فلش دوربین','easy','[{"title": "تست چراغق و دما", "body": "در محیط خنک و بدون حالت کم‌مصرف تست کنید."}, {"title": "باز کردن درب پشت", "body": "حرارت و پیک؛ فلکس فلش بازرسی شود."}, {"title": "تعویض فلکس", "body": "فلکس نو نصب شود."}, {"title": "تعویض ماژول LED", "body": "در صورت ادامه، ماژول فلش تعویض و تست نهایی."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','free',0,'public','published','سامسونگ,A52,فلش',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-21 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'فلش دوربین A52 کار نمی‌کند');

