SELECT @bk_author,@bk_cat,'اثر انگشت A12 (پشت گوشی) کار نمی‌کند','سنسور پشتی A12 روی فلکس جداگانه است؛ تمیزکاری، ثبت مجدد و تعویض فلکس ترتیب کار است.','سنسور پشتی در برابر خش و گردوغبار حساس است. خرابی آن در A12 معمولاً با تعویض فلکس سنسور حل می‌شود.','گلکسی A12','سامسونگ','گلکسی A12','','سنسور اثر انگشت','medium','[{"title": "تمیز و ثبت مجدد", "body": "سنسور را تمیز و انگشت‌ها را دوباره ثبت کنید."}, {"title": "تست کد سرویس", "body": "*#0*# › تست اثر انگشت."}, {"title": "باز کردن و بازرسی فلکس", "body": "پشت باز، فلکس سنسور جازده و سوکت تمیز شود."}, {"title": "تعویض فلکس سنسور", "body": "در صورت خرابی، فلکس نو (ارزان) نصب و تست."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','paid',25000,'public','published','سامسونگ,A12,اثر انگشت',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-21 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'اثر انگشت A12 (پشت گوشی) کار نمی‌کند');

