SELECT @bk_author,@bk_cat,'Face Unlock در S23 با عینک یا در تاریکی کار نمی‌کند','Face Unlock سامسونگ فقط دوربین جلو است (بدون سنسور عمق) و در تاریکی ضعیف است؛ طبیعت ابزار را بشناسید.','برخلاف آیفون، تشخیص چهرهٔ سامسونگ برای پرداخت‌های امن توصیه نمی‌شود؛ اثر انگشت زیر نمایشگر جایگزین امن‌تری است.','گلکسی S23','سامسونگ','گلکسی S23','','Face Unlock','easy','[{"title": "ثبت مجدد چهره", "body": "در نور خوب و بدون عینک ثبت کنید؛ گزینهٔ «استفاده در تاریکی» را فعال کنید."}, {"title": "افزودن ظاهر دوم", "body": "ثبت دوم بدون عینک، تشخیص را بهتر می‌کند."}, {"title": "اولویت اثر انگشت", "body": "برای کارهای امن از اثر انگشت استفاده کنید."}, {"title": "بررسی دوربین جلو", "body": "اگر دوربین جلو هم خراب است، ماژول آن تعویض شود."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','like',0,'public','published','سامسونگ,S23,Face Unlock',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-21 20:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'Face Unlock در S23 با عینک یا در تاریکی کار نمی‌کند');

