SELECT @bk_author,@bk_cat,'A12 سیم‌کارت را نمی‌شناسد','سینی خمیده و سیم‌کارت قدیمی رایج‌ترین علت‌ها هستند؛ بعد نرم‌افزار و آخر مدار.','سینی‌های متال ارزان گاهی کامل نمی‌نشینند و سوییچ تشخیص را فعال نمی‌کنند.','گلکسی A12','سامسونگ','گلکسی A12','','سیم‌کارت','easy','[{"title": "سیم‌کارت و سینی دیگر", "body": "سیم‌کارت سالم در گوشی دیگر و سینی اصل گوشی تست شود."}, {"title": "ریست شبکه و آپدیت", "body": "ریست تنظیمات شبکه + آپدیت نرم‌افزار."}, {"title": "تست Safe Mode", "body": "اپ ثالثی که رادیو را مزاحم می‌کند نادر ولی ممکن است."}, {"title": "سوکت سیم‌کارت", "body": "در صورت ادامه، سوکت SIM و پین‌هایش بررسی و در صورت نیاز تعمیر برد."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','سامسونگ,A12,سیم‌کارت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-22 02:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'A12 سیم‌کارت را نمی‌شناسد');

