SELECT @bk_author,@bk_cat,'S21 روی لوگوی سامسونگ گیر کرده','اول Recovery و Wipe Cache؛ بعد فلش با Odin؛ آخر بررسی برد و UFS.','پرچمدارها معمولاً با فلش رسمی Odin درست می‌شوند. حتماً قبل از فلش، اگر دسترسی دارید بکاپ بگیرید.','گلکسی S21','سامسونگ','گلکسی S21','','گیر لوگو','hard','[{"title": "Recovery و Wipe Cache", "body": "Volume پایین+Power برای خاموشی؛ سپس Volume بالا+Power برای Recovery؛ Cache Partition را پاک کنید."}, {"title": "دانلود فریمور رسمی", "body": "از سامسونگ (مثل sammobile یا SamFw) فریمور مدل دقیق (SM-G991B و...) را بگیرید."}, {"title": "فلش با Odin", "body": "در حالت Download Mode، فایل‌های AP/BL/CP/CSC را فلش کنید (CSC کامل = پاک شدن داده)."}, {"title": "اگر فلش fail شد", "body": "خطاهای Odin مثل fail یا گیر، مسیر UFS/برد را نشان می‌دهد؛ تعمیر تخصصی لازم است."}]','کامپیوتر، کابل اصل، نرم‌افزار Odin، فریمور رسمی','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','سامسونگ,S21,لوگو,Odin',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-22 05:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'S21 روی لوگوی سامسونگ گیر کرده');

