SELECT @bk_author,@bk_cat,'تعویض تاچ و ال‌سی‌دی ردمی نوت ۹ — آموزش گام‌به‌گام','پنل ردمی نوت ۹ یکپارچه است و از پشت گوشی باز می‌شود؛ آموزش ویدیویی فارسی آن در آپارات موجود است.','ردمی نوت ۹ از پرترددترین گوشی‌های ایران است. تعویض پنل آن با باز کردن پشت شیشه‌ای و پیچ‌های قاب میانی انجام می‌شود.','ردمی نوت ۹','شیائومی','ردمی نوت 9','','شکستن نمایشگر','medium','[{"title": "باز کردن پشت شیشه‌ای", "body": "با هیتر ~۸۰ درجه و ساکشن؛ پیک پلاستیکی برای آزاد کردن چسب."}, {"title": "قطع باتری", "body": "اول فلکس باتری جدا شود."}, {"title": "باز کردن پیچ‌های قاب و پنل", "body": "پیچ‌ها باز و فلکس نمایشگر آزاد؛ پنل با حرارت ملایم از قاب جدا می‌شود."}, {"title": "نصب پنل نو", "body": "پنل نو جا زده، تست تاچ/تصویر و مونتاژ با چسب نو انجام شود."}]','','["/uploads/tips/gen/cracked-display.jpg", "/uploads/tips/gen/screws-organization-mat.jpg"]','https://www.aparat.com/v/xkskb1b','[]','free',0,'public','published','شیائومی,ردمی نوت ۹,نمایشگر',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-22 13:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض تاچ و ال‌سی‌دی ردمی نوت ۹ — آموزش گام‌به‌گام');

