SELECT @bk_author,@bk_cat,'ریست فکتوری ردمی نوت ۱۱ از ریکاوری (فراموشی رمز)','از منوی Recovery می‌توانید گوشی را Wipe کنید؛ یادتان باشد حساب Mi/گوگل لازم است تا قفل فعال‌سازی نیفتد.','ویدئوهای «هارد ریست» شیائومی در آپارات فراوان‌اند. بعد از ریست، گوشی با حسابی که قبلاً روی آن بود قفل می‌شود؛ پس رمز آن حساب را بدانید.','ردمی نوت ۱۱','شیائومی','ردمی نوت 11','','فراموشی رمز','medium','[{"title": "ورود به Recovery", "body": "گوشی خاموش؛ Volume بالا + Power را نگه دارید تا منوی بیاید."}, {"title": "Wipe Data", "body": "گزینهٔ Wipe Data را با دکمهٔ Power تأیید کنید."}, {"title": "Reboot", "body": "بعد از اتمام، Reboot to system بزنید."}, {"title": "ورود حساب", "body": "با Mi Account و اکانت گوگل قبلی وارد شوید تا FRP/قفل Mi رفع شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','https://www.aparat.com/v/c1juR','[]','free',0,'public','published','شیائومی,ردمی نوت ۱۱,ریست فکتوری,رمز',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-22 15:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ریست فکتوری ردمی نوت ۱۱ از ریکاوری (فراموشی رمز)');

