SELECT @bk_author,@bk_cat,'ردمی ۹ خودش خاموش می‌شود — باتری یا نرم‌افزار؟','خاموشی هنگام بازی یا شارژ کم = باتری؛ خاموشی تصادفی = نرم‌افزار/اتصال.','ردمی ۹ باتری ۵۰۲۰ میلی‌آمپری دارد؛ اگر باتری اصلی بوده باشد بعد از ۲-۳ سال فرسوده می‌شود.','ردمی ۹','شیائومی','متفرقه','','خاموشی ناگهانی','easy','[{"title": "تشخیص الگو", "body": "موقعیت خاموشی‌ها را یادداشت کنید."}, {"title": "کالیبراسیون و آپدیت", "body": "یک چرخهٔ کامل شارژ + آپدیت MIUI."}, {"title": "تعویض باتری", "body": "باتری نو (BM23/BM2X مدل درست) نصب؛ پشت گوشی با پیک باز می‌شود."}, {"title": "ریست کارخانه", "body": "اگر با باتری سالم ادامه داشت، بعد از بکاپ ریست کنید."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','paid',65000,'public','published','شیائومی,ردمی ۹,خاموشی,باتری',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-22 18:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ردمی ۹ خودش خاموش می‌شود — باتری یا نرم‌افزار؟');

