SELECT @bk_author,@bk_cat,'پوکو X3 شارژ نمی‌شود — پورت Type-C','پوکو X3 سوکت پرمشکل دارد؛ تمیزکاری، کابل ۳۳ وات اصل و تعویض فلکس پورت ترتیب کار است.','پوکو X3 از شارژ سریع ۳۳ وات پشتیبانی می‌کند؛ اگر با آداپتور اصل هم کند شارژ می‌شود، فلکس پورت مشکوک است.','پوکو X3','شیائومی','پوکو X3','','شارژ نمی‌شود','medium','[{"title": "تمیزکاری پورت", "body": "گردوغبار و پرز داخل پورت با خلال و برس تمیز شود."}, {"title": "تست آداپتور ۳۳ وات اصل", "body": "آداپتور اصل شیائومی (MDY-11-EX) و کابل 3A تست شود."}, {"title": "بررسی پیام شارژ سریع", "body": "اگر پیام شارژ سریع نمی‌آید، مذاکرهٔ PD خراب است؛ فلکس پورت تعویض شود."}, {"title": "تعویض فلکس", "body": "پشت باز، فلکس نو نصب؛ میکروفون پایین هم روی همین فلکس است."}]','','["/uploads/tips/gen/wet-usb-port.jpg", "/uploads/tips/gen/charger-and-cable.jpg"]','','[]','like',0,'public','published','شیائومی,پوکو X3,شارژ',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-22 21:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'پوکو X3 شارژ نمی‌شود — پورت Type-C');

