SELECT @bk_author,@bk_cat,'وای‌فای ردمی ۱۰ قطع و وصل می‌شود','ریست شبکه، فراموشی مودم و آپدیت MIUI را انجام دهید؛ ناسازگاری روتینگ مودم هم رایج است.','اگر فقط در خانه مشکل دارید، کانال مودم را عوض کنید (۱/۶/۱۱) و باند ۵ گیگاهرتز را تست کنید.','ردمی ۱۰','شیائومی','متفرقه','','وای‌فای','easy','[{"title": "فراموشی و وصل مجدد", "body": "شبکه را فراموش و با رمز جدید وصل شوید."}, {"title": "ریست تنظیمات شبکه", "body": "تنظیمات › اتصال و اشتراک › ریست Wi-Fi و بلوتوث."}, {"title": "آپدیت MIUI", "body": "آپدیت‌های رادیو را نصب کنید."}, {"title": "تست شبکه‌های دیگر", "body": "اگر همه‌جا مشکل است، ماژول وای‌فای سخت‌افزاری بررسی شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','شیائومی,ردمی ۱۰,وای‌فای',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-24 03:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'وای‌فای ردمی ۱۰ قطع و وصل می‌شود');

