SELECT @bk_author,@bk_cat,'پوکو X3 Pro ریستارت‌های تکراری (مشکل شناخته‌شدهٔ مادربرد)','ریستارت‌های تصادفی X3 Pro معروف است؛ معمولاً مشکل برد (Power IC) است و تعمیر تخصصی لازم دارد.','این مشکل در سری X3 Pro شناخته‌شده است؛ گاهی با فلش مجدد موقتاً برطرف می‌شود ولی ریشه سخت‌افزاری دارد.','پوکو X3 پرو','شیائومی','پوکو X3','','ریستارت مکرر','hard','[{"title": "فلش Fastboot", "body": "با MiFlash و فریمور رسمی فلش کامل کنید تا نرم‌افزار رد شود."}, {"title": "بررسی دما و باتری", "body": "داغی شدید یا باتری معیوب هم ریستارت می‌دهد؛ رد کنید."}, {"title": "تعمیر برد", "body": "Power/PMIC زیر میکروسکوپ بازرسی و در صورت نیاز بازلحیم/تعویض IC."}, {"title": "تصمیم اقتصادی", "body": "اگر هزینهٔ برد بالاست، با تعمیرکار دربارهٔ ارزش گوشی مشورت کنید."}]','','["/uploads/tips/mobile/board-under-microscope.jpg"]','','[]','free',0,'public','published','شیائومی,پوکو X3 Pro,ریستارت,برد',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-24 06:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'پوکو X3 Pro ریستارت‌های تکراری (مشکل شناخته‌شدهٔ مادربرد)');

