SELECT @bk_author,@bk_cat,'بلوتوث ردمی نوت ۱۱ جفت نمی‌شود','پاک کردن جفت‌سازی‌ها و ریست شبکه بلوتوث را درست می‌کند؛ MIUI هم گاهی باگ اتصال دارد.','قبل از تعمیر، دستگاه مقصد را هم ریست کنید؛ نیمی از مشکلات بلوتوث از سمت هدفون/ماشین است.','ردمی نوت ۱۱','شیائومی','ردمی نوت 11','','بلوتوث','easy','[{"title": "Unpair همه", "body": "دستگاه‌های جفت‌شده را پاک کنید."}, {"title": "ریست Wi-Fi/بلوتوث", "body": "از تنظیمات اتصال."}, {"title": "آپدیت MIUI", "body": "آپدیت‌های سازگاری بلوتوث نصب شود."}, {"title": "تست با هدفون دیگر", "body": "اگر با هیچ دستگاهی جفت نشد، ماژول بلوتوث بررسی سخت‌افزاری شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','like',0,'public','published','شیائومی,ردمی نوت ۱۱,بلوتوث',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-24 09:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بلوتوث ردمی نوت ۱۱ جفت نمی‌شود');

