SELECT @bk_author,@bk_cat,'تعویض پنل AMOLED ردمی نوت ۱۰ پرو با حفظ اثر انگشت','سنسور اثر انگشت زیرنمایشگری نوت ۱۰ پرو به کیفیت پنل حساس است؛ پنل اصل یا گرید A بگیرید.','پنل‌های کپی AMOLED اثر انگشت زیرنمایشگری را بی‌دقت می‌کنند. هزینهٔ بیشتر برای پنل باکیفیت، جبران می‌شود.','ردمی نوت ۱۰ پرو','شیائومی','ردمی نوت 10','','شکستن نمایشگر AMOLED','hard','[{"title": "خرید پنل سازگار", "body": "مدل دقیق (M2101K6P و...) را چک کنید؛ پنل اصل/Service Pack."}, {"title": "باز کردن پشت شیشه‌ای", "body": "هیتر + ساکشن + پیک؛ باتری را جدا کنید."}, {"title": "تعویض و انتقال قطعات", "body": "بلندگو، دوربین جلو و سنسورها به پنل نو منتقل شوند."}, {"title": "ثبت مجدد اثر انگشت", "body": "بعد از مونتاژ، انگشت‌ها را دوباره ثبت و دقت را تست کنید."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','شیائومی,ردمی نوت ۱۰ پرو,AMOLED,اثر انگشت',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-24 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض پنل AMOLED ردمی نوت ۱۰ پرو با حفظ اثر انگشت');

