SELECT @bk_author,@bk_cat,'ردمی ۹ داخل آب افتاد — برنامهٔ نجات گام‌به‌گام','خاموشی سریع، شارژ نکردن و باز شدن حرفه‌ای در ۲۴ ساعت اول، شانس نجات را چند برابر می‌کند.','خوردگی الکتروشیمیایی از لحظهٔ تماس آب شروع می‌شود. باز شدن و شست‌وشو با الکل تنها راه متوقف کردنش است.','ردمی ۹','شیائومی','متفرقه','','آب‌خوردگی','hard','[{"title": "خاموش و بی‌شارژ", "body": "فوراً خاموش؛ تا تعمیر حرفه‌ای شارژ نزنید."}, {"title": "خشک اولیه و حمل درست", "body": "پارچه + هوای فن؛ در کیسهٔ زیپ‌دار با جاذبهٔ رطوبت ببرید."}, {"title": "تخلیهٔ کامل و اولتراسونیک", "body": "باتری جدا، برد در اولتراسونیک با ایزوپروپیل شسته و خشک شود."}, {"title": "تست مرحله‌ای ماژول‌ها", "body": "نمایشگر، دوربین، میکروفون و شارژ تک‌به‌تک تست؛ خوردگی‌های پنهان با تست کشیده پیدا می‌شوند."}]','','["/uploads/tips/gen/phone-in-rice.jpg", "/uploads/tips/gen/wet-usb-port.jpg"]','','[]','free',0,'public','published','شیائومی,ردمی ۹,آب‌خوردگی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-24 17:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ردمی ۹ داخل آب افتاد — برنامهٔ نجات گام‌به‌گام');

