SELECT @bk_author,@bk_cat,'سوکت شارژ پوکو X3 NFC — تعویض فلکس کامل','فلکس پورت X3 شامل میکروفون و آنتن هم هست؛ تعویض کامل فلکس بهتر از تعویض سوکت تنهاست.','در تعمیرگاه‌ها معمولاً کل فلکس عوض می‌شود چون سوکت روی فلکس لحیم شده و تعویض تک‌سوکت با هویه مهارت می‌خواهد.','پوکو X3 NFC','شیائومی','پوکو X3','','سوکت شارژ','medium','[{"title": "تست", "body": "با کابل اصل و کابل دیگر؛ اگر شل بودن ماند، فلکس مقصر."}, {"title": "باز کردن", "body": "پشت شیشه‌ای با حرارت باز؛ باتری جدا."}, {"title": "تعویض فلکس", "body": "پیچ‌های فلکس باز، فلکس نو جا زده."}, {"title": "تست کامل", "body": "شارژ سریع ۳۳ وات، میکروفون پایین و آنتن‌ها تست شوند."}]','','["/uploads/tips/gen/wet-usb-port.jpg", "/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','like',0,'public','published','شیائومی,پوکو X3 NFC,فلکس پورت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-24 20:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'سوکت شارژ پوکو X3 NFC — تعویض فلکس کامل');

