SELECT @bk_author,@bk_cat,'ردمی نوت ۸ پرو بدون مصرف سنگین هم داغ است','داغی بدون بار = اپ معیوب پس‌زمینه، باتری فرسوده یا مشکل برد؛ از نرم‌افزار شروع کنید.','Mediatek Helio G90T ذاتاً گرم‌تر است ولی داغی دائمی غیرعادی است. مصرف لحظه‌ای را با ابزارهای MIUI ببینید.','ردمی نوت ۸ پرو','شیائومی','متفرقه','','داغ شدن شدید','medium','[{"title": "بازرسی مصرف", "body": "تنظیمات › باتری › مصرف اپ‌ها؛ اپ پرمصرف پنهان را ببندید/حذف کنید."}, {"title": "Malware Scan", "body": "اپ‌های نصب‌شده از منابع ناامن را حذف و اسکن کنید."}, {"title": "تست بدون شارژر", "body": "اگر فقط حین شارژ داغ است، آداپتور/کابل اصل تست شود."}, {"title": "بازرسی سخت‌افزار", "body": "اگر داغی بلاوقف است، باتری تعویض و در صورت ادامه، برد بازرسی شود."}]','','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','paid',45000,'public','published','شیائومی,ردمی نوت ۸ پرو,داغی',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-25 00:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ردمی نوت ۸ پرو بدون مصرف سنگین هم داغ است');

