SELECT @bk_author,@bk_cat,'ردمی 9A شارژ نمی‌شود — ارزان‌ترین راه‌حل‌ها اول','پورت کثیف، کابل فرسوده و آداپتور ضعیف ۸۰٪ موارد را می‌سازند.','ردمی 9A با شارژر ۱۰ وات می‌آید؛ اگر حتی با شارژر اصل هم شارژ نمی‌شود، فلکس پورت یا مدار شارژ بررسی شود.','ردمی 9A','شیائومی','متفرقه','','شارژ نمی‌شود','easy','[{"title": "تمیزکاری پورت", "body": "خلال و برس؛ پرز رایج‌ترین علت."}, {"title": "تست ست شارژ دیگر", "body": "کابل + آداپتور سالم دیگر."}, {"title": "ریست نرم‌افزاری", "body": "ریست اجباری (Power ۱۵ ثانیه) و آپدیت."}, {"title": "تعویض فلکس پورت", "body": "فلکس ارزان 9A تعویض و تست."}]','','["/uploads/tips/gen/wet-usb-port.jpg"]','','[]','free',0,'public','published','شیائومی,ردمی 9A,شارژ',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-25 04:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ردمی 9A شارژ نمی‌شود — ارزان‌ترین راه‌حل‌ها اول');

