SELECT @bk_author,@bk_cat,'درصد باتری نوت ۱۱ پرو می‌پرد','کالیبراسیون چرخهٔ کامل + به‌روزرسانی MIUI اکثر پرش‌ها را منظم می‌کند.','پرش درصد یعنی متر حجمی باتری با واقعیت هماهنگ نیست؛ با باتری فرسوده هم پیش می‌آید هم بعد آپدیت.','ردمی نوت ۱۱ پرو','شیائومی','ردمی نوت 11','','پرش درصد باتری','easy','[{"title": "چرخهٔ کامل", "body": "۱۰۰٪ تا خاموشی، بعد شارژ بی‌وقفه تا ۱۰۰٪."}, {"title": "آپدیت MIUI", "body": "آپدیت‌های مدیریت باتری نصب شود."}, {"title": "بررسی باتری", "body": "در تعمیرگاه با پاور/تست سخت‌افزاری، سلامت باتری سنجیده شود."}, {"title": "تعویض در صورت فرسودگی", "body": "باتری نو (BM58/BM59 سازگار با مدل) نصب."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','free',0,'public','published','شیائومی,ردمی نوت ۱۱ پرو,باتری',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-25 05:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'درصد باتری نوت ۱۱ پرو می‌پرد');

