SELECT @bk_author,@bk_cat,'آموزش تعویض باتری ردمی 10C','پشت 10C پلاستیکی است و باز کردنش آسان‌تر از شیشه‌ای‌هاست؛ با پیک و حرارت کم.','برای تازه‌کارها، گوشی‌های پشت‌پلاستیکی مثل 10C بهترین تمرین تعویض باتری هستند.','ردمی 10C','شیائومی','متفرقه','','تعویض باتری','medium','[{"title": "باز کردن پشت", "body": "از گوشهٔ پایین با پیک؛ حرارت ملایم برای چسب."}, {"title": "قطع فلکس باتری", "body": "اولین کار بعد از باز شدن."}, {"title": "خروج باتری", "body": "نوارهای چسب را موازی بکشید؛ الکل در صورت نیاز."}, {"title": "نصب و تست", "body": "باتری نو، چسب نو، تست شارژدهی کامل."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg", "/uploads/tips/gen/disconnect-battery-flex.jpg"]','','[]','like',0,'public','published','شیائومی,ردمی 10C,باتری',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-25 09:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آموزش تعویض باتری ردمی 10C');

