SELECT @bk_author,@bk_cat,'پوکو M4 روشن است ولی صفحه سیاه است','ریست اجباری، تست با اعلان و تست پنل دیگر؛ احتمال خرابی پنل AMOLED بالا است.','پنل‌های AMOLED گاهی بعد از ضربه یا عیب تراشهٔ پنل کامل سیاه می‌شوند در حالی که گوشی کار می‌کند.','پوکو M4','شیائومی','متفرقه','','صفحه سیاه','medium','[{"title": "ریست اجباری", "body": "Power + Volume بالا ۲۰ ثانیه."}, {"title": "تست با زنگ", "body": "از خط دیگر تماس بگیرید؛ زنگ زدن = گوشی سالم و پنل مشکوک."}, {"title": "جازدن فلکس", "body": "پشت باز، فلکس نمایشگر جازده و تمیز."}, {"title": "تعویض پنل", "body": "پنل نو نصب؛ اگر با پنل سالم هم سیاه بود، برد تخصصی بررسی شود."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','شیائومی,پوکو M4,صفحه سیاه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-25 12:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'پوکو M4 روشن است ولی صفحه سیاه است');

