SELECT @bk_author,@bk_cat,'دوربین ۱۰۸ مگاپیکسلی نوت ۹ پرو تار شده','تاری می‌تواند از چربی، شل بودن ماژول یا غبار زیر شیشه باشد؛ تمیزکاری داخلی مؤثر است.','سنسور بزرگ نوت ۹ پرو به گردوغبار زیر شیشهٔ لنز حساس است؛ با باز کردن پشت می‌توان شیشهٔ داخلی را تمیز کرد.','ردمی نوت ۹ پرو','شیائومی','متفرقه','','دوربین تار','easy','[{"title": "تمیز بیرونی", "body": "میکروفایبر و الکل ملایم."}, {"title": "باز کردن و بازرسی", "body": "پشت باز؛ ماژول دوربین بازرسی و پیچ‌ها محکم."}, {"title": "تمیزکاری داخلی شیشه", "body": "غبار زیر شیشه با برس و مکش تمیز شود."}, {"title": "تعویض ماژول در صورت خرابی", "body": "اگر تاری ماند، ماژول نو (S5KHM2 سازگار) نصب."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','free',0,'public','published','شیائومی,ردمی نوت ۹ پرو,دوربین تار',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-25 18:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'دوربین ۱۰۸ مگاپیکسلی نوت ۹ پرو تار شده');

