SELECT @bk_author,@bk_cat,'ردمی ۹ سیم‌کارت را نمی‌شناسد','سینی، سیم‌کارت و ریست شبکه؛ در ۹۰٪ موارد مشکل از همین‌هاست.','سینی‌های ارزان بعد از تعویض سیم‌کارت گاهی کامل نمی‌نشینند.','ردمی ۹','شیائومی','متفرقه','','سیم‌کارت','easy','[{"title": "سیم‌کارت و سینی", "body": "سیم‌کارت سالم در گوشی دیگر تست؛ سینی اصل جا زده."}, {"title": "ریست شبکه", "body": "ریست تنظیمات Wi-Fi/موبایل/بلوتوث."}, {"title": "آپدیت MIUI", "body": "آپدیت رادیو نصب شود."}, {"title": "بررسی سوکت", "body": "در صورت ادامه، سوکت SIM روی برد بررسی شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','شیائومی,ردمی ۹,سیم‌کارت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-26 00:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ردمی ۹ سیم‌کارت را نمی‌شناسد');

