SELECT @bk_author,@bk_cat,'رمز و Mi Account ردمی نوت ۱۰ را فراموش کرده‌ام','Mi Account قفل سخت‌گیرانه‌تری از گوگل دارد؛ فقط با حساب خودتان از طریق سایت شیائومی رفع می‌شود.','Mi Account بعد از ریست، آدرس ایمیل و رمز می‌خواهد. اگر آن را ندانید، بازیابی حساب از account.xiaomi.com انجام شود؛ ابزارهای بایپس ناپایدار و ناامن‌اند.','ردمی نوت ۱۰','شیائومی','ردمی نوت 10','','فراموشی رمز + Mi Account','hard','[{"title": "بازیابی Mi Account", "body": "از account.xiaomi.com با شماره/ایمیل بازیابی کنید."}, {"title": "ریست از Recovery", "body": "Volume بالا + Power؛ Wipe Data."}, {"title": "ورود حساب بعد از ریست", "body": "با حساب بازیابی‌شده وارد شوید تا قفل برداشته شود."}, {"title": "نکتهٔ مهم", "body": "قبل از فروش/خرید دست دوم، حتماً Mi Account را حذف کنید؛ وگرنه گوشی آجر می‌شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','paid',35000,'public','published','شیائومی,ردمی نوت ۱۰,Mi Account,رمز',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-26 04:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'رمز و Mi Account ردمی نوت ۱۰ را فراموش کرده‌ام');

