SELECT @bk_author,@bk_cat,'فراموشی رمز ردمی نوت ۱۲ — از Find Device تا فلش','اگر Find Device فعال باشد از سایت شیائومی پاک می‌کنید؛ بدون آن، ریست Recovery یا فلش Fastboot.','گوشی‌های جدید شیائومی با Android 13 به بالا، ریست Recovery را هم محدود کرده‌اند؛ در آن صورت فلش با MiFlash راه باقی‌مانده است.','ردمی نوت ۱۲','شیائومی','ردمی نوت 12','','فراموشی رمز','medium','[{"title": "Find Device", "body": "از i.mi.com با حساب شیائومی، گزینهٔ Erase Device."}, {"title": "Recovery", "body": "اگر منوی Recovery در دسترس بود، Wipe Data."}, {"title": "فلش Fastboot", "body": "فریمور Fastboot رسمی + MiFlash؛ گوشی در حالت Fastboot وصل و فلش."}, {"title": "ورود حساب", "body": "بعد از فلش، حتماً با Mi Account و گوگل قبلی وارد شوید."}]','','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','free',0,'public','published','شیائومی,ردمی نوت ۱۲,رمز,فلش',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-26 07:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'فراموشی رمز ردمی نوت ۱۲ — از Find Device تا فلش');

