SELECT @bk_author,@bk_cat,'پوکو X6 حین بازی سنگین داغ می‌کند','Snapdragon 7 Gen 1 در بار سنگین گرم می‌شود؛ تنظیمات رندر و مدیریت گرما سرعت را حفظ می‌کند.','گرما → کاهش خودکار فریم‌ریت. با تنظیم Game Turbo و کاهش رزولوشن رندر، پایداری بهتری می‌گیرید.','پوکو X6','شیائومی','پوکو X6','','داغی بازی','easy','[{"title": "Game Turbo", "body": "حالت بازی را روشن و برنامهٔ پس‌زمینه را ببندید."}, {"title": "رزولوشن رندر", "body": "در بازی‌های سنگین، کیفیت متوسط + فریم بالاتر پایدارتر است."}, {"title": "بدون قاب و خنک", "body": "قاب ضخیم بردارید؛ شارژ حین بازی نکنید."}, {"title": "آپدیت MIUI/HyperOS", "body": "آپدیت‌های ترموسیپ سطوح دما را بهبود می‌دهند."}]','','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','like',0,'public','published','شیائومی,پوکو X6,داغی,بازی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-26 08:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'پوکو X6 حین بازی سنگین داغ می‌کند');

