SELECT @bk_author,@bk_cat,'ردمی ۱۲ کند شارژ می‌شود — چک‌لیست سریع','شارژ ۱۸-۳۳ وات فقط با آداپتور/کابل مناسب فعال می‌شود؛ پورت کثیف هم گلوگاه است.','خیلی از کاربران کابل موبایل را با آداپتور ضعیف ترکیب می‌کنند؛ جفت درست کابل/آداپتور سرعت را چند برابر می‌کند.','ردمی ۱۲','شیائومی','متفرقه','','شارژ آهسته','easy','[{"title": "آداپتور مناسب", "body": "آداپتور ۱۸ وات به بالا + کابل 3A اصل."}, {"title": "تمیزکاری پورت", "body": "خلال و برس نرم."}, {"title": "فعال بودن شارژ سریع", "body": "در برخی مدل‌ها تنظیم شارژ سریع وجود دارد؛ روشن باشد."}, {"title": "دما", "body": "در گرما شارژ کند می‌شود؛ محیط خنک."}]','','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','free',0,'public','published','شیائومی,ردمی ۱۲,شارژ آهسته',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-26 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ردمی ۱۲ کند شارژ می‌شود — چک‌لیست سریع');

