SELECT @bk_author,@bk_cat,'تعویض باتری هواوی P30 بعد از چند سال استفاده','پشت شیشه‌ای P30 با حرارت باز می‌شود؛ باتری HB486486ECW با نوارهای چسبی بیرون می‌آید.','P30 از سال ۲۰۱۹ در بازار است و باتری‌هایش به پایان عمر رسیده‌اند. تعویض باتری، عمر مفید این دوربین خوب را دوباره تمدید می‌کند.','هواوی P30','هواوی','P30','','باتری ضعیف','medium','[{"title": "باز کردن پشت شیشه‌ای", "body": "هیتر ~۸۰ درجه، ساکشن از پایین و پیک برای چسب."}, {"title": "قطع فلکس باتری", "body": "اولین اقدام بعد باز شدن."}, {"title": "خروج باتری", "body": "نوارهای چسب موازی کشیده؛ در صورت پارگی، الکل ایزوپروپیل."}, {"title": "نصب و تست", "body": "باتری نو، چسب آب‌بندی نو و تست شارژدهی یک روز."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg", "/uploads/tips/gen/heat-gun-backcover.jpg"]','','[]','free',0,'public','published','هواوی,P30,باتری',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-26 18:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض باتری هواوی P30 بعد از چند سال استفاده');

