SELECT @bk_author,@bk_cat,'دوربین P30 Pro تار عکس می‌گیرد (لنز لایکا)','سنسور پرریسک P30 Pro به غبار زیر شیشهٔ لنز حساس است؛ تمیزکاری داخلی اغلب کافی است.','دوربین P30 Pro معروف است ولی با گذر سال، غبار زیر شیشهٔ لنز جمع می‌شود و عکس‌ها مات می‌شوند.','هواوی P30 پرو','هواوی','P30','','دوربین تار','medium','[{"title": "تمیزکاری بیرونی", "body": "میکروفایبر؛ اول ساده‌ترین علت را رد کنید."}, {"title": "تست زوم", "body": "اگر فقط در زوم تار است، ماژول پریسکوپ مقصر است."}, {"title": "باز کردن و تمیزکاری داخلی", "body": "پشت باز، شیشهٔ داخلی لنز تمیز شود."}, {"title": "تعویض ماژول", "body": "در صورت آسیب ماژول، تعویض با قطعه اصل."}]','','["/uploads/tips/gen/cracked-camera-lens.jpg"]','','[]','like',0,'public','published','هواوی,P30 Pro,دوربین',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-26 20:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'دوربین P30 Pro تار عکس می‌گیرد (لنز لایکا)');

