SELECT @bk_author,@bk_cat,'SuperCharge ۲۲.۵ وات P40 کار نمی‌کند','شارژ سریع هواوی پروتکل اختصاصی دارد؛ فقط آداپتور اصل سرعت کامل می‌دهد.','SuperCharge هواوی روی PD هم کار می‌کند ولی با توان کمتر. اگر حتی با اصل هم کند است، پورت و فلکس پورت بررسی شود.','هواوی P40','هواوی','P40','','شارژ آهسته','easy','[{"title": "آداپتور اصل", "body": "آداپتور SuperCharge اصل هواوی + کابل 5A."}, {"title": "تمیزکاری پورت Type-C", "body": "خلال و برس."}, {"title": "بررسی پیام SuperCharge", "body": "هنگام وصل، پیام شارژ سریع باید بیاید؛ اگر نمی‌آید مذاکرهٔ پروتکل خراب است."}, {"title": "تعویض فلکس پورت", "body": "فلکس نو نصب و تست."}]','','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','free',0,'public','published','هواوی,P40,SuperCharge',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-26 23:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'SuperCharge ۲۲.۵ وات P40 کار نمی‌کند');

