SELECT @bk_author,@bk_cat,'نوا ۹ خودش خاموش می‌شود','خاموشی معمولاً از اپ‌های غیرسازگار (چون هواوی سرویس گوگل ندارد) یا باتری است.','روی گوشی‌های بدون GMS بعضی اپ‌های غیررسمی ناپایدار کار می‌کنند و سیستم را کرش می‌دهند. منبع نصب اپ‌ها را جدی بگیرید.','هواوی نوا ۹','هواوی','Nova 9','','خاموشی ناگهانی','medium','[{"title": "یادداشت الگو", "body": "خاموشی با کدام اپ/شرایط رخ می‌دهد؟"}, {"title": "حذف اپ‌های مشکوک", "body": "اپ‌های نصب‌شده از منابع غیررسمی را حذف کنید."}, {"title": "به‌روزرسانی EMUI", "body": "آپدیت‌های سیستم نصب شود."}, {"title": "تعویض باتری", "body": "اگر با باتری سالم ادامه داشت، برد بازرسی شود."}]','','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','free',0,'public','published','هواوی,Nova 9,خاموشی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-27 03:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'نوا ۹ خودش خاموش می‌شود');

