SELECT @bk_author,@bk_cat,'تعویض نمایشگر منحنی Mate 40','پنل خمیده (Curved) ریسک شکستن هنگام جداسازی دارد؛ با حرارت کافی و صبوری کار کنید.','نمایشگرهای منحنی با چسب بیشتری نصب شده‌اند و پیک ممکن است گوشه‌ها را بشکند. ابزار کارت پلاستیکی نازک و حرارت یکنواخت لازم است.','هواوی میت ۴۰','هواوی','Mate 40','','شکستن نمایشگر','hard','[{"title": "گرم یکنواخت", "body": "کل محیط پنل گرم شود؛ تمرکز حرارت روی یک نقطه ممنوع."}, {"title": "جداسازی با کارت", "body": "کارت نازک زیر لبه‌ها؛ پیک فلزی استفاده نکنید."}, {"title": "انتقال قطعات", "body": "بلندگو، سنسور و دوربین جلو به پنل نو منتقل شوند."}, {"title": "تست و آب‌بندی", "body": "تست کامل نمایشگر + واشر نو."}]','','["/uploads/tips/gen/cracked-display.jpg", "/uploads/tips/gen/heat-gun-backcover.jpg"]','','[]','paid',25000,'public','published','هواوی,Mate 40,نمایشگر منحنی',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-27 05:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض نمایشگر منحنی Mate 40');

