SELECT @bk_author,@bk_cat,'تعویض باتری آنر X7','پشت پلاستیکی X7 باز کردن ساده‌ای دارد؛ تعویض باتری آن پروژهٔ خوبی برای تازه‌کارهاست.','آنر سری X اقتصادی است و قطعاتش ارزان. پشت پلاستیکی با پیک و حرارت ملایم باز می‌شود.','آنر X7','آنر','X7','','باتری ضعیف','easy','[{"title": "باز کردن پشت", "body": "از گوشهٔ پایین با پیک."}, {"title": "قطع فلکس", "body": "فلکس باتری جدا شود."}, {"title": "خروج باتری", "body": "نوارهای چسب کشیده یا الکل."}, {"title": "نصب و تست", "body": "باتری نو نصب و تست یک روزه."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','free',0,'public','published','آنر,X7,باتری',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-27 12:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعویض باتری آنر X7');

