SELECT @bk_author,@bk_cat,'آنر ۹۰ هنگام عکاسی و بازی داغ می‌کند','سنسور ۲۰۰ مگاپیکسلی پردازش سنگینی دارد؛ تنظیمات دوربین و مدیریت بازی دما را پایین می‌آورد.','عکاسی با رزولوشن کامل و پردازش HDR طولانی، تراشه را زیر فشار می‌گذارد. تنظیمات هوشمندانه گرما را کم می‌کند.','آنر ۹۰','آنر','Honor 90','','داغ شدن','easy','[{"title": "عکاسی ۱۲ مگاپیکسلی پیش‌فرض", "body": "رزولوشن ۲۰۰MP فقط برای صحنه‌های نور خوب و بدون حرکت."}, {"title": "بدون قاب در بازی", "body": "قاب ضخیم برداشته و شارژ حین بازی ممنوع."}, {"title": "MagicOS به‌روز", "body": "آپدیت‌های دمایی نصب شود."}, {"title": "بررسی باتری", "body": "باتری فرسوده هم گرمای اضافه می‌دهد."}]','','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','free',0,'public','published','آنر,Honor 90,داغی',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-27 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آنر ۹۰ هنگام عکاسی و بازی داغ می‌کند');

