SELECT @bk_author,@bk_cat,'رمز گوشی هواوی را فراموش کرده‌ام — Find My Phone و Recovery','با Find My Phone هواوی از راه دور پاک کنید یا از Recovery ریست کنید؛ حساب هواوی لازم است.','قفل فعال‌سازی هواوی مثل گوگل سخت‌گیرانه است. قبل از هر اقدامی مطمئن شوید ایمیل/رمز حساب هواوی خود را می‌دانید.','گوشی‌های هواوی','هواوی','متفرقه','','فراموشی رمز','medium','[{"title": "Find My Phone", "body": "از cloud.huawei.com وارد شوید و Erase Device بزنید."}, {"title": "Recovery", "body": "خاموش؛ Volume بالا + Power؛ Wipe data/factory reset."}, {"title": "ورود حساب", "body": "بعد از ریست با حساب هواوی/گوگل قبلی وارد شوید."}, {"title": "اگر حساب را نمی‌دانید", "body": "بازیابی حساب از سایت هواوی؛ از ابزارهای بایپس پرهیز کنید."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','هواوی,رمز,Find My Phone',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-27 19:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'رمز گوشی هواوی را فراموش کرده‌ام — Find My Phone و Recovery');

