SELECT @bk_author,@bk_cat,'هواوی P30 آب خورده — مسیر نجات','P30 در برابر پاشش مقاوم است ولی غوطه‌وری نه؛ خاموشی سریع و باز شدن حرفه‌ای کلید نجات است.','سنسور رطوبت و خوردگی بلافاصله شروع می‌شود. هر ساعت تأخیر در باز شدن، شانس نجات را کم می‌کند.','هواوی P30','هواوی','P30','','آب‌خوردگی','hard','[{"title": "خاموش فوری و بی‌شارژ", "body": "تا باز شدن حرفه‌ای، شارژ و روشن کردن ممنوع."}, {"title": "خشک اولیه", "body": "پارچه، تکان ملایم، هوای فن."}, {"title": "تخلیه و شست‌وشو", "body": "برد در اولتراسونیک با ایزوپروپیل؛ سوکت‌ها تمیز و خشک."}, {"title": "بازرسی و تست کشیده", "body": "خوردگی‌ها بازلحیم و تست چندروزه؛ اکسیدیشن تأخیری رایج است."}]','','["/uploads/tips/gen/phone-in-rice.jpg", "/uploads/tips/gen/wet-usb-port.jpg"]','','[]','like',0,'public','published','هواوی,P30,آب‌خوردگی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-27 20:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'هواوی P30 آب خورده — مسیر نجات');

