SELECT @bk_author,@bk_cat,'چطور بفهمیم مشکل از گوشی است یا شارژر و کابل؟ (روش مهندسی حذف)','با جدول سادهٔ تعویض متقاطع در ۱۰ دقیقه مقصر را پیدا کنید؛ پرتکرارترین روش تعمیرگاه‌های حرفه‌ای.','بیشتر مراجعه‌های «شارژ نمی‌شود» اصلاً مشکل سخت‌افزاری نیستند. با حذف متقاطع (Cross-test) بدون هزینه مقصر را پیدا می‌کنید.','همهٔ گوشی‌ها','عمومی','','','تشخیص شارژر و کابل','easy','[{"title": "کابل را عوض کنید", "body": "سالم‌ترین کابل موجود را بزنید؛ اگر درست شد کابل مقصر بود."}, {"title": "آداپتور را عوض کنید", "body": "با آداپتور دیگری از یک دستگاه سالم تست."}, {"title": "پورت گوشی را با دستگاه دیگر تست کنید", "body": "کابل را به گوشی دیگری بزنید؛ اگر آن هم شارژ نشد، کابل/آداپتور مقصر است."}, {"title": "پورت را تمیز کنید", "body": "اگر همهٔ تست‌ها مشکل را به گوشی رساندند، پورت کثیف یا فلکس معیوب است."}]','دو کابل، دو آداپتور، خلال چوبی، برس نرم','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','free',0,'public','published','عمومی,شارژر,کابل,عیب‌یابی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-29 07:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'چطور بفهمیم مشکل از گوشی است یا شارژر و کابل؟ (روش مهندسی حذف)');

