SELECT @bk_author,@bk_cat,'تمیزکاری امن پورت Type-C بدون آسیب به پین‌ها','پرز فشردهٔ جیب، رایج‌ترین علت شارژ نشدن است؛ با خلال و نور قوی بی‌خطر تمیز کنید.','هرگز با فلز داخل پورت نروید؛ پین‌های Type-C ظریف‌اند و خم شدنشان یعنی تعویض پورت. خلال چوبی و برس نرم کاملاً کافی است.','گوشی‌های Type-C','عمومی','','','پورت کثیف','easy','[{"title": "نور بتابانید", "body": "با چراغ قوی داخل پورت را ببینید؛ پرز معمولاً کف پورت فشرده شده."}, {"title": "خلال خشک", "body": "آرام از کف پورت پرز را بیرون بکشید؛ فشار به بالا (پین‌ها) ندهید."}, {"title": "برس نرم یا مکش ملایم", "body": "ذرات باقی‌مانده را بردارید."}, {"title": "تست", "body": "کابل را باید کامل و با کلیک جا برود؛ اگر شل است، پورت استهلاک خورده و تعویض لازم است."}]','خلال چوبی، برس ضداستاتیک، چراغ قوی','["/uploads/tips/gen/wet-usb-port.jpg"]','','[]','like',0,'public','published','عمومی,پورت Type-C,تمیزکاری',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-29 09:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تمیزکاری امن پورت Type-C بدون آسیب به پین‌ها');

