SELECT @bk_author,@bk_cat,'ریست کارخانهٔ امن — قبل از فروش یا حل مشکلات نرم‌افزاری','بکاپ کامل، خروج از حساب‌ها و بعد ریست؛ بدون این ترتیب داده یا گوشی قفل می‌شود.','ریست کارخانه بدون خروج از حساب‌ها، FRP (قفل فعال‌سازی گوگل) را فعال نگه می‌دارد و گوشی بعد از ریست با حساب قبلی قفل می‌شود.','گوشی‌های اندروید','عمومی','','','ریست کارخانه','medium','[{"title": "بکاپ کامل", "body": "عکس‌ها با گوگل‌فوتو، فایل‌ها با کابل به کامپیوتر، چت‌ها با بکاپ خودشان."}, {"title": "خروج از حساب‌ها", "body": "گوگل، سامسونگ/شیائومی/هواوی و هر حساب اپ از تنظیمات خارج شود."}, {"title": "رمز قفل صفحه را حذف کنید", "body": "قبل از ریست، رمز را بردارید."}, {"title": "ریست و تست", "body": "بعد از ریست، گوشی باید بدون درخواست حساب قبلی بالا بیاید."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','paid',55000,'public','published','عمومی,ریست کارخانه,FRP,بکاپ',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-29 12:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'ریست کارخانهٔ امن — قبل از فروش یا حل مشکلات نرم‌افزاری');

