SELECT @bk_author,@bk_cat,'چطور سلامت باتری هر گوشی را بسنجیم؟ (بدون تعویض قطعه)','الگوی افت درصد، گرمای شارژ و عمر گوشی سه شاخص سادهٔ فرسودگی باتری هستند.','اندروید مثل آیفون عدد سلامت نمی‌دهد ولی با رفتار باتری می‌توان وضعیت را تخمین زد: افت پرشی، خاموشی زیر ۱۵٪ و داغی شارژ نشانه‌های اصلی‌اند.','همهٔ گوشی‌ها','عمومی','','','سلامت باتری','easy','[{"title": "تست پرش درصد", "body": "از ۵۰٪ شروع کنید؛ اگر در کمتر از ۳۰ دقیقه مصرف معمولی به ۲۰٪ رسید، باتری فرسوده است."}, {"title": "تست دما", "body": "شارژ عادی نباید گوشی را داغ کند؛ داغی یعنی مقاومت داخلی بالا."}, {"title": "اپ‌های تشخیصی", "body": "برخی اپ‌ها (مثل AccuBattery) ظرفیت واقعی را با چند چرخه تخمین می‌زنند."}, {"title": "تصمیم تعویض", "body": "زیر ۷۵-۸۰٪ ظرفیت واقعی = تعویض اقتصادی است."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','free',0,'public','published','عمومی,باتری,سلامت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-29 14:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'چطور سلامت باتری هر گوشی را بسنجیم؟ (بدون تعویض قطعه)');

