SELECT @bk_author,@bk_cat,'قواعد طلایی جدا کردن باتری چسبیده — بدون آتش‌سوزی','کشش موازی، الکل، کارت پلاستیکی؛ هرگز خم، سوراخ یا با فلز.','باتری لیتیومی در برابر خمش و سوراخ شدن واکنش حرارتی (Thermal Runaway) می‌دهد. این قواعد برای همهٔ گوشی‌ها یکسان است.','همهٔ گوشی‌ها','عمومی','','','جدا کردن باتری','hard','[{"title": "شارژ زیر ۲۵٪", "body": "قبل از باز کردن، باتری را کم‌شارژ کنید؛ باتری پر در صورت حادثه شدیدتر می‌سوزد."}, {"title": "نوارها موازی بکشید", "body": "آرام، پیوسته و موازی سطح؛ اگر پاره شد الکل بریزید."}, {"title": "کارت پلاستیکی", "body": "باتری را بلند کنید نه خم؛ هیچ‌وقت با پیچ‌گوشتی زیرش نروید."}, {"title": "دفع امن", "body": "باتری جدا شده در ظرف فلزی/شنی و تحویل به دفع‌کنندهٔ مجاز."}]','الکل ایزوپروپیل ۹۹٪، کارت پلاستیکی، پنس پلاستیکی، ظرف فلزی','["/uploads/tips/gen/disconnect-battery-flex.jpg", "/uploads/tips/gen/swollen-battery.jpg"]','','[]','free',0,'public','published','عمومی,باتری,ایمنی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-29 18:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'قواعد طلایی جدا کردن باتری چسبیده — بدون آتش‌سوزی');

