SELECT @bk_author,@bk_cat,'باز کردن درب پشت شیشه‌ای بدون شکستن — تکنیک حرارت و ساکشن','حرارت یکنواخت ~۸۰ درجه، ساکشن از پایین و پیشروی پیک به‌صورت تدریجی.','شیشه‌های پشت با چسب دوطرفهٔ قوی نصب شده‌اند. عجله و حرارت ناکافی دو عامل اصلی شکستن هستند.','گوشی‌های قاب چسبی','عمومی','','','باز کردن درب','medium','[{"title": "گرم کردن یکنواخت", "body": "هیتر یا سشوار صنعتی؛ سطح را با دست چک کنید: داغ ولی قابل لمس."}, {"title": "ساکشن و فشار هوا", "body": "ساکشن را نزدیک لبه بگذارید و بکشید تا لبه باز شود؛ پیک را جا بزنید."}, {"title": "پیشروی تدریجی", "body": "پیک را آرام به سمت گوشه‌ها هدایت کنید؛ پیک‌های فلزی ممنوع."}, {"title": "باز کردن کامل", "body": "در گوشی‌هایی که فلکس دوربین روی درب است، درب را آرام باز کنید و فلکس‌ها را جدا نمایید."}]','هیتر/سشوار صنعتی، ساکشن، پیک‌های پلاستیکی، کارت نازک','["/uploads/tips/gen/heat-gun-backcover.jpg"]','','[]','like',0,'public','published','عمومی,درب پشت,حرارت',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-29 20:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'باز کردن درب پشت شیشه‌ای بدون شکستن — تکنیک حرارت و ساکشن');

