SELECT @bk_author,@bk_cat,'سازماندهی پیچ‌ها و قطعات هنگام تعمیر — روش مات مغناطیسی','بیشترین خطای تعمیرکاران تازه‌کار، جابجایی یا جاانداختن پیچ است؛ با نقشهٔ ساده این خطا صفر می‌شود.','پیچ‌های گوشی به طول‌های مختلف‌اند؛ پیچ بلند در جای کوتاه، برد را سوراخ می‌کند. یک نقشهٔ کاغذی یا مات مغناطیسی خطا را از بین می‌برد.','تعمیرگاه','عمومی','','','پیچ‌های گم‌شده','medium','[{"title": "کشیدن نقشه", "body": "روی کاغذ، جای هر پیچ را با اندازه مشخص کنید و پیچ روی همان خانه بچسبد."}, {"title": "مات مغناطیسی", "body": "مات‌های مغناطیسی با سلول‌های برچسب‌دار پیچ‌ها را نگه می‌دارند."}, {"title": "قانون طول", "body": "هرگز پیچ بلندتر را به‌زور در جای کوتاه نگذارید."}, {"title": "شمارش قبل از بستن", "body": "قبل از بستن نهایی، تعداد پیچ‌های بازشده با نقشه چک شود."}]','مات مغناطیسی، کاغذ، چسب کاغذی، برچسب','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','عمومی,تعمیرگاه,پیچ,ابزار',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-30 00:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'سازماندهی پیچ‌ها و قطعات هنگام تعمیر — روش مات مغناطیسی');

