SELECT @bk_author,@bk_cat,'الکل ایزوپروپیل ۹۹٪ — کاربردهای طلایی در تعمیر موبایل','تمیزکاری سوکت، آزاد کردن چسب باتری، شست‌وشوی برد؛ هر تعمیرکاری باید بداند کدام غلظت برای کدام کار.','ایزوپروپیل ۹۹٪ سریع تبخیر می‌شود و رسوب نمی‌گذارد؛ الکل‌های معطر و دستی (۷۰٪) آب دارند و برای برد مناسب نیستند.','تعمیرگاه','عمومی','','','الکل ایزوپروپیل','easy','[{"title": "تمیزکاری سوکت‌ها", "body": "چند قطره + برس ضداستاتیک؛ اکسیدیشن سوکت‌ها را می‌برد."}, {"title": "آزادسازی چسب باتری", "body": "زیر باتری چند قطره، ۳۰ ثانیه صبر، بلند کردن با کارت."}, {"title": "شست‌وشوی برد آب‌خورده", "body": "به‌تنهایی یا در اولتراسونیک؛ بعد خشک‌کاری کامل."}, {"title": "پرهیزها", "body": "روی OLED روشن نریزید؛ در محیط با تهویه کار کنید."}]','','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','free',0,'public','published','عمومی,الکل,ایزوپروپیل,تعمیرگاه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-30 02:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'الکل ایزوپروپیل ۹۹٪ — کاربردهای طلایی در تعمیر موبایل');

