SELECT @bk_author,@bk_cat,'تست دقیق مدار شارژ با مولتی‌متر و جعبهٔ تست','با مولتی‌متر ولتاژ شارژر و شروع شارژ گوشی را بسننجید تا فلکس، سوکت یا IC شارژ را تفکیک کنید.','قبل از تعویض IC شارژ (که تخصص می‌خواهد)، سه سطح تست وجود دارد: خروجی آداپتور، جریان روی کابل و رفتار گوشی.','تعمیرگاه','عمومی','','','تست شارژ','medium','[{"title": "تست آداپتور", "body": "خروجی آداپتور سیمی باید ۵ ولت (یا ولتاژ PD مذاکره‌شده) باشد."}, {"title": "تست کابل", "body": "مقاومت هر رشتهٔ کابل چک شود؛ رشتهٔ شکستهٔ داخلی رایج است."}, {"title": "اندازه‌گیری جریان", "body": "با جعبهٔ تست USB (USB meter) جریان شارژ گوشی را ببینید: زیر ۰.۳ آمپر = مشکل گوشی/پورت."}, {"title": "تفکیک فلکس و IC", "body": "با تعویض فلکس پورت، فلکس از IC شارژ جدا می‌شود."}]','مولتی‌متر، جعبهٔ تست USB، آداپتور مرجع','["/uploads/tips/gen/charger-and-cable.jpg", "/uploads/tips/gen/esd-workspace.jpg"]','','[]','free',0,'public','published','عمومی,مولتی‌متر,شارژ,تعمیرگاه',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-30 07:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تست دقیق مدار شارژ با مولتی‌متر و جعبهٔ تست');

