SELECT @bk_author,@bk_cat,'کار امن با هیتر — دما، فاصله و مدت برای هر نوع بدنه','شیشه ~۸۰ درجه، پلاستیک ~۶۰-۷۰؛ حرارت یکنواخت و حرکت دائم هیتر.','هیتر بی‌حرکت روی یک نقطه، OLED یا باتری را می‌سوزاند. حرکت دائمی و تنظیم دما دو اصل کلیدی‌اند.','تعمیرگاه','عمومی','','','کار با هیتر','medium','[{"title": "دمای درست", "body": "شیشه: ۷۵-۹۰ درجه؛ پلاستیک: ۵۵-۷۰ درجه؛ هرگز بالای ۱۰۰ روی نمایشگر روشن."}, {"title": "حرکت دائم", "body": "هیتر را روی سطح حرکت دهید؛ هر نقطه بیش از چند ثانیه نماند."}, {"title": "تست لمسی", "body": "سطح باید داغ ولی قابل لمس باشد (~۶۵ درجه محسوس)."}, {"title": "سریع بودن کار", "body": "بعد از گرم شدن، کار جداسازی را سریع ادامه دهید؛ سرد شدن مجدد یعنی چسب سفت شدن."}]','هیتر دیجیتال، ساکشن، پیک پلاستیکی','["/uploads/tips/gen/heat-gun-backcover.jpg"]','','[]','like',0,'public','published','عمومی,هیتر,تعمیرگاه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-30 08:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'کار امن با هیتر — دما، فاصله و مدت برای هر نوع بدنه');

