SELECT @bk_author,@bk_cat,'برنج، جوش شیرین یا هوای فن؟ واقعیت خشک کردن گوشی','برنج کند و کم‌اثر است؛ هوای فن و گرمای ملایم مؤثرترند و باز شدن حرفه‌ای قطعی.','آزمایش‌های مستقل نشان داده‌اند برنج در ۴۸ ساعت فقط بخشی از رطوبت را می‌گیرد. مهم‌تر از خشک کردن سطحی، جلوگیری از خوردگی با باز شدن زودهنگام است.','همهٔ گوشی‌ها','عمومی','','','آب‌خوردگی','medium','[{"title": "خاموشی فوری", "body": "مهم‌ترین قدم؛ جریان روی مدار خیس = خوردگی سریع."}, {"title": "تکان و پاک‌سازی سطحی", "body": "پورت رو به پایین تکان دهید؛ با پارچه خشک کنید."}, {"title": "هوای فن", "body": "جلوی فن یا هوای خنک؛ سشوار داغ و فشار هوا (رطوبت را می‌برد داخل) ممنوع."}, {"title": "تعمیر حرفه‌ای در ۲۴ ساعت", "body": "باز شدن، شست‌وشوی اولتراسونیک و بازرسی، از خوردگی پیشروی‌کننده جلوگیری می‌کند."}]','','["/uploads/tips/gen/phone-in-rice.jpg", "/uploads/tips/gen/wet-usb-port.jpg"]','','[]','free',0,'public','published','عمومی,آب‌خوردگی,برنج',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-30 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'برنج، جوش شیرین یا هوای فن؟ واقعیت خشک کردن گوشی');

