SELECT @bk_author,@bk_cat,'آب‌بندی مجدد بعد از تعمیر — واشر، چسب و تست IP','بعد از هر باز شدن، واشر ضدآب نو و چسب مخصوص لازم است؛ تست IP کارخانه قابل بازتولید کامل نیست.','گوشی‌های ضدآب با ربات و فشار کنترل‌شده مهر می‌شوند. تعمیرگاه با واشر نو و چسب مناسب، مقاومت خوبی بازیابی می‌کند ولی وعدهٔ IP اصلی نداریم.','همهٔ گوشی‌ها','عمومی','','','آب‌بندی','medium','[{"title": "واشر نو", "body": "واشر دور نمایشگر/درب حتماً نو باشد؛ واشر کهنه آب‌بندی نمی‌شود."}, {"title": "چسب مناسب", "body": "چسب‌های آب‌بندی مخصوص (نه چسب دوطرفهٔ معمولی)."}, {"title": "مونتاژ تمیز", "body": "لبه‌ها بدون غبار و اثر انگشت؛ غبار روی مسیر واشر نشتی می‌سازد."}, {"title": "انتظار واقع‌بینانه", "body": "به مشتری بگویید مقاومت پاشش برمی‌گردد نه IP کامل کارخانه."}]','واشر آب‌بندی، چسب مخصوص، گیره‌های مونتاژ','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','paid',45000,'public','published','عمومی,آب‌بندی,واشر',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-30 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آب‌بندی مجدد بعد از تعمیر — واشر، چسب و تست IP');

