SELECT @bk_author,@bk_cat,'تست کامل تاچ و نمایشگر قبل از تحویل به مشتری','با اپ‌های تست لمس و مسیرهای دستی، تمام صفحه را پوشش دهید؛ تاچ ناقص شایع‌ترین مرجوعی تعمیر است.','پنل‌های تعویضی گاهی فقط در نواحی مرزی یا با فشار مشکل دارند. تست ۲-۳ دقیقه‌ای، مرجوعی را از بین می‌برد.','همهٔ گوشی‌ها','عمومی','','','تاچ تست','easy','[{"title": "اپ تست لمس", "body": "اپ‌های Touch Screen Test مسیر انگشت را رسم می‌کنند؛ کل صفحه را پوشش دهید."}, {"title": "تست چندانگشتی", "body": "Multi-touch را با دو انگشت همزمان چک کنید."}, {"title": "تست روشنایی خودکار و True Tone/رنگ", "body": "سنسورها بعد از تعویض پنل چک شوند."}, {"title": "تست در حالت شارژ", "body": "تاچ ناپایدار حین شارژ یعنی نویز پنل/شارژر."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','عمومی,تست,تاچ,تعمیرگاه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-30 17:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تست کامل تاچ و نمایشگر قبل از تحویل به مشتری');

