SELECT @bk_author,@bk_cat,'عادت‌هایی که عمر باتری را دو برابر می‌کنند','گرما، تخلیهٔ کامل مکرر و شارژرهای بی‌کیفیت سه دشمن اصلی باتری هستند.','باتری لیتیومی بر اساس چرخه‌ها (Cycle) فرسوده می‌شود؛ با کاهش استرس حرارتی و بازهٔ شارژ معقول، عمر مفید از ~۵۰۰ به ~۹۰۰ چرخه می‌رسد.','همهٔ گوشی‌ها','عمومی','','','نگهداری باتری','easy','[{"title": "از گرمای شدید بپرهیزید", "body": "تابش مستقیم آفتاب و داشبورد ماشین ممنوع."}, {"title": "تخلیهٔ مکرر تا صفر نشود", "body": "۲۰٪ حد پایین معقول است."}, {"title": "شارژر استاندارد", "body": "آداپتورهای معتبر با پروتکل رسمی گوشی."}, {"title": "شارژ ذخیره‌ای طولانی‌مدت", "body": "برای گوشیِ انبارشده ~۵۰٪ شارژ و خاموش."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg", "/uploads/tips/gen/charger-and-cable.jpg"]','','[]','free',0,'public','published','عمومی,باتری,نگهداری',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-31 00:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'عادت‌هایی که عمر باتری را دو برابر می‌کنند');

