SELECT @bk_author,@bk_cat,'چک‌لیست ۱۲ نقطه‌ای تست قبل از تحویل گوشی به مشتری','تماس، وای‌فای، بلوتوث، دوربین‌ها، میکروفون‌ها، سنسورها، شارژ و تاچ؛ ۵ دقیقه تست، اعتبار تعمیرگاه.','بخش بزرگی از اعتبار یک تعمیرگاه در «تحویل بی‌مرجوعی» است. چک‌لیست ثابت، خطای انسانی را از بین می‌برد.','تعمیرگاه','عمومی','','','چک‌لیست تحویل','easy','[{"title": "تماس و صدا", "body": "تماس واقعی: میکروفون، بلندگو، اسپیکرفون."}, {"title": "شبکه‌ها", "body": "وای‌فای، بلوتوث، سیم‌کارت‌ها، GPS."}, {"title": "دوربین و فلش", "body": "همهٔ لنزها + ویدیو + فلش."}, {"title": "سنسورها و ورودی‌ها", "body": "تاچ کامل، اثر انگشت/چهره، قطب‌نما، شتاب‌سنج، شارژ سیمی."}]','','["/uploads/tips/gen/esd-workspace.jpg", "/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','عمومی,تعمیرگاه,چک‌لیست',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-31 02:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'چک‌لیست ۱۲ نقطه‌ای تست قبل از تحویل گوشی به مشتری');

