SELECT @bk_author,@bk_cat,'قطعهٔ اصل، Service Pack یا کپی؟ راهنمای خرید قطعات','Service Pack = اصل تعمیراتی؛ گرید A = کیفیتی معقول؛ کپی ارزان = ریسک تاچ، رنگ و اثر انگشت.','در بازار ایران سه گریف اصلی وجود دارد. برای گوشی پرچمدار، پنل و باتری باکیفیت؛ برای گوشی‌های اقتصادی، گرید A انتخاب منطقی است.','همهٔ گوشی‌ها','عمومی','','','انتخاب قطعه','medium','[{"title": "Service Pack", "body": "بسته‌بندی تعمیراتی سازنده؛ بهترین کیفیت، گران‌ترین."}, {"title": "گرید A/OEM", "body": "کیفیت نزدیک به اصل با قیمت کمتر؛ برای اکثر کاربردها کافی."}, {"title": "کپی بی‌نام", "body": "فقط برای گوشی با ارزش کم؛ ریسک گوست تاچ، رنگ بی‌کیفیت و عمر کوتاه."}, {"title": "تست فوری نصب", "body": "قبل از تحویل، هر قطعه جدید تست شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','عمومی,قطعات,گرید',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-31 06:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'قطعهٔ اصل، Service Pack یا کپی؟ راهنمای خرید قطعات');

