SELECT @bk_author,@bk_cat,'قبل از تحویل گوشی به تعمیرگاه: بکاپ و امنیت','بکاپ کامل + خروج از حساب‌ها + رمز حذف/اعلام؛ چند دقیقه، خیال راحت.','تعمیر یعنی باز شدن گوشی؛ حوادث غیرمنتظره (در تعمیرات برد) ممکن است داده را پاک کند. حق شماست که قبل از تعمیر بکاپ بگیرید.','همهٔ گوشی‌ها','عمومی','','','بکاپ قبل تعمیر','easy','[{"title": "بکاپ ابری و محلی", "body": "عکس‌ها، مخاطبین، چت‌ها (بکاپ محلی واتساپ) و فایل‌ها."}, {"title": "خروج حساب‌ها", "body": "اگر تعمیر شامل ریست است، حساب‌ها از تنظیمات خارج شوند."}, {"title": "اطلاع به تعمیرکار", "body": "کارت حافظه/سیم‌کارت را اگر لازم نیست بیرون بدهید."}, {"title": "رمز را اعلام کنید", "body": "تعمیرکار برای تست بعد از تعمیر به رمز نیاز دارد؛ بعد از تحویل رمز را عوض کنید."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','like',0,'public','published','عمومی,بکاپ,امنیت',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-31 10:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'قبل از تحویل گوشی به تعمیرگاه: بکاپ و امنیت');

