SELECT @bk_author,@bk_cat,'چرا میز کار ضداستاتیک (ESD) جدی است؟','برق استاتیک نامرئی، تراشه‌ها را بی‌صدا می‌کُشد؛ مات، مچ‌بند و زمین واقعی سه ضامن امنیت‌اند.','استاتیک بدن انسان تا هزاران ولت می‌رسد و ICهای ظریف را بدون علامت می‌سوزاند. هزینهٔ ست ESD در برابر یک برد سوخته، هیچ است.','تعمیرگاه','عمومی','','','میز کار ESD','easy','[{"title": "مات ضداستاتیک", "body": "کل میز کار پوشیده و به زمین متصل."}, {"title": "مچ‌بند آنتی‌استاتیک", "body": "هنگام کار با برد حتماً بسته و زمین‌شده."}, {"title": "نگهداری قطعات در کیسهٔ آنتی‌استاتیک", "body": "نه روی میز معمولی و پلاستیک خشکی."}, {"title": "پرهیز از لباس پشمی و محیط خشک", "body": "رطوبت نسبی ۴۰-۶۰٪ تولید استاتیک را کم می‌کند."}]','مات ESD، مچ‌بند، کیسهٔ آنتی‌استاتیک','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','free',0,'public','published','عمومی,ESD,تعمیرگاه,ایمنی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-31 12:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'چرا میز کار ضداستاتیک (ESD) جدی است؟');

