SELECT @bk_author,@bk_cat,'پاوربانک مناسب برای موبایل — چه چیزی بخریم که باتری نسوزاند؟','پروتکل سازگار (PD/QC)، ظرفیت واقعی و مدار حفاظتی؛ پاوربانک بی‌کیفیت هم باتری را می‌فرساید هم خطرآفرین است.','پاوربانک‌های بی‌کیفیت ولتاژ ناپایدار می‌دهند؛ فرسایش باتری و داغی سریع‌تر اتفاق می‌افتد. ظرفیت ۱۰-۲۰ هزار میلی‌آمپر برای مصرف عادی کافی است.','همهٔ گوشی‌ها','عمومی','','','پاوربانک','easy','[{"title": "پروتکل رسمی", "body": "برای آیفون PD؛ برای سامسونگ PD/PPS؛ برای شیائومی سازگار ۳۳ وات."}, {"title": "ظرفیت واقعی", "body": "برندهای معتبر؛ ظرفیت اعلامی ۱۰ هزار یعنی شارژ کامل حدود دو بار."}, {"title": "حفاظت‌ها", "body": "حفاظت اتصال کوتاه، دما و اضافه‌جریان داشته باشد."}, {"title": "نگهداری", "body": "پاوربانک را هم داخل ماشین داغ نگذارید."}]','','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','free',0,'public','published','عمومی,پاوربانک,شارژ',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-31 15:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'پاوربانک مناسب برای موبایل — چه چیزی بخریم که باتری نسوزاند؟');

