SELECT @bk_author,@bk_cat,'در سرما صفحهٔ گوشی به لمس جواب نمی‌دهد — علت و راه‌حل','سرد شدن پنل، پاسخ‌گویی سنسور خازنی را کند می‌کند؛ طبیعی است ولی با ترفندهای ساده کم می‌شود.','سنسورهای خازنی در دمای پایین حساسیتشان کم می‌شود؛ همچنین انگشت سرد رسانایی کمتری دارد. هر دو عامل با هم تاچ را کُند می‌کنند.','همهٔ گوشی‌ها','عمومی','','','تاچ در سرما','easy','[{"title": "انگشت را گرم کنید", "body": "قبل از لمس، انگشت را کمی گرم و خشک کنید."}, {"title": "دستکش تاچ‌اسکرین", "body": "دستکش‌های مخصوص صفحه‌لمسی الیاف رسانا دارند."}, {"title": "گوشی در جیب درونی", "body": "نزدیک بدن بماند تا پنل سرد نشود."}, {"title": "اگر دائم است", "body": "در دمای اتاق هم تاچ کند است؟ پس پنل/محافظ بررسی شود."}]','','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','paid',35000,'public','published','عمومی,سرما,تاچ',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-31 19:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'در سرما صفحهٔ گوشی به لمس جواب نمی‌دهد — علت و راه‌حل');

