SELECT @bk_author,@bk_cat,'لکه‌های سبز/بنفش بعد از فشار یا ضربه روی AMOLED','لکه‌های رنگی فزاینده یعنی پنل ترک داخلی خورده و تدریجی بزرگ می‌شود؛ تعویض پنل تنها راه است.','ضربه روی OLED می‌تواند لایهٔ ارگانیک را بشکند؛ لکه از نقطهٔ ضربه رشد می‌کند و در نهایت کل صفحه را می‌گیرد.','همهٔ گوشی‌ها','عمومی','','','لکه فشار صفحه','medium','[{"title": "مستندسازی", "body": "عکس از لکه بگیرید و هر روز اندازه‌اش را چک کنید."}, {"title": "فشار ندهید", "body": "چسب زدن یا فشار دادن لکه را سریع‌تر پخش می‌کند."}, {"title": "برنامه‌ریزی تعویض", "body": "زمان خرید پنل را بر اساس سرعت رشد لکه تعیین کنید."}, {"title": "تعویض پنل", "body": "پنل باکیفیت نصب؛ در گوشی قدیمی، مقایسهٔ اقتصادی با ارزش گوشی."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','like',0,'public','published','عمومی,AMOLED,لکه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-08-31 21:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'لکه‌های سبز/بنفش بعد از فشار یا ضربه روی AMOLED');

