SELECT @bk_author,@bk_cat,'چسب B-7000 و مونتاژ تمیز — چطور بدون لکه و لبهٔ باز ببندیم','چسب پلیمری B-7000 برای لبه‌ها و درپوش‌ها؛ مقدار کم، فشار یکنواخت و پاک‌سازی سریع اضافه‌ها.','چسب داغ (هیتر) برای باتری و قطعات حساس ممنوع است؛ B-7000 چسب ارجح مونتاژ است چون انعطاف‌پذیر و قابل جداسازی است.','تعمیرگاه','عمومی','','','چسب B-7000','medium','[{"title": "مقدار کنترل‌شده", "body": "نوار نازک در لبه؛ پر کردن کل سطح لازم نیست."}, {"title": "فشار و گیره", "body": "بعد از بستن با کش یا گیره، ۱-۲ ساعت فشار یکنواخت."}, {"title": "پاک‌سازی اضافه", "body": "قبل از خشک شدن با دستمال الکلی اضافه‌ها را بگیرید."}, {"title": "انتخاب درست", "body": "برای آب‌بندی، چسب/واشر مخصوص؛ برای قطعات داخلی، چسب دوطرفهٔ نازک."}]','چسب B-7000، دستمال بدون پرز، الکل، گیره','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','free',0,'public','published','عمومی,چسب,مونتاژ,تعمیرگاه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-01 01:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'چسب B-7000 و مونتاژ تمیز — چطور بدون لکه و لبهٔ باز ببندیم');

