SELECT @bk_author,@bk_cat,'کدهای سرویس اندروید — تست سخت‌افزاری بدون نرم‌افزار','*#0*# سامسونگ و *#*#64663#*#* شیائومی؛ با این منوها تاچ، سنسور، دوربین و بلندگو را تست کنید.','هر سازنده منوی تست مخفی دارد. این منوها برای عیب‌یابی سریع و اثبات خرابی به مشتری فوق‌العاده کاربردی‌اند.','گوشی‌های اندروید','عمومی','','','کد سرویس','easy','[{"title": "سامسونگ", "body": "*#0*# در شماره‌گیر › منوی کامل سنسور/تاچ/دوربین."}, {"title": "شیائومی", "body": "*#*#64663#*#* › تست اجزای کامل (CIT)."}, {"title": "هواوی/آنر", "body": "در بعضی مدل‌ها *#*#2846579#*#* منوی ProjectMenu."}, {"title": "گزارش‌گیری", "body": "نتیجهٔ هر تست را قبل از باز کردن گوشی ثبت کنید تا خطای قبل تعمیر مشخص باشد."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','عمومی,کد سرویس,تست',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-01 02:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'کدهای سرویس اندروید — تست سخت‌افزاری بدون نرم‌افزار');

