SELECT @bk_author,@bk_cat,'قطب‌نما، شتاب‌سنج و چرخش صفحه کار نمی‌کنند','سنسورهای حرکتی معمولاً با کالیبراسیون درست می‌شوند؛ خاموشی خودکار چرخش هم رایج است.','سنسور مغناطیسی (قطب‌نما) با میدان‌های مزاحم (آهنربای قاب، کلاه موبایل) کالیبره‌اش به هم می‌ریزد.','همهٔ گوشی‌ها','عمومی','','','سنسورها','easy','[{"title": "روشن کردن Auto-rotate", "body": "نوار اعلان › چرخش خودکار روشن."}, {"title": "کالیبراسیون قطب‌نما", "body": "اپ قطب‌نما را باز و گوشی را به شکل ۸ در هوا بچرخانید."}, {"title": "حذف مزاحم‌ها", "body": "قاب آهنربادار و پایه‌های مغناطیسی برداشته شوند."}, {"title": "تست کد سرویس", "body": "در منوی تست سازنده، سنسورها را جداگانه چک کنید؛ خرابی واقعی = تعویض فلکس سنسور."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','عمومی,سنسور,کالیبراسیون',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-01 05:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'قطب‌نما، شتاب‌سنج و چرخش صفحه کار نمی‌کنند');

