SELECT @bk_author,@bk_cat,'تابستان: گوشی در ماشین و آفتاب — چرا خطرناک است و چطور جلوگیری کنیم','دمای داشبورد ماشین در آفتاب تا ۸۰ درجه می‌رسد؛ باتری و پنل از این گرما آسیب دائمی می‌بینند.','باتری لیتیومی بالای ۴۵ درجه فرسایش سریع دارد و ممکن است متورم شود؛ پنل OLED هم لکه و سوختگی می‌گیرد.','همهٔ گوشی‌ها','عمومی','','','تابستان و گرما','easy','[{"title": "هرگز داشبورد نه", "body": "گوشی در جیب در، کف ماشین یا سایه."}, {"title": "قاب در گرمای شدید", "body": "قاب ضخیم حین گرما برداشته شود."}, {"title": "شارژ در سایه", "body": "شارژ حین آفتاب مستقیم دما را به سقف می‌رساند."}, {"title": "اگر داغ شد", "body": "در سایه/کولر بگذارید و تا خنک شدن استفاده نکنید؛ یخچال و فریزر ممنوع (تقطیر رطوبت)."}]','','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','like',0,'public','published','عمومی,گرما,تابستان',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-01 09:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تابستان: گوشی در ماشین و آفتاب — چرا خطرناک است و چطور جلوگیری کنیم');

