SELECT @bk_author,@bk_cat,'بعد از ساحل: شن و آب شور، قاتل خاموش پورت و اسپیکر','آب شور خورنده است؛ شست‌وشو با آب معمولی (فقط بیرون) و تمیزکاری سریع پورت لازم است.','نمک بعد از تبخیر آب، کریستال‌های خورنده می‌سازد که پورت و اتصالات را می‌خورند. گوشی‌های ضدآب هم در برابر آب شور تضمین ندارند.','همهٔ گوشی‌ها','عمومی','','','شن و ماسه','medium','[{"title": "خاموشی و خشک اولیه", "body": "مثل آب‌خوردگی معمولی."}, {"title": "شست‌وشوی بیرونی با آب شیرین", "body": "فقط سطح بیرونی و به‌صورت چکه؛ فشار هوا/آب ممنوع."}, {"title": "تمیزکاری پورت و اسپیکر", "body": "بعد از خشک شدن کامل، پرز/شن با برس نرم."}, {"title": "تعمیرگاه در صورت نشتی", "body": "اگر داخل آب رفته، شست‌وشوی برد حرفه‌ای ضروری است."}]','','["/uploads/tips/gen/phone-in-rice.jpg", "/uploads/tips/gen/wet-usb-port.jpg"]','','[]','free',0,'public','published','عمومی,ساحل,آب شور',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-01 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بعد از ساحل: شن و آب شور، قاتل خاموش پورت و اسپیکر');

