SELECT @bk_author,@bk_cat,'استفاده از گوشی در حمام و کنار استخر — ریسک‌ها و محافظت','بخار حمام به‌تنهایی معمولاً بی‌ضرر است ولی چکه و افتادن تراژدی می‌سازد؛ درپوش پورت و دقت کافی است.','درجهٔ IP فقط برای شرایط آزمایشگاهی است. قطره در حالت اسپلش معمولاً تحمل می‌شود ولی غوطه‌وری کوتاه هم می‌تواند نشتی ایجاد کند مخصوصاً گوشی‌های تعمیرشده.','همهٔ گوشی‌ها','عمومی','','','رطوبت حمام','easy','[{"title": "درپوش سیلیکونی پورت", "body": "برای گوشی‌های تعمیرشده یا بدون IP توصیه می‌شود."}, {"title": "دور از لبهٔ استخر", "body": "گوشی را روی حوله/طاقه نگه دارید نه لبهٔ سنگ."}, {"title": "بعد از حمام", "body": "پورت را خشک کنید؛ رطوبت باقی‌مانده پیام شارژ را می‌آورد."}, {"title": "اگر خیس شد", "body": "خاموش، خشک، صبر؛ طبق قلق آب‌خوردگی."}]','','["/uploads/tips/gen/wet-usb-port.jpg", "/uploads/tips/gen/phone-in-rice.jpg"]','','[]','free',0,'public','published','عمومی,رطوبت,حمام',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-01 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'استفاده از گوشی در حمام و کنار استخر — ریسک‌ها و محافظت');

