SELECT @bk_author,@bk_cat,'صدای اسپیکر بعد از رطوبت گرفته شد — اپ‌های تخلیهٔ صدا','صدای سینوسی ~۱۶۵ هرتز، قطره‌های داخل اسپیکر را با ارتعاش بیرون می‌پرانند.','سامسونگ و اپل قابلیت داخلی تخلیهٔ آب دارند؛ برای بقیهٔ گوشی‌ها اپ‌های رایگان همین کار را می‌کنند.','همهٔ گوشی‌ها','عمومی','','','اسپیکر رطوبت','easy','[{"title": "اپ Speaker Cleaner", "body": "اپ‌های معتبر تخلیهٔ صدا را نصب و چند چرخه اجرا کنید."}, {"title": "تکرار چرخه‌ها", "body": "چند بار پشت‌سرهم اجرا کنید تا صدای «جیرجیر» قطره‌ها تمام شود."}, {"title": "صبر", "body": "رطوبت جزئی طی چند ساعت خودش تبخیر می‌شود."}, {"title": "تعمیر", "body": "اگر خش و لرزش ماند، پارچهٔ ضدآب اسپیکر آسیب دیده و ماژول تعویض می‌شود."}]','','["/uploads/tips/gen/speaker-mesh-macro.jpg"]','','[]','free',0,'public','published','عمومی,اسپیکر,رطوبت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-01 17:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'صدای اسپیکر بعد از رطوبت گرفته شد — اپ‌های تخلیهٔ صدا');

