SELECT @bk_author,@bk_cat,'شارژ در خودرو — USB خودرو یا آداپتور ۱۲ ولت؟','پورت USB خودرو معمولاً ۰.۵ آمپر می‌دهد و فقط «نگه‌داشتن» شارژ است؛ برای شارژ واقعی آداپتور ۱۲ ولت باکیفیت بگیرید.','خروجی ضعیف پورت خودرو باعث می‌شود گوشی حین ناوبری شارژ از دست بدهد. آداپتور خودروی PD با کیفیت، سرعت واقعی می‌دهد.','همهٔ گوشی‌ها','عمومی','','','شارژ خودرو','easy','[{"title": "آداپتور PD ۱۸-۳۰ وات خودرویی", "body": "از برند معتبر."}, {"title": "کابل سالم", "body": "کابل کوتاه‌تر افت ولتاژ کمتری دارد."}, {"title": "پرهیز از پاور مستقیم داغ", "body": "آداپتور را از نور مستقیم دور نگه دارید."}, {"title": "سیم‌کشی سالم", "body": "فندک سالم و فیوز درست؛ از اتصالات پیچی موقت پرهیز کنید."}]','','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','like',0,'public','published','عمومی,شارژ خودرو',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-01 22:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'شارژ در خودرو — USB خودرو یا آداپتور ۱۲ ولت؟');

