SELECT @bk_author,@bk_cat,'گوشی با ۱٪ شارژ خاموش می‌شود — کالیبراسیون متر باتری','متر درصد باتری با زمان کج می‌شود؛ یک چرخهٔ کامل شارژ/مصرف آن را منظم می‌کند.','سیستم ظرفیت را از منحنی یادگیری تخمین می‌زند؛ تغییر عادت مصرف یا فرسودگی، تخمین را خطادار می‌کند.','همهٔ گوشی‌ها','عمومی','','','خاموشی با ۱ درصد','easy','[{"title": "تخلیهٔ کامل", "body": "گوشی تا خاموشی کامل مصرف شود."}, {"title": "شارژ بی‌وقفه تا ۱۰۰٪", "body": "بدون استفاده و بدون قطع."}, {"title": "تکرار ماهانه", "body": "یک‌بار در ماه این چرخه کافی است."}, {"title": "اگر ادامه داشت", "body": "باتری فرسوده است؛ تعویض."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg"]','','[]','free',0,'public','published','عمومی,کالیبراسیون,باتری',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-01 23:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'گوشی با ۱٪ شارژ خاموش می‌شود — کالیبراسیون متر باتری');

