SELECT @bk_author,@bk_cat,'درپوش سیلیکونی پورت — ارزان‌ترین بیمهٔ گوشی','گردوغبار جیب و پرز، پورت را می‌گیرند؛ درپوش کوچک سیلیکونی سال‌ها پورت را سالم نگه می‌دارد.','مخصوصاً برای گوشی‌های تعمیرشدهٔ پورت، کارگران ساختمان و محیط‌های گردوخاکی، این قطعهٔ چند هزار تومانی تعویض پورت را به تأخیر می‌اندازد.','همهٔ گوشی‌ها','عمومی','','','محافظ پورت','easy','[{"title": "خرید درپوش مناسب مدل", "body": "سایز Type-C یا microUSB گوشی."}, {"title": "نصب", "body": "کامل و محکم؛ نباید آزاد بماند."}, {"title": "نظافت دوره‌ای", "body": "هر چند ماه درپوش و پورت تمیز شود."}, {"title": "مورد بی‌نیاز", "body": "اگر گوشی IP68 اصل و کم‌استفاده است، لزومی ندارد."}]','','["/uploads/tips/gen/wet-usb-port.jpg"]','','[]','free',0,'public','published','عمومی,محافظ,پورت',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-02 03:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'درپوش سیلیکونی پورت — ارزان‌ترین بیمهٔ گوشی');

