SELECT @bk_author,@bk_cat,'بوی سوختگی یا لکهٔ سوخت روی برد — تشخیص و اقدام','بوی سوختگی یعنی اتصال کوتاه فعال است؛ باتری را جدا و به تعمیر برد تخصصی برسانید.','قطعهٔ سوخته معمولاً IC شارژ، Power IC یا مسیر باتری است. روشن کردن مجدد گوشی سوخته، آسیب را گسترده‌تر می‌کند.','همهٔ گوشی‌ها','عمومی','','','بوی سوختگی','hard','[{"title": "خاموشی فوری", "body": "و توقف هر تلاش برای روشن کردن."}, {"title": "بازدید چشمی", "body": "در تعمیرگاه، ناحیهٔ سوخته/سیاه‌شده پیدا می‌شود."}, {"title": "قطع مسیر معیوب", "body": "IC سوخته برداشته و مسیر سیم‌کشی/جایگزین می‌شود."}, {"title": "هزینهٔ واقع‌بینانه", "body": "تعمیر برد سوخته گاهی از ارزش گوشی بیشتر است؛ قبل از شروع مشورت کنید."}]','','["/uploads/tips/mobile/board-under-microscope.jpg", "/uploads/tips/gen/esd-workspace.jpg"]','','[]','free',0,'public','published','عمومی,سوختگی,برد',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-02 05:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بوی سوختگی یا لکهٔ سوخت روی برد — تشخیص و اقدام');

