SELECT @bk_author,@bk_cat,'نوسان برق و شارژ — چرا شارژر ارزان خطرناک است','شارژرهای بی‌کیفیت در نوسان برق، ولتاژ غیرایمن به گوشی می‌دهند؛ IC شارژ و باتری قربانی اول‌اند.','آداپتور استاندارد با ایزولاسیون و مدار حفاظتی می‌آید؛ نمونه‌های تقلبی فقط ترانس کوچک و مقاومت‌اند.','همهٔ گوشی‌ها','عمومی','','','نوسان برق','easy','[{"title": "شارژر دارای نشان استاندارد", "body": "CE/FCC و برند معتبر؛ سبک‌وزنِ عجیب هشدار است."}, {"title": "محافظ نوسان", "body": "در ساختمان‌های پرنوسان، از محافظ/محافظ اضافه‌ولتاژ استفاده کنید."}, {"title": "نشانه‌های خرابی", "body": "داغی آداپتور، بوی پلاستیک و صدای وزوز = قطع فوری."}, {"title": "پیامد بی‌کیفیتی", "body": "سوختن IC شارژ گوشی هزینه‌ای چند برابر شارژر است."}]','','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','like',0,'public','published','عمومی,شارژر,نوسان برق',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-02 08:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'نوسان برق و شارژ — چرا شارژر ارزان خطرناک است');

