SELECT @bk_author,@bk_cat,'تعمیر یا تعویض؟ جدول تصمیم اقتصادی برای گوشی آسیب‌دیده','هزینهٔ تعمیر بالای ~۴۰-۵۰٪ ارزش فعلی گوشی، معمولاً به نفع تعویض است.','برای تصمیم درست، ارزش بازار فعلی گوشی و هزینهٔ تعمیر را مقایسه کنید؛ سن گوشی و هزینهٔ قطعات آینده را هم لحاظ کنید.','همهٔ گوشی‌ها','عمومی','','','تصمیم اقتصادی تعمیر','medium','[{"title": "ارزش فعلی", "body": "قیمت فروش دست دوم گوشی سالم را ببینید."}, {"title": "هزینهٔ تعمیر", "body": "مشاورهٔ تعمیرگاه برای تعمیر کامل."}, {"title": "قاعدهٔ ۵۰٪", "body": "تعمیر بیش از نصف ارزش = تعویض منطقی‌تر."}, {"title": "استثناها", "body": "گوشی با داده/نسبت عاطفی یا تعمیر جزئی ارزان، استثنا هستند."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','عمومی,تصمیم,هزینه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-02 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تعمیر یا تعویض؟ جدول تصمیم اقتصادی برای گوشی آسیب‌دیده');

