SELECT @bk_author,@bk_cat,'لیست ابزار پایه برای شروع تعمیر موبایل در خانه','ست پیچ‌گوشتی دقیق، پیک، ساکشن، پنس، الکل و مات؛ با کمتر از هزینهٔ یک تعویض صفحه، شروع کنید.','شروع تعمیر در خانه با ابزار پایه ممکن است؛ ولی تعمیرات برد و آب‌بندی حرفه‌ای، تجهیزات خاص می‌خواهند. از باتری و پورت شروع کنید.','تعمیرگاه','عمومی','','','ابزار پایه','medium','[{"title": "ست پیچ‌گوشتی دقیق", "body": "فیلیپس ۰۰۰، تورکس، پنتالوب، Y000."}, {"title": "بازکننده‌ها", "body": "ساکشن، پیک پلاستیکی، اسپاتجر، کارت."}, {"title": "مصرفی", "body": "الکل ایزوپروپیل، دستمال بدون پرز، چسب دوطرفه، واشر."}, {"title": "ایمنی و سازماندهی", "body": "مات پیچ، مچ‌بند آنتی‌استاتیک و نور خوب."}]','ست پیچ‌گوشتی، ساکشن، پیک، پنس، الکل، مات ESD','["/uploads/tips/gen/esd-workspace.jpg", "/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','عمومی,ابزار,تازه‌کار',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-02 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'لیست ابزار پایه برای شروع تعمیر موبایل در خانه');

