SELECT @bk_author,@bk_cat,'کی تعمیر برد با میکروسکوپ لازم است؟ مرز تعمیرکار عمومی و بوردی','مشکلات IC شارژ، وای‌فای، صدا و ریستارت‌های علت‌ناشناخته = قلمرو بوردی‌ها.','تعمیرکار عمومی ماژول‌ها را عوض می‌کند؛ بوردی زیر میکروسکوپ لحیم، مسیر و IC کار می‌کند. دانستن این مرز، وقت و پول مشتری را حفظ می‌کند.','تعمیرگاه','عمومی','','','میکروسکوپ','medium','[{"title": "مشکلات ماژولی", "body": "نمایشگر، باتری، پورت، دوربین = عمومی."}, {"title": "مشکلات بردی", "body": "شارژ نشدن با فلکس سالم، وای‌فای خاکستری، ریستارت = بورد."}, {"title": "ابزار بوردی", "body": "میکروسکوپ، هیتر برد، پاور ساپلای، مولتی‌متر، هات ایر."}, {"title": "همکاری دو تعمیرکار", "body": "تعمیرگاه عمومی + بوردی، سرویس کامل به مشتری می‌دهد."}]','میکروسکوپ، هات‌ایر، پاور ساپلای، مولتی‌متر','["/uploads/tips/mobile/board-under-microscope.jpg", "/uploads/tips/mobile/board-under-microscope.jpg"]','','[]','free',0,'public','published','عمومی,تعمیر برد,میکروسکوپ',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-02 19:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'کی تعمیر برد با میکروسکوپ لازم است؟ مرز تعمیرکار عمومی و بوردی');

