SELECT @bk_author,@bk_cat,'گوشی خم شده (خمیدگی قاب) — صاف‌کاری و پیامدهایش','قاب آلومینیومی با سیم‌بول صاف می‌شود ولی نمایشگر و اتصالات ممکن است آسیب دیده باشند؛ کامل چک کنید.','خمش قاب، پنل را زیر کشش می‌گذارد (گوست تاچ) و لحیم‌های BGA را استرس می‌دهد. صاف‌کاری بدون تست کامل کافی نیست.','همهٔ گوشی‌ها','عمومی','','','بدنه خمیده','hard','[{"title": "اندازه‌گیری خمش", "body": "روی سطح صاف؛ اختلاف بیش از نیم‌میلی‌متر محسوس است."}, {"title": "صاف‌کاری با سیم‌بول", "body": "فقط توسط تعمیرگاه مجهز؛ روش‌های خانگی (کتاب و وزنه) نتیجهٔ نامطمئن دارد."}, {"title": "تست قطعات", "body": "نمایشگر، فلکس‌ها و ماژول‌ها بعد از صاف‌کاری تست شوند."}, {"title": "تعمیرات تکمیلی", "body": "پنل آسیب‌دیده یا لحیم‌های استرس‌خورده تعمیر شوند."}]','سیم‌بول، خط‌کش فولادی، میکروسکوپ','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','like',0,'public','published','عمومی,خمش,صاف‌کاری',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-02 21:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'گوشی خم شده (خمیدگی قاب) — صاف‌کاری و پیامدهایش');

