SELECT @bk_author,@bk_cat,'گارانتی تعمیر — چه چیزی باید از تعمیرگاه بخواهید؟','فاکتور با شرح تعمیر، ضمانت قطعه و کار، و تحویل قطعات تعویضی حق شماست.','مصرف‌کنندهٔ آگاه، خدمات بهتری می‌گیرد. قبل از تحویل گوشی، شرح کار و قیمت را شفاهی و کتبی بگیرید.','همهٔ گوشی‌ها','عمومی','','','حقوق مشتری','easy','[{"title": "شرح کار کتبی", "body": "روی رسید: قطعهٔ تعویضی، قیمت، مدت ضمانت."}, {"title": "ضمانت استاندارد", "body": "پنل و باتری معمولاً ۳ تا ۶ ماه ضمانت دارند."}, {"title": "قطعات تعویضی", "body": "درخواست تحویل قطعهٔ قدیمی حق شماست."}, {"title": "مرجوعی", "body": "اگر مشکل اولیه بعد از تعمیر برگشت، با رسید ضمانت مراجعه کنید."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','عمومی,گارانتی,مصرف‌کننده',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-03 02:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'گارانتی تعمیر — چه چیزی باید از تعمیرگاه بخواهید؟');

