SELECT @bk_author,@bk_cat,'شارژ فوق‌سریع (VOOC/SuperVOOC/Warp) کار نمی‌کند — چرا فقط با اصلش جواب می‌دهد','پروتکل‌های شارژ سریع اختصاصی، مذاکرهٔ دقیق بین شارژر و گوشی می‌خواهند؛ کابل موبایل-کوتاه هم شرط است.','شارژرهای ۶۵-۱۵۰ واتی، فرمان‌های پروتکل اختصاصی با کابل مخصوص ۶+ رشته‌ای می‌فرستند. کابل معمولی، سرعت را به ۱۸ وات محدود می‌کند.','OnePlus و گوشی‌های شارژ سریع','عمومی','','','شارژ سریع از کار افتاد','easy','[{"title": "ست اصل کامل", "body": "آداپتور اصل + کابل اصل همان برند."}, {"title": "تمیزکاری پورت", "body": "خلال و برس؛ گلوگاه تماس سرعت را می‌بُرد."}, {"title": "دمای گوشی", "body": "در گرما شارژ سریع خودکار محدود می‌شود."}, {"title": "بررسی فلکس", "body": "اگر همه سالم بود و سرعت نیامد، فلکس پورت تعویض شود."}]','','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','free',0,'public','published','عمومی,شارژ سریع,VOOC',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-03 05:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'شارژ فوق‌سریع (VOOC/SuperVOOC/Warp) کار نمی‌کند — چرا فقط با اصلش جواب می‌دهد');

