SELECT @bk_author,@bk_cat,'Sony Xperia — مشکلات رایج نمایشگر LCD و تعویض','LCD اکسپریا گاهی خطوط و لمس‌ناپذیری بعد از ضربه می‌دهد؛ پنل‌هایش جدا از دیجیتایزر هم موجود است.','برخی مدل‌های اکسپریا، پنل و تاچ را جداگانه می‌فروشند؛ اگر فقط تاچ خراب است، هزینه کمتر می‌شود.','Sony Xperia','عمومی','','','نمایشگر LCD','medium','[{"title": "تشخیص سطح خرابی", "body": "تصویر سالم + تاچ خراب = فقط دیجیتایزر."}, {"title": "تعویض لایه تاچ", "body": "در مدل‌های سازگار، تاچ جداگانه تعویض می‌شود."}, {"title": "تعویض پنل کامل", "body": "در صورت خرابی تصویر، پنل کامل."}, {"title": "تست تاچ", "body": "اپ تست لمس تمام صفحه را بپوشانید."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','عمومی,Xperia,LCD',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-03 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'Sony Xperia — مشکلات رایج نمایشگر LCD و تعویض');

