SELECT @bk_author,@bk_cat,'Nokia با Android One — چرا کند شده و چطور سبکش کنیم','گوشی‌های حافظهٔ کم (۲-۴ گیگ) با اپ‌های سنگین امروز له می‌شوند؛ نسخهٔ سبک اپ‌ها را نصب کنید.','Android One سبک است ولی RAM کم گلوگاه است. اپ‌های Go/نسخهٔ Lite و محدود کردن پس‌زمینه، تجربه را قابل قبول می‌کند.','Nokia و گوشی‌های سبک','عمومی','','','کندی نرم‌افزاری','easy','[{"title": "اپ‌های Lite/Go", "body": "نسخه‌های سبک گوگل و پیام‌رسان‌ها."}, {"title": "حذف اپ‌های سنگین", "body": "فیس‌بوک کامل به‌جای خودش، نسخهٔ Lite."}, {"title": "محدودسازی پس‌زمینه", "body": "مصرف پس‌زمینه اپ‌ها را ببندید."}, {"title": "ریست کارخانه سالانه", "body": "با بکاپ؛ سیستم انباشته را تازه می‌کند."}]','','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','free',0,'public','published','عمومی,Nokia,کندی',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-03 15:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'Nokia با Android One — چرا کند شده و چطور سبکش کنیم');

