SELECT @bk_author,@bk_cat,'تبلت‌ها: تعویض باتری تبلت سامسونگ/آیپد چه فرقی با گوشی دارد','تبلت‌ها باتری بزرگ‌تر با چسب بیشتر دارند؛ ابزار مشابه ولی صبوری بیشتر لازم است.','باتری تبلت‌ها چند سلولی و بزرگ‌اند و گاهی با چسب کشیده شده‌اند. اصول ایمنی همان باتری گوشی است با سطح بزرگ‌تر ریسک.','تبلت','عمومی','','','باتری تبلت','medium','[{"title": "باز کردن پنل", "body": "با هیتر و پیک؛ تبلت‌ها لبهٔ باریکی دارند."}, {"title": "خروج سلولی", "body": "باتری‌های چندسلولی را سلول‌به‌سلول با الکل جدا کنید."}, {"title": "قطعهٔ مدل‌دقیق", "body": "باتری تبلت مدل‌محور است؛ کد باتری روی خودش را ببینید."}, {"title": "تست و بستن", "body": "شارژدهی و شارژ تست؛ چسب/واشر نو."}]','','["/uploads/tips/mobile/open-iphone-repair.jpg", "/uploads/tips/gen/heat-gun-backcover.jpg"]','','[]','free',0,'public','published','عمومی,تبلت,باتری',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-03 18:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تبلت‌ها: تعویض باتری تبلت سامسونگ/آیپد چه فرقی با گوشی دارد');

