SELECT @bk_author,@bk_cat,'آیپد شارژ نمی‌شود — شارژر قوی لازم است','آیپدها با شارژر ۱۰ وات موبایل به‌سختی شارژ می‌شوند؛ آداپتور ۲۰-۳۰ وات لازم است.','بسیاری فکر می‌کنند آیپد خراب شده در حالی که شارژر موبایل برایش کافی نیست. پورت USB-C/لایتنینگ آیپد هم مثل موبایل پرز می‌گیرد.','آیپد','عمومی','','','شارژ نمی‌شود','medium','[{"title": "آداپتور ۲۰ وات به بالا", "body": "شارژر آیفون اصل برای آیپد ضعیف است."}, {"title": "تمیزکاری پورت", "body": "پرز جیب در آیپد هم رایج است."}, {"title": "کابل بزرگ‌تر", "body": "کابل‌های آیپد سیم‌بندی قوی‌تری می‌خواهند؛ کابل موبایل گرم می‌شود."}, {"title": "تست روشن/خاموش", "body": "اگر با آداپتور قوی هم شارژ نشد، فلکس پورت یا مدار شارژ بررسی شود."}]','','["/uploads/tips/gen/charger-and-cable.jpg"]','','[]','like',0,'public','published','عمومی,آیپد,شارژ',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-03 22:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'آیپد شارژ نمی‌شود — شارژر قوی لازم است');

