SELECT @bk_author,@bk_cat,'تست قطعات قبل از نصب — قانون طلایی تعمیرکار حرفه‌ای','باتری با مولتی‌متر، پنل با اتصال آزمایشی، فلکس با بازرسی چشمی؛ قبل از چسب و بستن کامل، همه‌چیز تست شود.','نصب کامل و چسب زدن، برگشت قطعهٔ معیوب را غیرممکن می‌کند. تست قبل از بستن، دوبرابر سرعت کار و اعتبار شما را نگه می‌دارد.','همهٔ گوشی‌ها','عمومی','','','قطعات بازار','medium','[{"title": "باتری", "body": "ولتاژ سالم (۳.۷-۴.۲) و بدون تورم؛ قاب پلاستیکی سالم."}, {"title": "پنل", "body": "تست اتصال موقت: تاچ، رنگ، روشنایی، سنسورها."}, {"title": "فلکس‌ها", "body": "اتصال‌ها و پین‌ها زیر نور بازرسی."}, {"title": "قانون کلی", "body": "هرگز قبل از تست کامل، چسب نزنید و گوشی را کامل نبندید."}]','','["/uploads/tips/gen/screws-organization-mat.jpg", "/uploads/tips/gen/esd-workspace.jpg"]','','[]','free',0,'public','published','عمومی,تست قطعه,تعمیرگاه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-04 01:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تست قطعات قبل از نصب — قانون طلایی تعمیرکار حرفه‌ای');

