SELECT @bk_author,@bk_cat,'تشخیص اتصال کوتاه با دوربین حرارتی — ترفند بوردی‌ها','برد روشن با پاور محدود؛ قطعهٔ داغ در تصویر حرارتی، مقصر اتصال کوتاه را لو می‌دهد.','در تعمیر برد، پیدا کردن قطعهٔ اتصال‌کوتاه‌شده سخت است؛ دوربین حرارتی یا اسپری یخ‌زننده، قطعهٔ داغ را نشان می‌دهد.','تعمیرگاه','عمومی','','','دوربین حرارتی','medium','[{"title": "تزریق ولتاژ محدود", "body": "پاور ساپلای روی ولتاژ باتری با جریان محدود."}, {"title": "تصویر حرارتی", "body": "قطعه‌ای که سریع‌تر گرم می‌شود، نشتی می‌کشد."}, {"title": "برداشتن قطعه", "body": "IC مشکوک با هات‌ایر برداشته و تست مجدد."}, {"title": "جایگزینی", "body": "IC سالم نصب یا مسیر سیم‌کشی موقت (Jumper) انجام شود."}]','دوربین حرارتی، پاور ساپلای، هات‌ایر','["/uploads/tips/mobile/board-under-microscope.jpg", "/uploads/tips/gen/esd-workspace.jpg"]','','[]','paid',55000,'public','published','عمومی,برد,دوربین حرارتی',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-04 03:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'تشخیص اتصال کوتاه با دوربین حرارتی — ترفند بوردی‌ها');

