SELECT @bk_author,@bk_cat,'بعد از تعمیر سیگنال ضعیف شد — فلز فراموش‌شده و آنتن‌های روی قاب','خیلی از آنتن‌ها فویل/مس روی قاب و درپوش‌اند؛ جابجایی یا ماندن قطعهٔ فلزی، سیگنال را می‌کُشد.','وای‌فای، NFC و آنتن سلولی اغلب روی درب پشت یا قاب میانی هستند. تعمیرکار تازه‌کار با جابجایی فویل، مشکل جدید می‌سازد.','همهٔ گوشی‌ها','عمومی','','','آنتن‌ها بعد تعمیر','medium','[{"title": "تست قبل از بستن", "body": "سیگنال، وای‌فای و NFC را قبل از چسب نهایی تست کنید."}, {"title": "بازرسی فویل‌ها", "body": "فویل‌های آنتن و اتصالات پین به‌جا و تمیز باشند."}, {"title": "پیچ‌های زمین", "body": "پیچ‌های فلزی با واشر، مسیر زمین آنتن را می‌سازند؛ کامل ببندید."}, {"title": "تست نهایی جیب", "body": "گاهی فقط در دست، سیگنال ضعیف است؛ تست در موقعیت واقعی."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','عمومی,آنتن,تعمیرگاه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-04 06:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'بعد از تعمیر سیگنال ضعیف شد — فلز فراموش‌شده و آنتن‌های روی قاب');

