SELECT @bk_author,@bk_cat,'دکمهٔ پاور/صدا گیر کرده یا بی‌پاسخ','گیر کردن دکمه معمولاً از گردوغبار زیر سوئیچ است؛ تمیزکاری یا تعویض سوئیچ فلکسی.','سوئیچ‌های دکمه روی فلکس‌های جانبی هستند و تعویضشان با باز کردن گوشی و گاهی جوش انجام می‌شود.','همهٔ گوشی‌ها','عمومی','','','دکمه‌ها','medium','[{"title": "تمیزکاری بیرونی", "body": "الکل روی لبهٔ دکمه و فشار مکرر؛ غبار سطحی را می‌برد."}, {"title": "تست با کد سرویس", "body": "تست دکمه‌ها در منوی تست سازنده."}, {"title": "باز کردن و بازرسی", "body": "فلکس دکمه، سوئیچ و پین‌ها."}, {"title": "تعویض سوئیچ/فلکس", "body": "سوئیچ نو با هویه یا فلکس کامل نو."}]','الکل، برس نرم، هویهٔ ریز، سوئیچ یدک','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','like',0,'public','published','عمومی,دکمه,پاور',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-04 10:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'دکمهٔ پاور/صدا گیر کرده یا بی‌پاسخ');

