SELECT @bk_author,@bk_cat,'هدفون سیمی صدا نمی‌دهد — جک ۳.۵ میلی‌متری','گردوغبار جک یا سوزن فلزی خم‌شده، رایج‌ترین علت‌اند؛ تمیزکاری، تست هدفون دیگر و تعویض فلکس.','خیلی‌ها با خلال دندان یا سیم داخل جک را خراب می‌کنند. تمیزکاری با پنبهٔ نازک و الکل، امن است.','گوشی‌های دارای جک ۳.۵','عمومی','','','جک هدفون','easy','[{"title": "تست با هدفون دیگر", "body": "اول مطمئن شوید مشکل از گوشی است نه هدفون."}, {"title": "تمیزکاری جک", "body": "پنبهٔ نازک الکلی یا مکش ملایم؛ فلز وارد نکنید."}, {"title": "بررسی سوئیچ بلوتوث", "body": "اگر هدفون بلوتوثی وصل است، مسیر صدا رفته آنجا."}, {"title": "تعویض فلکس جک", "body": "فلکس جک (و بعضاً میکروفون) نو نصب شود."}]','','["/uploads/tips/gen/speaker-mesh-macro.jpg"]','','[]','free',0,'public','published','عمومی,جک,هدفون',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-04 13:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'هدفون سیمی صدا نمی‌دهد — جک ۳.۵ میلی‌متری');

