SELECT @bk_author,@bk_cat,'کارت microSD شناسایی نمی‌شود یا فایل‌ها ناپدید می‌شوند','کارت‌های تقلبی و فرسوده رایج‌اند؛ تست در دستگاه دیگر، تعمیر فایل‌سیستم و تعویض کارت.','کارت‌های تقلبی ظرفیت دروغین دارند و داده را خراب می‌کنند. خرید از فروشندهٔ معتبر با تست ظرفیت (h2testw) ضروری است.','گوشی‌های اندروید','عمومی','','','کارت حافظه','easy','[{"title": "تست متقاطع", "body": "کارت در دستگاه دیگر و کارت دیگر در گوشی."}, {"title": "تعمیر فایل‌سیستم", "body": "در کامپیوتر با ابزارهای chk/فرمت FAT32/exFAT."}, {"title": "نکتهٔ سرعت", "body": "کارت کلاس پایین، ضبط ویدیو را مختل می‌کند؛ U3/V30 برای ویدیو."}, {"title": "تعویض", "body": "کارت فرسوده را تعویض و از آن بکاپ نگیرید."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','عمومی,microSD,حافظه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-04 16:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'کارت microSD شناسایی نمی‌شود یا فایل‌ها ناپدید می‌شوند');

