SELECT @bk_author,@bk_cat,'Wipe Cache از Recovery — راه‌حل کم‌هزینهٔ هنگ و کندی','پاک کردن پارتیشن کش، بدون حذف داده‌ها، مشکلات انباشتهٔ سیستم را کم می‌کند.','کش سیستم و اپ‌ها گاهی خراب می‌شود و هنگ/کندی می‌سازد. Wipe Cache partition در Recovery بدون از دست رفتن داده انجام می‌شود.','گوشی‌های اندروید','عمومی','','','پاک کردن کش','easy','[{"title": "ورود به Recovery", "body": "ترکیب دکمهٔ سازنده (معمولاً Volume بالا + Power)."}, {"title": "Wipe Cache Partition", "body": "با Volume جابجا و با Power تأیید."}, {"title": "Reboot", "body": "گوشی را ریبوت کنید؛ بوت اول کمی طول می‌کشد."}, {"title": "اگر ادامه داشت", "body": "ریست کارخانه با بکاپ یا فلش رسمی."}]','','["/uploads/tips/gen/screws-organization-mat.jpg"]','','[]','free',0,'public','published','عمومی,کش,Recovery',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-04 17:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'Wipe Cache از Recovery — راه‌حل کم‌هزینهٔ هنگ و کندی');

