SELECT @bk_author,@bk_cat,'Safe Mode اندروید — تشخیص اپ مقصر در ۲ دقیقه','اگر در Safe Mode گوشی سالم است، یک اپ نصب‌شده مقصر است؛ به‌ترتیب حذف کنید.','Safe Mode فقط اپ‌های سیستمی را بار می‌کند. اگر مشکل (هنگ، داغی، تاچ خیالی، مصرف باتری) رفت، اپ ثالثی است.','گوشی‌های اندروید','عمومی','','','Safe Mode','easy','[{"title": "ورود به Safe Mode", "body": "دکمهٔ پاور را نگه دارید و آیکون خاموش کردن را لمس طولانی › Safe Mode."}, {"title": "تست مشکل", "body": "مشکل را در Safe بازتولید کنید."}, {"title": "حذف اپ‌های مشکوک", "body": "از آخرین نصب‌ها شروع کنید."}, {"title": "خروج", "body": "ریستارت معمولی از Safe خارج می‌شود."}]','','["/uploads/tips/gen/esd-workspace.jpg"]','','[]','like',0,'public','published','عمومی,Safe Mode,اپ',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-04 22:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'Safe Mode اندروید — تشخیص اپ مقصر در ۲ دقیقه');

