SELECT @bk_author,@bk_cat,'چک‌لیست خرید گوشی دست دوم — تست ۱۵ دقیقه‌ای سخت‌افزار','دوربین‌ها، تاچ کامل، شارژ، سنسورها، باتری، IMEI و وضعیت قطعات تعویضی را چک کنید.','بیشترین کلاهبرداری دست‌دوم در قطعات تعویضی بی‌کیفیت و مشکلات شارژ است. این چک‌لیست خرید مطمئن می‌دهد.','همهٔ گوشی‌ها','عمومی','','','خرید دست دوم','medium','[{"title": "شبکه و تماس", "body": "سیم‌کارت، تماس، میکروفون، اسپیکرفون."}, {"title": "تاچ و نمایشگر", "body": "اپ تست لمس؛ رنگ‌های سفید/مشکی برای لکه."}, {"title": "باتری و شارژ", "body": "شارژدهی، دمای شارژ، سلامت باتری."}, {"title": "IMEI و قطعات", "body": "*#06# با کارتن مطابقت؛ پنل/درب اصل بودن (لبه‌ها، پیچ‌ها)."}]','','["/uploads/tips/gen/charger-and-cable.jpg", "/uploads/tips/gen/cracked-display.jpg"]','','[]','free',0,'public','published','عمومی,خرید,دست دوم',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-05 01:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'چک‌لیست خرید گوشی دست دوم — تست ۱۵ دقیقه‌ای سخت‌افزار');

