SELECT @bk_author,@bk_cat,'محافظ صفحهٔ مناسب — گلس، TPU یا مات؟','گلس برای شکستن جای صفحه، TPU برای انعطاف و مات برای ضدبازتاب؛ کیفیت نصب مهم‌تر از نوع است.','محافظ بد نصب‌شده، تاچ را خراب می‌کند و حباب، سنسور را اغتشاش می‌دهد. برای پنل‌های خمیده، محافظ مخصوص Curved لازم است.','همهٔ گوشی‌ها','عمومی','','','محافظ صفحه','easy','[{"title": "گلس سخت", "body": "محافظت ضربه؛ برای کاربرد عمومی بهترین تعادل."}, {"title": "TPU نرم", "body": "لبه‌های خمیده و گوشی‌های Curved."}, {"title": "مات", "body": "ضدبازتاب و ضداثرانگشت؛ کمی وضوح را کم می‌کند."}, {"title": "نصب تمیز", "body": "محیط کم‌غبار؛ حباب = اغتشاش تاچ."}]','','["/uploads/tips/gen/cracked-display.jpg"]','','[]','paid',45000,'public','published','عمومی,محافظ,گلس',1,NULL,1,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-05 06:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'محافظ صفحهٔ مناسب — گلس، TPU یا مات؟');

