SELECT @bk_author,@bk_cat,'عکس‌برداری قبل و حین تعمیر — حرفه‌ای‌گرایی و رفع اختلاف','عکس از وضعیت ورودی گوشی، پیچ‌ها و محل هر فلکس؛ هم رفع اختلاف می‌کند هم راهنمای مونتاژ است.','عکس قبل از باز کردن، خرابی‌های قبلی را مستند می‌کند و عکس‌های حین کار، مسیر مونتاژ را یادآوری می‌کنند.','تعمیرگاه','عمومی','','','مستندسازی تعمیر','easy','[{"title": "عکس ورودی", "body": "همهٔ وجه‌ها + خرابی‌ها؛ با تاریخ."}, {"title": "عکس حین باز کردن", "body": "هر مرحله: پیچ‌ها، فلکس‌ها، مات پیچ."}, {"title": "عکس قطعات تعویضی", "body": "قطعهٔ قدیمی و نو کنار هم."}, {"title": "بایگانی", "body": "با پروندهٔ مشتری ذخیره شود."}]','','["/uploads/tips/gen/screws-organization-mat.jpg", "/uploads/tips/gen/esd-workspace.jpg"]','','[]','like',0,'public','published','عمومی,مستندسازی,تعمیرگاه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-05 10:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'عکس‌برداری قبل و حین تعمیر — حرفه‌ای‌گرایی و رفع اختلاف');

