SELECT @bk_author,@bk_cat,'قبل از تعویض قطعه، سه سؤال بپرسید (روش تفکر تعمیرکار)','آیا قطعه قبلاً تست شد؟ آیا مشکل با قطعهٔ دیگر بازتولید می‌شود؟ آیا علت، رابطهٔ بین قطعات است؟','بخشی از «تعمیرهای پرهزینه» در واقع قطعه‌عوضی‌های زنجیره‌ای بی‌نتیجه است. تفکر سیستماتیک، هزینهٔ مشتری و وقت شما را نجات می‌دهد.','همهٔ گوشی‌ها','عمومی','','','تعویض قطعات بدون نیاز','easy','[{"title": "تست قطعهٔ مشکوک", "body": "قبل از تعویض، با تست کد سرویس یا جابجایی، خرابی را اثبات کنید."}, {"title": "بازتولید با قطعهٔ سالم", "body": "اگر با قطعهٔ سالم مشکل ماند، آن قطعه مقصر نبود."}, {"title": "نگاه به رابط‌ها", "body": "سوکت‌ها، فلکس‌ها و مسیر مشترک قطعات."}, {"title": "اعتراف به مرز تخصص", "body": "مشکلات برد را به متخصص برد ارجاع دهید."}]','','["/uploads/tips/gen/esd-workspace.jpg", "/uploads/tips/mobile/board-under-microscope.jpg"]','','[]','free',0,'public','published','عمومی,روش‌شناسی,تعمیرگاه',1,NULL,0,0,0,0,0,0,NULL,NULL,NULL,NULL,'2026-09-05 11:40:47' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tips WHERE title = 'قبل از تعویض قطعه، سه سؤال بپرسید (روش تفکر تعمیرکار)');
